export const CustomerOTPVerification: React.FC<
  CustomerOTPVerificationProps
> = ({ phoneNumber, onBack }) => {
  const router = useRouter();
  const [otp, setOtp] = useState("");
  const [error, setError] = useState<string | null>(null);
  const [timeLeft, setTimeLeft] = useState(30);
  const [canResend, setCanResend] = useState(false);
  const [isVerifying, setIsVerifying] = useState(false);
  const [isSuccess, setIsSuccess] = useState(false);
  const [redirectTarget, setRedirectTarget] = useState<string>("");
  const verificationInProgress = useRef(false);
  const redirectTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);

  const [verifyOTP, { isLoading }] = useVerifyOTPMutation();
  const [sendOTP, { isLoading: isResending }] = useSendOTPMutation();

  useEffect(() => {
    if (timeLeft <= 0) {
      setCanResend(true);
      return;
    }

    const timer = setTimeout(() => {
      setTimeLeft((prev) => prev - 1);
    }, 1000);

    return () => clearTimeout(timer);
  }, [timeLeft]);

  useEffect(() => {
    return () => {
      verificationInProgress.current = false;
      if (redirectTimerRef.current) {
        clearTimeout(redirectTimerRef.current);
      }
    };
  }, []);

  const handleVerifyOTP = async (otpValue: string) => {
    if (verificationInProgress.current || isVerifying || isLoading) {
      console.log("⚠️ Verification already in progress, skipping...");
      return;
    }

    if (!otpValue || otpValue.length !== 6) {
      setError("Please enter a valid 6-digit OTP");
      return;
    }

    console.log("🔵🔵🔵 SENDING OTP VERIFICATION REQUEST");
    console.log("📱 Phone:", phoneNumber);
    console.log("🔑 OTP:", otpValue);

    verificationInProgress.current = true;
    setIsVerifying(true);
    setError(null);

    try {
      const result = await verifyOTP({
        phone: phoneNumber,
        otp: otpValue,
      }).unwrap();

      console.log("✅ OTP verification API call successful:", result);

      if (result.status === true) {
        // ✅ Store phone number and temp token from response
        if (result.phone) {
          localStorage.setItem("verified_phone", result.phone);
          sessionStorage.setItem("verified_phone", result.phone);
          console.log("📱 Phone stored:", result.phone);
        }

        if (result.temp_token) {
          localStorage.setItem("temp_token", result.temp_token);
          sessionStorage.setItem("temp_token", result.temp_token);
          console.log("🔑 Temp token stored");
        }

        // ✅ Check if user needs registration
        if (result.requires_registration === true) {
          console.log("📝 New user - needs registration, redirecting to registration...");
          setRedirectTarget("registration");
          setIsSuccess(true);

          if (redirectTimerRef.current) {
            clearTimeout(redirectTimerRef.current);
          }

          redirectTimerRef.current = setTimeout(() => {
            const phoneToPass = result.phone || phoneNumber;
            router.push(`/auth/customer/register?phone=${encodeURIComponent(phoneToPass)}`);
          }, 1500);
        } else {
          // ✅ User is already registered - check token
          console.log("👤 Existing user - checking token...");

          // Check if token exists
          const token = TokenManager.getAccessToken();

          if (token) {
            console.log("🔑 Token found, redirecting to home page...");
            setRedirectTarget("home");
            setIsSuccess(true);

            if (redirectTimerRef.current) {
              clearTimeout(redirectTimerRef.current);
            }
            redirectTimerRef.current = setTimeout(() => {
              console.log("📍 Redirecting to home page...");
              router.push("/");
            }, 1500);
          } else {
            // ✅ No token - user is registered but not logged in
            // Redirect to login page instead of registration
            console.log("🔑 No token found - redirecting to login page...");
            setRedirectTarget("login");
            setIsSuccess(true);

            if (redirectTimerRef.current) {
              clearTimeout(redirectTimerRef.current);
            }
            redirectTimerRef.current = setTimeout(() => {
              console.log("📍 Redirecting to login page...");
              router.push("/auth/customer/login");
            }, 1500);
          }
        }
      } else {
        setError(result.message || "Invalid OTP. Please try again.");
        verificationInProgress.current = false;
        setIsVerifying(false);
        setIsSuccess(false);
      }
    } catch (err: unknown) {
      console.error("❌ OTP Verification Error:", err);
      setError(readCaughtMessage(err, "data", "message") || "Invalid OTP. Please try again.");
      verificationInProgress.current = false;
      setIsVerifying(false);
      setIsSuccess(false);
    }
  };

  const handleComplete = (value: string) => {
    setOtp(value);
    if (
      value.length === 6 &&
      !verificationInProgress.current &&
      !isVerifying &&
      !isLoading
    ) {
      handleVerifyOTP(value);
    }
  };

  const handleVerifyClick = () => {
    if (otp.length === 6) {
      handleVerifyOTP(otp);
    } else {
      setError("Please enter a complete 6-digit OTP");
    }
  };

  const handleResend = async () => {
    if (isResending) return;

    setError(null);
    setOtp("");
    setIsSuccess(false);
    verificationInProgress.current = false;
    setIsVerifying(false);

    try {
      const result = await sendOTP({
        phone: phoneNumber,
      }).unwrap();

      if (result.status === true) {
        setTimeLeft(30);
        setCanResend(false);
        console.log("✅ OTP resent successfully!");
      } else {
        setError(result.message || "Failed to resend OTP. Please try again.");
      }
    } catch (err: unknown) {
      console.error("Resend OTP error:", err);
      setError(readCaughtMessage(err, "data", "message") || "Failed to resend OTP. Please try again.");
    }
  };

  const formatPhoneNumber = (phone: string) => {
    if (phone.startsWith("+91")) {
      const digits = phone.replace("+91", "");
      return `+91 ${digits.slice(0, 5)}****${digits.slice(-2)}`;
    }
    if (phone.length === 10) {
      return `+91 ${phone.slice(0, 5)}****${phone.slice(-2)}`;
    }
    return phone;
  };

  const getSuccessMessage = () => {
    if (redirectTarget === "registration") {
      return "Redirecting to registration...";
    } else if (redirectTarget === "login") {
      return "Redirecting to login...";
    } else if (redirectTarget === "home") {
      return "Redirecting to your dashboard...";
    }
    return "Verification successful!";
  };

  const features = [
    { icon: Shield, label: "Secure verification process" },
    { icon: Clock, label: "One-time code expires in 5 minutes" },
    { icon: Lock, label: "Protecting your account security" },
  ];

  return (
