// components/customer/Registration/CustomerRegistrationForm.tsx

"use client";

import React, { useState, useEffect } from "react";
import { useRouter, useSearchParams } from "next/navigation";
import { useDispatch } from "react-redux";
import { Input } from "@/components/common/Input";
import { PhoneInput } from "@/components/common/PhoneInput";
import "@/components/common/Button";
import { Logo } from "@/components/common/Logo";
import Link from "next/link";
import { ROUTES } from "@/lib/constants/routes";
import ConstellationBackground from "@/components/common/ConstellationBackground";
import { useConfirmRegistrationMutation } from "@/lib/redux/api/authApi";
import { showToast } from "@/lib/slices/toastSlice";
import { Shield, CheckCircle, ArrowRight, Users, Sparkles, ArrowLeft } from "lucide-react";

/**
 * Same theme tokens as all registration steps and login components
 */
const theme = {
  font: "'Inter', 'Plus Jakarta Sans', ui-sans-serif, system-ui, -apple-system, sans-serif",
  gold: "#F9C744",
  goldDark: "#E6B33D",
  goldDeep: "#C9922A",
  navy: "#06101E",
  navySoft: "#0B1B2E",
};

interface CustomerRegistrationFormProps {
  onBack?: () => void;
  phoneNumber?: string;
}

export const CustomerRegistrationForm: React.FC<
  CustomerRegistrationFormProps
> = ({ onBack, phoneNumber: propPhoneNumber }) => {
  const router = useRouter();
  const dispatch = useDispatch();
  const searchParams = useSearchParams();
  const [confirmRegistration, { isLoading }] = useConfirmRegistrationMutation();
  const [formError, setFormError] = useState<string | null>(null);
  const [successMessage, setSuccessMessage] = useState<string | null>(null);
  const [tempToken, setTempToken] = useState<string | null>(null);
  const [verifiedPhone, setVerifiedPhone] = useState<string>("");
  const [isPhoneVerified, setIsPhoneVerified] = useState<boolean>(false);
  const [isPageLoading, setIsPageLoading] = useState(true);

  const [formData, setFormData] = useState({
    full_name: "",
    email: "",
    phone: "",
    country: "India",
    terms_condition: false,
    account_type: "customer" as const,
  });

  const [errors, setErrors] = useState<Record<string, string>>({});

  // Helper function to clean phone number (remove +91 if present)
  const cleanPhoneNumber = (phone: string): string => {
    if (!phone) return "";
    // Remove +91 if present
    let cleaned = phone.replace(/^\+91/, "");
    // Remove any other non-digit characters except +
    cleaned = cleaned.replace(/[^\d]/g, "");
    return cleaned;
  };

  // Handle back button - go to login instead of OTP
  const handleBack = () => {
    if (onBack) {
      onBack();
    } else {
      // Clear temporary data
      if (typeof window !== "undefined") {
        localStorage.removeItem("temp_token");
        localStorage.removeItem("verified_phone");
        localStorage.removeItem("customer_otp");
        localStorage.removeItem("customer_phone");
        sessionStorage.removeItem("temp_token");
        sessionStorage.removeItem("verified_phone");
        sessionStorage.removeItem("customer_phone");
      }
      // Navigate to login page
      router.push(ROUTES.auth.customer.login);
    }
  };

  // Effect to check if user came from OTP flow
  useEffect(() => {
    // Check if user has a temp token (meaning they came from OTP verification)
    const hasTempToken =
      typeof window !== "undefined" &&
      (localStorage.getItem("temp_token") ||
        sessionStorage.getItem("temp_token"));
    const hasVerifiedPhone =
      typeof window !== "undefined" &&
      (localStorage.getItem("verified_phone") ||
        sessionStorage.getItem("verified_phone"));

    // Also check if phone is in URL
    const urlPhone = searchParams.get("phone");

    if (!hasTempToken && !hasVerifiedPhone && !urlPhone && !propPhoneNumber) {
      console.log(
        "🚫 No temp token or verified phone found - redirecting to login",
      );
      setFormError("Please verify your phone number first.");
      dispatch(
        showToast({
          message: "Please verify your phone number first.",
          type: "error",
        }),
      );
      setTimeout(() => {
        router.push(ROUTES.auth.customer.login);
      }, 1000);
    } else {
      setIsPageLoading(false);
    }
  }, [router, searchParams, propPhoneNumber, dispatch]);

  // Effect to set phone number from various sources
  useEffect(() => {
    let token = null;
    let phone = null;

    console.log("🔍 Looking for phone number...");

    // 1. Check props first
    if (propPhoneNumber) {
      phone = propPhoneNumber;
      console.log("📱 Phone from props (raw):", phone);
    }

    // 2. Check URL query params
    if (!phone && typeof window !== "undefined") {
      const urlPhone = searchParams.get("phone");
      if (urlPhone) {
        phone = decodeURIComponent(urlPhone);
        console.log("📱 Phone from URL (raw):", phone);
      }
    }

    // 3. Check localStorage
    if (!phone && typeof window !== "undefined") {
      const storedPhone = localStorage.getItem("verified_phone");
      if (storedPhone) {
        phone = storedPhone;
        console.log("📱 Phone from localStorage (raw):", phone);
      }
    }

    // 4. Check sessionStorage
    if (!phone && typeof window !== "undefined") {
      const sessionPhone = sessionStorage.getItem("verified_phone");
      if (sessionPhone) {
        phone = sessionPhone;
        console.log("📱 Phone from sessionStorage (raw):", phone);
      }
    }

    // Get temp token
    if (typeof window !== "undefined") {
      token = localStorage.getItem("temp_token");
      if (!token) {
        token = sessionStorage.getItem("temp_token");
      }
      console.log("🔑 Temp Token:", token);
    }

    // Clean the phone number (remove +91 if present)
    let cleanPhone = "";
    if (phone) {
      cleanPhone = cleanPhoneNumber(phone);
      console.log("📱 Cleaned Phone (without +91):", cleanPhone);
    }

    console.log("📱 Final Clean Phone:", cleanPhone);

    if (token) {
      setTempToken(token);
    }

    if (cleanPhone) {
      setVerifiedPhone(cleanPhone);
      setIsPhoneVerified(true);
      // Update form data with cleaned phone number
      setFormData((prev) => ({
        ...prev,
        phone: cleanPhone,
      }));
      console.log("✅ Phone set in form (without +91):", cleanPhone);
    } else {
      console.log("❌ No phone found - redirecting to login");
      setFormError("Phone number not found. Please verify your phone again.");
      dispatch(
        showToast({
          message: "Phone number not found. Please verify your phone again.",
          type: "error",
        }),
      );
      setTimeout(() => {
        // 🔥 FIX: Redirect to login instead of phone input
        router.push(ROUTES.auth.customer.login);
      }, 2000);
    }
  }, [propPhoneNumber, router, searchParams, dispatch]);

  const validateForm = (): boolean => {
    const newErrors: Record<string, string> = {};

    if (!formData.full_name.trim()) {
      newErrors.full_name = "Full name is required";
    } else if (formData.full_name.trim().split(" ").length < 2) {
      newErrors.full_name = "Please enter your full name (First and Last name)";
    }

    if (!formData.email) {
      newErrors.email = "Email address is required";
    } else if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(formData.email)) {
      newErrors.email = "Please enter a valid email address";
    }

    const cleanPhone = formData.phone.replace(/\D/g, "");
    if (!formData.phone) {
      newErrors.phone = "Phone number is required";
    } else if (cleanPhone.length < 10) {
      newErrors.phone = "Please enter a valid 10-digit phone number";
    }

    if (!formData.country) {
      newErrors.country = "Country is required";
    }

    if (!formData.terms_condition) {
      newErrors.terms_condition =
        "You must accept the Terms of Service and Privacy Policy";
    }

    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!validateForm()) return;

    if (!tempToken) {
      setFormError("Session expired. Please verify your phone number again.");
      dispatch(
        showToast({
          message: "Session expired. Please verify your phone number again.",
          type: "error",
        }),
      );
      setTimeout(() => {
        // 🔥 FIX: Redirect to login instead of phone input
        router.push(ROUTES.auth.customer.login);
      }, 2000);
      return;
    }

    setFormError(null);
    setSuccessMessage(null);

    // Ensure phone has +91 for API
    const phoneForApi = formData.phone.startsWith("+91")
      ? formData.phone
      : `+91${formData.phone}`;

    try {
      const requestBody = {
        email: formData.email,
        account_type: "customer",
        temp_token: tempToken,
        full_name: formData.full_name.trim(),
        phone: phoneForApi, // Send with +91 to API
        country: formData.country,
        terms_condition: formData.terms_condition ? "1" : "0",
      };

      console.log("📝 Registration Payload:", requestBody);

      const result = await confirmRegistration(requestBody).unwrap();

      if (result.status && result.token) {
        // Show success toast
        dispatch(
          showToast({
            message: result.message || "Account created successfully!",
            type: "success",
          }),
        );

        localStorage.setItem("auth_token", result.token);
        if (result.data?.user) {
          localStorage.setItem("user_data", JSON.stringify(result.data.user));
        }

        // Clear temporary data
        localStorage.removeItem("temp_token");
        localStorage.removeItem("verified_phone");
        localStorage.removeItem("customer_otp");
        localStorage.removeItem("customer_phone");
        sessionStorage.removeItem("temp_token");
        sessionStorage.removeItem("verified_phone");
        sessionStorage.removeItem("customer_phone");

        setSuccessMessage(
          "Account created successfully! Redirecting to dashboard...",
        );

        setTimeout(() => {
          router.push(ROUTES.dashboard);
        }, 1500);
      } else {
        const errorMsg =
          result.message || "Registration failed. Please try again.";
        setFormError(errorMsg);
        dispatch(
          showToast({
            message: errorMsg,
            type: "error",
          }),
        );
      }
    } catch (err: any) {
      console.error("Registration error:", err);

      let errorMsg = "Registration failed. Please try again later.";
      if (err.data?.message) {
        if (err.data.message.toLowerCase().includes("email")) {
          errorMsg =
            "This email is already registered. Please use a different email.";
        } else if (err.data.message.toLowerCase().includes("phone")) {
          errorMsg =
            "This phone number is already registered. Please use a different number.";
        } else {
          errorMsg = err.data.message;
        }
      }
      setFormError(errorMsg);
      dispatch(
        showToast({
          message: errorMsg,
          type: "error",
        }),
      );
    }
  };

  const handleChange = (
    e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>,
  ) => {
    const { name, value, type } = e.target;
    const checked = (e.target as HTMLInputElement).checked;

    setFormData((prev) => ({
      ...prev,
      [name]: type === "checkbox" ? checked : value,
    }));

    if (errors[name]) {
      setErrors((prev) => {
        const newErrors = { ...prev };
        delete newErrors[name];
        return newErrors;
      });
    }
  };

  // Handler for phone input changes
  const handlePhoneChange = (value: string) => {
    // If the value already has +91, clean it
    let cleanedValue = value;
    if (cleanedValue.startsWith("+91")) {
      cleanedValue = cleanedValue.replace(/^\+91/, "");
    }
    console.log("📱 Phone input changed (cleaned):", cleanedValue);
    setFormData((prev) => ({ ...prev, phone: cleanedValue }));
    if (errors.phone) {
      const newErrors = { ...errors };
      delete newErrors.phone;
      setErrors(newErrors);
    }
  };

  const features = [
    { icon: Sparkles, label: "Easy ordering & reordering" },
    { icon: Shield, label: "Real-time delivery tracking" },
    { icon: CheckCircle, label: "Secure & trusted platform" },
  ];

  // Loading state
  if (isPageLoading) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-[#FAF8F4]">
        <div className="flex flex-col items-center gap-4">
          <div className="w-10 h-10 border-4 border-[var(--gold)] border-t-transparent rounded-full animate-spin" />
          <p className="text-gray-500 text-sm font-medium">Loading...</p>
        </div>
      </div>
    );
  }

  return (
    <div
      style={
        {
          fontFamily: theme.font,
          "--gold": theme.gold,
          "--gold-dark": theme.goldDark,
          "--gold-deep": theme.goldDeep,
          "--navy": theme.navy,
          "--navy-soft": theme.navySoft,
        } as React.CSSProperties
      }
      className="min-h-screen flex items-center justify-center bg-[#FAF8F4] px-3 sm:px-4 py-4 sm:py-8"
    >
      <ConstellationBackground
        starColor="#F9C744"
        starCount={55}
        connectionDistance={22}
        animationSpeed={1.2}
        showParticles={true}
        particleCount={20}
        showShootingStars={true}
        shootingStarCount={5}
        glowIntensity={1.2}
        interactive={true}
        onStarClick={(starId) => {
          console.log(`✨ Star ${starId} exploded!`);
        }}
      />
      {/* Centered surface card */}
      <div className="w-full max-w-4xl mx-auto">
        <div className="relative rounded-2xl sm:rounded-[28px] bg-white/90 backdrop-blur-xl border border-[var(--navy)]/[0.06] shadow-[0_20px_60px_-15px_rgba(6,16,30,0.15)] overflow-hidden">
          {/* Ambient glow */}
          <div className="pointer-events-none absolute inset-x-0 -top-10 flex justify-center">
            <div className="w-40 sm:w-60 h-40 sm:h-60 rounded-full bg-[radial-gradient(circle,_rgba(249,199,68,0.25)_0%,_rgba(249,199,68,0)_70%)] blur-2xl" />
          </div>

          <div className="relative grid grid-cols-1 lg:grid-cols-5">
            {/* Left Panel - Customer Branding */}
            <div className="hidden lg:flex lg:col-span-2 relative overflow-hidden bg-gradient-to-br from-[#0F2038] via-[#06101E] to-[#030810] p-8 lg:p-10 flex-col justify-between min-h-[400px] lg:min-h-[600px]">
              {/* Background Pattern */}
              <div className="absolute inset-0 opacity-[0.03]">
                <div
                  className="absolute inset-0"
                  style={{
                    backgroundImage:
                      "radial-gradient(circle at 20% 50%, #F9C744 1px, transparent 1px)",
                    backgroundSize: "40px 40px",
                  }}
                />
              </div>

              {/* Decorative Elements */}
              <div className="absolute -right-20 -top-20 w-96 h-96 bg-[#F9C744]/5 rounded-full blur-3xl" />
              <div className="absolute -left-20 -bottom-20 w-80 h-80 bg-[#F9C744]/5 rounded-full blur-3xl" />

              {/* Floating Dots */}
              <div className="absolute inset-0 opacity-10">
                {[...Array(15)].map((_, i) => (
                  <div
                    key={i}
                    className="absolute w-1.5 h-1.5 bg-[#F9C744] rounded-full"
                    style={{
                      top: `${Math.random() * 100}%`,
                      left: `${Math.random() * 100}%`,
                      animation: `pulse 3s ease-in-out ${Math.random() * 3}s infinite`,
                    }}
                  />
                ))}
              </div>

              <style>{`
                @keyframes pulse {
                  0%, 100% { opacity: 0.2; transform: scale(1); }
                  50% { opacity: 0.8; transform: scale(1.5); }
                }
              `}</style>

              {/* Header */}
              <div className="relative z-10">
                <div className="flex items-center gap-3">
                  <div className="bg-white/10 backdrop-blur-sm p-2.5 rounded-xl border border-white/10">
                    <Logo width={32} height={32} showText={false} />
                  </div>
                  <span className="text-white/40 text-[10px] tracking-[0.2em] font-light uppercase">
                    Indiekonnet
                  </span>
                </div>
              </div>

              {/* Main Content */}
              <div className="relative z-10 py-6">
                <div className="space-y-6">
                  <div className="w-12 h-1 bg-gradient-to-r from-[#F9C744] to-[#E6B33D] rounded-full" />

                  <h2 className="text-white text-2xl lg:text-3xl font-bold leading-tight">
                    Welcome to
                    <br />
                    <span className="text-[#F9C744]">IndiKonnect</span>
                  </h2>

                  <p className="text-[#8291A6] text-sm leading-relaxed">
                    Create your customer account to start ordering, track
                    deliveries, and manage your purchases seamlessly.
                  </p>

                  <div className="space-y-2.5">
                    {features.map((feature, index) => (
                      <div
                        key={index}
                        className="flex items-center gap-3 text-xs text-[#5C6B80] group cursor-default"
                      >
                        <div className="w-6 h-6 rounded-lg bg-[#F9C744]/10 flex items-center justify-center flex-shrink-0 group-hover:bg-[#F9C744]/20 transition-colors duration-300">
                          <feature.icon className="w-3.5 h-3.5 text-[#F9C744]" />
                        </div>
                        <span className="group-hover:text-white/80 transition-colors duration-300">
                          {feature.label}
                        </span>
                      </div>
                    ))}
                  </div>
                </div>
              </div>

              {/* Footer Stats */}
              <div className="relative z-10 grid grid-cols-3 gap-4 text-xs border-t border-white/5 pt-4">
                <div>
                  <p className="text-white font-semibold text-lg">10K+</p>
                  <p className="text-[#5C6B80] text-[10px]">Happy Customers</p>
                </div>
                <div className="border-l border-white/5 pl-4">
                  <p className="text-white font-semibold text-lg">98%</p>
                  <p className="text-[#5C6B80] text-[10px]">Satisfaction</p>
                </div>
                <div className="border-l border-white/5 pl-4">
                  <p className="text-white font-semibold text-lg">4.9★</p>
                  <p className="text-[#5C6B80] text-[10px]">User Rating</p>
                </div>
              </div>
            </div>

            {/* Right Panel - Registration Form */}
            <div className="lg:col-span-3 p-5 sm:p-6 md:p-8 lg:p-10 flex flex-col justify-center">
              {/* Back Button - Mobile */}
              <button
                onClick={handleBack}
                className="lg:hidden flex items-center gap-2 text-gray-500 hover:text-[var(--gold-deep)] transition-colors duration-200 mb-4 group"
              >
                <ArrowLeft className="w-4 h-4 group-hover:-translate-x-1 transition-transform" />
                <span className="text-sm font-medium">Back to Login</span>
              </button>

              {/* Mobile Header */}
              <div className="lg:hidden text-center mb-6">
                <div className="flex justify-center mb-3">
                  <div className="w-14 h-14 rounded-2xl bg-gradient-to-br from-[var(--gold)] via-[var(--gold-dark)] to-[var(--gold-deep)] flex items-center justify-center shadow-[0_8px_20px_-6px_rgba(249,199,68,0.55)]">
                    <Users className="w-7 h-7 text-[var(--navy)]" />
