"use client";

import { useState } from "react";
import { motion, AnimatePresence } from "framer-motion";
import {
  Send,
  CheckCircle2,
  AlertCircle,
  User,
  Mail,
  MessageCircle,
  Phone,
} from "lucide-react";
import { useSubmitContactMutation } from "@/lib/redux/api/ContactApi";

interface ContactFormProps {
  onSubmit?: (data: any) => void;
}

const subjects = [
  "Order support",
  "Wholesale & partnerships",
  "Press",
  "Something else",
];

const RequiredStar = () => (
  <span className="ml-1 inline-block text-red-500" aria-hidden="true">
    *
  </span>
);

export default function ContactForm({ onSubmit }: ContactFormProps) {
  const [submitContact, { isLoading }] = useSubmitContactMutation();

  const [formData, setFormData] = useState({
    firstName: "",
    lastName: "",
    email: "",
    phone: "",
    subject: "Order support",
    message: "",
  });

  const [isSubmitted, setIsSubmitted] = useState(false);
  const [errorMessage, setErrorMessage] = useState("");
  const [successMessage, setSuccessMessage] = useState("");

  const [formErrors, setFormErrors] = useState<{
    firstName?: string;
    lastName?: string;
    email?: string;
    phone?: string;
    message?: string;
  }>({});

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    setErrorMessage("");
    setSuccessMessage("");
    setFormErrors({});

    const errors: any = {};

    if (!formData.firstName.trim()) {
      errors.firstName = "First name is required";
    }

    if (!formData.lastName.trim()) {
      errors.lastName = "Last name is required";
    }

    if (!formData.email.trim()) {
      errors.email = "Email is required";
    } else if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(formData.email)) {
      errors.email = "Please enter a valid email address";
    }

    if (!formData.phone.trim()) {
      errors.phone = "Phone number is required";
    } else if (!/^[0-9]{10,14}$/.test(formData.phone.replace(/\s/g, ""))) {
      errors.phone = "Please enter a valid phone number";
    }

    if (!formData.message.trim()) {
      errors.message = "Message is required";
    } else if (formData.message.trim().length < 10) {
      errors.message = "Message must be at least 10 characters";
    }

    if (Object.keys(errors).length > 0) {
      setFormErrors(errors);
      return;
    }

    try {
      const contactData = {
        name: `${formData.firstName} ${formData.lastName}`.trim(),
        email: formData.email,
        phone: formData.phone.replace(/\s/g, ""),
        message: `[${formData.subject}] ${formData.message}`,
      };

      const result = await submitContact(contactData).unwrap();

      setSuccessMessage(
        result?.message || "Your message has been sent successfully!",
      );

      setIsSubmitted(true);

      if (onSubmit) {
        onSubmit(contactData);
      }

      setTimeout(() => {
        setIsSubmitted(false);
        setSuccessMessage("");

        setFormData({
          firstName: "",
          lastName: "",
          email: "",
          phone: "",
          subject: "Order support",
          message: "",
        });
      }, 3000);
    } catch (error: any) {
      if (error?.data?.message) {
        setErrorMessage(error.data.message);
      } else if (error?.data?.error) {
        setErrorMessage(error.data.error);
      } else if (error?.status === 400) {
        setErrorMessage("Please check your input and try again.");
      } else if (error?.status === 429) {
        setErrorMessage("Too many requests. Please try again later.");
      } else if (error?.status === 500) {
        setErrorMessage("Server error. Please try again later.");
      } else {
        setErrorMessage("Failed to send message. Please try again.");
      }

      setTimeout(() => {
        setErrorMessage("");
      }, 5000);
    }
  };

  const handleChange = (
    e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement>,
  ) => {
    const { name, value } = e.target;

    if (name === "phone") {
      const cleanedValue = value.replace(/\D/g, "");

      if (cleanedValue.length <= 14) {
        setFormData((prev) => ({
          ...prev,
          phone: cleanedValue,
        }));
      }
    } else {
      setFormData((prev) => ({
        ...prev,
        [name]: value,
      }));
    }

    if (formErrors[name as keyof typeof formErrors]) {
      setFormErrors((prev) => ({
        ...prev,
        [name]: undefined,
      }));
    }

    if (errorMessage) {
      setErrorMessage("");
    }

    if (successMessage) {
      setSuccessMessage("");
    }
  };

  return (
    <motion.div
      initial={{ opacity: 0, y: 20 }}
      animate={{ opacity: 1, y: 0 }}
      transition={{ duration: 0.5 }}
      className="w-full"
    >
      <form onSubmit={handleSubmit} className="space-y-5">
        {/* First Name + Last Name */}
        <div className="grid grid-cols-1 gap-4 md:grid-cols-2">
          {/* First Name */}
          <div>
            <label className="mb-2 block text-[12px] font-semibold uppercase tracking-wider text-[#172044]">
              First Name
              <RequiredStar />
            </label>

            <div className="relative">
