// components/distributor/Login/ForgotPasswordModal.tsx

"use client";

import React, { useState, useEffect } from "react";
import { X, Mail, Key, Lock, Eye, EyeOff, CheckCircle, ArrowLeft } from "lucide-react";
import { Input } from "@/components/common/Input";
import {
    useForgotPasswordMutation,
    useVerifyResetOTPMutation,
    useResetPasswordMutation
} from "@/lib/redux/api/distributor/distributorauthApis";
import { readCaughtMessage } from "@/lib/utils/readCaughtMessage";


interface ForgotPasswordModalProps {
    isOpen: boolean;
    onClose: () => void;
    onSuccess?: () => void;
}

type Step = "email" | "otp" | "reset";

export const ForgotPasswordModal: React.FC<ForgotPasswordModalProps> = ({
    isOpen,
    onClose,
    onSuccess,
}) => {
    // Step management
    const [currentStep, setCurrentStep] = useState<Step>("email");

    // Form data
    const [email, setEmail] = useState("");
    const [otp, setOtp] = useState("");
    const [password, setPassword] = useState("");
    const [confirmPassword, setConfirmPassword] = useState("");

    // UI states
    const [showPassword, setShowPassword] = useState(false);
    const [showConfirmPassword, setShowConfirmPassword] = useState(false);
    const [error, setError] = useState<string | null>(null);
    const [success, setSuccess] = useState<string | null>(null);
    const [otpTimer, setOtpTimer] = useState(60);
    const [canResend, setCanResend] = useState(false);

    // API hooks
    const [forgotPassword, { isLoading: isEmailLoading }] = useForgotPasswordMutation();
    const [verifyResetOTP, { isLoading: isOtpLoading }] = useVerifyResetOTPMutation();
    const [resetPassword, { isLoading: isResetLoading }] = useResetPasswordMutation();

    // Timer for OTP resend
    useEffect(() => {
        let interval: ReturnType<typeof setTimeout>;
        if (currentStep === "otp" && otpTimer > 0) {
            interval = setInterval(() => {
                setOtpTimer((prev) => prev - 1);
            }, 1000);
        } else if (otpTimer === 0) {
            setCanResend(true);
        }
        return () => clearInterval(interval);
    }, [currentStep, otpTimer]);

    // Reset state when modal opens
    useEffect(() => {
        if (isOpen) {
            setCurrentStep("email");
            setEmail("");
            setOtp("");
            setPassword("");
            setConfirmPassword("");
            setError(null);
            setSuccess(null);
            setOtpTimer(60);
            setCanResend(false);
        }
    }, [isOpen]);

    // Handle modal close
    const handleClose = () => {
        if (!isEmailLoading && !isOtpLoading && !isResetLoading) {
            onClose();
        }
    };

    // Step 1: Send OTP
    const handleSendOTP = async (e: React.FormEvent) => {
        e.preventDefault();
        setError(null);
        setSuccess(null);

        if (!email || !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) {
            setError("Please enter a valid email address");
            return;
        }

        try {
            const response = await forgotPassword({ email }).unwrap();

            if (response.status === true) {
                setSuccess(response.message || "OTP sent to your email");
                setCurrentStep("otp");
                setOtpTimer(60);
                setCanResend(false);

                // Pre-fill OTP if it's in response (for testing)
                if (response.otp) {
                    setOtp(String(response.otp));
                }
            } else {
                setError(response.message || "Failed to send OTP. Please try again.");
            }
        } catch (err: unknown) {
            setError(readCaughtMessage(err, "data", "message") || readCaughtMessage(err, "message") || "Network error. Please try again.");
        }
    };

    // Step 2: Verify OTP
    const handleVerifyOTP = async (e: React.FormEvent) => {
        e.preventDefault();
        setError(null);
        setSuccess(null);

        if (!otp || otp.length < 4) {
            setError("Please enter a valid OTP");
            return;
        }

        try {
            const response = await verifyResetOTP({
                email,
                otp: Number(otp)
            }).unwrap();

            if (response.status === true) {
                setSuccess(response.message || "OTP verified successfully");
                setCurrentStep("reset");
            } else {
                setError(response.message || "Invalid OTP. Please try again.");
            }
        } catch (err: unknown) {
            setError(readCaughtMessage(err, "data", "message") || readCaughtMessage(err, "message") || "Network error. Please try again.");
        }
    };

    // Step 3: Reset Password
    const handleResetPassword = async (e: React.FormEvent) => {
        e.preventDefault();
        setError(null);
        setSuccess(null);

        if (!password || password.length < 8) {
            setError("Password must be at least 8 characters");
            return;
        }

        if (password !== confirmPassword) {
            setError("Passwords do not match");
            return;
        }

        try {
            const response = await resetPassword({
                email,
                password,
                password_confirmation: confirmPassword,
            }).unwrap();

            if (response.status === true) {
                setSuccess(response.message || "Password reset successfully");

                // Close modal after success
                setTimeout(() => {
                    if (onSuccess) onSuccess();
                    handleClose();
                }, 2000);
            } else {
                setError(response.message || "Failed to reset password. Please try again.");
            }
        } catch (err: unknown) {
            setError(readCaughtMessage(err, "data", "message") || readCaughtMessage(err, "message") || "Network error. Please try again.");
        }
    };

    // Resend OTP
    const handleResendOTP = async () => {
        setError(null);
        setSuccess(null);
        setCanResend(false);
        setOtpTimer(60);

        try {
            const response = await forgotPassword({ email }).unwrap();

            if (response.status === true) {
                setSuccess("New OTP sent to your email");
                if (response.otp) {
                    setOtp(String(response.otp));
                }
            } else {
                setError(response.message || "Failed to resend OTP");
                setCanResend(true);
            }
        } catch (err: unknown) {
            setError(readCaughtMessage(err, "data", "message") || readCaughtMessage(err, "message") || "Network error");
            setCanResend(true);
        }
    };

    // Go back to previous step
    const goBack = () => {
        if (currentStep === "otp") {
            setCurrentStep("email");
            setError(null);
            setSuccess(null);
        } else if (currentStep === "reset") {
            setCurrentStep("otp");
            setError(null);
            setSuccess(null);
        }
    };

    if (!isOpen) return null;

    return (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/60 backdrop-blur-sm animate-in fade-in duration-200">
            <div className="bg-white rounded-2xl max-w-md w-full mx-4 p-6 shadow-2xl relative animate-in slide-in-from-bottom-4 duration-300">
                {/* Close Button */}
                <button
                    type="button"
                    onClick={handleClose}
                    disabled={isEmailLoading || isOtpLoading || isResetLoading}
                    className="absolute right-4 top-4 text-gray-400 hover:text-gray-600 transition-colors rounded-full hover:bg-gray-100 p-1 disabled:opacity-50 disabled:cursor-not-allowed"
                >
                    <X className="w-5 h-5" />
                </button>

                {/* Header */}
                <div className="text-center mb-6">
                    <div className="flex items-center justify-center gap-2 mb-2">
                        {currentStep !== "email" && (
                            <button
                                type="button"
                                onClick={goBack}
                                className="text-gray-400 hover:text-gray-600 transition-colors p-1"
                            >
                                <ArrowLeft className="w-5 h-5" />
                            </button>
                        )}
                        <div className="w-12 h-12 rounded-2xl bg-gradient-to-br from-[#F9C744] to-[#E6B33D] flex items-center justify-center shadow-[0_8px_20px_-6px_rgba(249,199,68,0.4)]">
                            {currentStep === "email" && <Mail className="w-6 h-6 text-[#06101E]" />}
                            {currentStep === "otp" && <Key className="w-6 h-6 text-[#06101E]" />}
                            {currentStep === "reset" && <Lock className="w-6 h-6 text-[#06101E]" />}
                        </div>
                    </div>
                    <h2 className="text-xl font-bold text-[#06101E]">
                        {currentStep === "email" && "Forgot Password"}
                        {currentStep === "otp" && "Verify OTP"}
                        {currentStep === "reset" && "Reset Password"}
                    </h2>
                    <p className="text-gray-500 text-sm mt-1">
                        {currentStep === "email" && "Enter your email to receive a password reset OTP"}
                        {currentStep === "otp" && `Enter the OTP sent to ${email}`}
                        {currentStep === "reset" && "Create a new password for your account"}
                    </p>
                </div>

                {/* Error Message */}
                {error && (
                    <div className="mb-4 bg-red-50 p-3 rounded-xl border border-red-200 text-sm text-red-700 flex items-start gap-2">
                        <span className="text-lg flex-shrink-0">❌</span>
                        <span>{error}</span>
                    </div>
                )}

                {/* Success Message */}
                {success && (
                    <div className="mb-4 bg-green-50 p-3 rounded-xl border border-green-200 text-sm text-green-700 flex items-start gap-2">
                        <CheckCircle className="w-5 h-5 flex-shrink-0 text-green-500" />
                        <span>{success}</span>
                    </div>
                )}

                {/* Step 1: Email */}
                {currentStep === "email" && (
                    <form onSubmit={handleSendOTP} className="space-y-4">
                        <Input
                            label="Email Address"
                            type="email"
                            value={email}
                            onChange={(e) => setEmail(e.target.value)}
                            placeholder="Enter Your mail"
                            required
                            className="w-full h-12 px-4 text-black rounded-xl border-gray-200 focus:border-[#F9C744] focus:ring-2 focus:ring-[#F9C744]/20 transition-all duration-200"
                            autoComplete="email"
                        />

                        <button
                            type="submit"
                            disabled={isEmailLoading}
                            className="w-full bg-[#F9C744] hover:bg-[#E6B33D] text-[#06101E] font-semibold h-12 rounded-xl disabled:opacity-50 disabled:cursor-not-allowed flex items-center justify-center gap-2 transition-all duration-200 shadow-[0_4px_12px_-4px_rgba(249,199,68,0.4)] hover:shadow-[0_8px_20px_-6px_rgba(249,199,68,0.5)]"
                        >
                            {isEmailLoading ? (
                                <>
                                    <svg className="animate-spin h-5 w-5" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24">
                                        <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle>
                                        <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
                                    </svg>
                                    Sending...
                                </>
                            ) : (
                                "Send OTP →"
                            )}
                        </button>
                    </form>
                )}

                {/* Step 2: OTP */}
                {currentStep === "otp" && (
                    <form onSubmit={handleVerifyOTP} className="space-y-4">
                        <div>
                            <label className="block text-sm font-medium text-gray-700 mb-1.5">
                                Enter OTP
                            </label>
                            <div className="flex gap-2">
                                <input
                                    type="text"
                                    value={otp}
                                    onChange={(e) => setOtp(e.target.value.replace(/\D/g, ""))}
                                    placeholder="Enter 6-digit OTP"
                                    className="flex-1 h-12 px-4 text-black rounded-xl border border-gray-200 focus:border-[#F9C744] focus:ring-2 focus:ring-[#F9C744]/20 transition-all duration-200 outline-none"
                                    maxLength={6}
                                    autoFocus
                                />
                            </div>
                        </div>

                        <div className="flex items-center justify-between text-sm">
                            <span className="text-gray-500">
                                {canResend ? (
                                    <button
                                        type="button"
                                        onClick={handleResendOTP}
                                        className="text-[#F9C744] hover:text-[#E6B33D] font-medium transition-colors"
                                    >
                                        Resend OTP
                                    </button>
                                ) : (
                                    `Resend OTP in ${otpTimer}s`
                                )}
                            </span>
                            <button
                                type="button"
                                onClick={() => setCurrentStep("email")}
                                className="text-gray-400 hover:text-gray-600 transition-colors"
                            >
                                Change Email
                            </button>
                        </div>

                        <button
                            type="submit"
                            disabled={isOtpLoading || !otp || otp.length < 4}
                            className="w-full bg-[#F9C744] hover:bg-[#E6B33D] text-[#06101E] font-semibold h-12 rounded-xl disabled:opacity-50 disabled:cursor-not-allowed flex items-center justify-center gap-2 transition-all duration-200 shadow-[0_4px_12px_-4px_rgba(249,199,68,0.4)] hover:shadow-[0_8px_20px_-6px_rgba(249,199,68,0.5)]"
                        >
                            {isOtpLoading ? (
                                <>
                                    <svg className="animate-spin h-5 w-5" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24">
                                        <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle>
                                        <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
                                    </svg>
                                    Verifying...
                                </>
                            ) : (
                                "Verify OTP →"
                            )}
                        </button>
                    </form>
                )}

                {/* Step 3: Reset Password */}
                {currentStep === "reset" && (
                    <form onSubmit={handleResetPassword} className="space-y-4">
                        <div className="relative">
                            <Input
                                label="New Password"
                                type={showPassword ? "text" : "password"}
                                value={password}
                                onChange={(e) => setPassword(e.target.value)}
                                placeholder="Enter new password"
                                required
                                className="w-full h-12 px-4 text-black rounded-xl border-gray-200 focus:border-[#F9C744] focus:ring-2 focus:ring-[#F9C744]/20 transition-all duration-200 pr-12"
                                autoComplete="new-password"
                            />
                            <button
                                type="button"
                                onClick={() => setShowPassword(!showPassword)}
                                className="absolute right-4 top-[46px] text-gray-400 hover:text-gray-600 transition-colors"
                            >
                                {showPassword ? <EyeOff className="w-4 h-4" /> : <Eye className="w-4 h-4" />}
                            </button>
                        </div>

                        <div className="relative">
                            <Input
                                label="Confirm Password"
                                type={showConfirmPassword ? "text" : "password"}
                                value={confirmPassword}
                                onChange={(e) => setConfirmPassword(e.target.value)}
                                placeholder="Confirm new password"
                                required
                                className="w-full h-12 px-4 text-black rounded-xl border-gray-200 focus:border-[#F9C744] focus:ring-2 focus:ring-[#F9C744]/20 transition-all duration-200 pr-12"
                                autoComplete="new-password"
                            />
                            <button
                                type="button"
                                onClick={() => setShowConfirmPassword(!showConfirmPassword)}
                                className="absolute right-4 top-[46px] text-gray-400 hover:text-gray-600 transition-colors"
                            >
                                {showConfirmPassword ? <EyeOff className="w-4 h-4" /> : <Eye className="w-4 h-4" />}
                            </button>
                        </div>

                        <div className="text-xs text-gray-400 space-y-1">
                            <p>Password must be at least 8 characters</p>
                            <p>Include uppercase, lowercase, number, and special character</p>
                        </div>

                        <button
                            type="submit"
                            disabled={isResetLoading || !password || !confirmPassword || password.length < 8 || password !== confirmPassword}
                            className="w-full bg-[#F9C744] hover:bg-[#E6B33D] text-[#06101E] font-semibold h-12 rounded-xl disabled:opacity-50 disabled:cursor-not-allowed flex items-center justify-center gap-2 transition-all duration-200 shadow-[0_4px_12px_-4px_rgba(249,199,68,0.4)] hover:shadow-[0_8px_20px_-6px_rgba(249,199,68,0.5)]"
                        >
                            {isResetLoading ? (
                                <>
                                    <svg className="animate-spin h-5 w-5" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24">
                                        <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle>
                                        <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
                                    </svg>
                                    Resetting...
                                </>
                            ) : (
                                "Reset Password →"
                            )}
                        </button>
                    </form>
                )}

                {/* Footer */}
                <div className="mt-4 pt-4 border-t border-gray-100 text-center">
                    <p className="text-xs text-gray-400">
                        {currentStep === "email" && "Enter your registered email to receive a password reset link"}
                        {currentStep === "otp" && "Check your email for the OTP code"}
                        {currentStep === "reset" && "Create a strong password for your account"}
                    </p>
                </div>
            </div>
        </div>
    );
};

export default ForgotPasswordModal;

// components/distributor/registration/DistributorRegistrationFlow.tsx

"use client";

import React, { useState } from "react";
import { useRouter } from "next/navigation";
import { useDispatch } from "react-redux";
import { useDistributorCheckStatusMutation } from "@/lib/redux/api/distributor/distributorauthApis";
import { distributorAuthApi } from "@/lib/redux/api/distributor/distributorauthApis";

import { DistributorFormData, Step } from "@/features/distributor/registration/types/index";
import { RegistrationLayout } from "@/features/distributor/registration/components/steps/RegistrationLayout";
import { ProgressSteps } from "@/features/distributor/registration/components/ProgressSteps";
import { EmailCheckScreen } from "@/features/distributor/registration/components/steps/MobileCheckScreen";
import { IdentityStep } from "@/features/distributor/registration/components/steps/IdentityStep";
import { SponsorStep } from "@/features/distributor/registration/components/steps/SponsorStep";
import { AadhaarStep } from "@/features/distributor/registration/components/steps/AadhaarStep";
import { PANStep } from "@/features/distributor/registration/components/steps/PANStep";
import { BankStep } from "@/features/distributor/registration/components/steps/BankStep";
import { LocationStep } from "@/features/distributor/registration/components/steps/LocationStep";
import { ReviewStep } from "@/features/distributor/registration/components/steps/ReviewStep";
import { AlertTriangle, X, RefreshCw, Trash2, Loader2 } from "lucide-react";
import { Button } from "@/components/common/Button";
import { readCaughtMessage } from "@/lib/utils/readCaughtMessage";


const steps: Step[] = [
  { title: "Identity", component: IdentityStep },
  { title: "Sponsor", component: SponsorStep },
  { title: "Aadhaar", component: AadhaarStep },
  { title: "PAN", component: PANStep },
  { title: "Bank", component: BankStep },
  { title: "Location", component: LocationStep },
  { title: "Review", component: ReviewStep },
];

export const DistributorRegistrationFlow: React.FC = () => {
  const router = useRouter();
  const dispatch = useDispatch();
  const [currentStep, setCurrentStep] = useState(-1);
  const [isLoading, setIsLoading] = useState(false);
  const [formError, setFormError] = useState<string | null>(null);
  const [successMessage, setSuccessMessage] = useState<string | null>(null);
  const [email, setEmail] = useState("");
  const [statusMessage, setStatusMessage] = useState("");
  const [statusType, setStatusType] = useState<"success" | "error" | "info">(
    "info",
  );
  const [emailError, setEmailError] = useState("");
  const [showNewRegistrationModal, setShowNewRegistrationModal] =
    useState(false);
  const [isResetting, setIsResetting] = useState(false);

  // ✅ NEW: checkResponse state — EmailCheckScreen ko pass karne ke liye
  const [checkResponse, setCheckResponse] = useState<any>(null);

  const [checkStatus] = useDistributorCheckStatusMutation();

  const [formData, setFormData] = useState<DistributorFormData>({
    full_name: "",
    date_of_birth: "",
    email: "",
    mobile: "",
    password: "",
    confirm_password: "",
    sponsor_id: "",
    placement_leg: "auto",
    email_verified: false,
    mobile_verified: false,
    aadhaar_number: "",
    aadhaar_consent: false,
    aadhaar_verified: false,
    pan_number: "",
    pan_verified: false,
    bank_account_holder_name: "",
    bank_account_number: "",
    bank_confirm_account_number: "",
    bank_ifsc_code: "",
    bank_name: "",
    bank_branch: "",
    bank_account_type: "savings",
    bank_verified: false,
    location_consent: false,
    location_verified: false,
    terms_accepted: false,
    agreement_accepted: false,
    code_of_conduct_accepted: false,
    account_type: "distributor",
    bank_title: "",
    bank_entity_type: "",
  });

  const [errors, setErrors] = useState<Record<string, string>>({});

  const totalSteps = steps.length;

  // ========== RESET DISTRIBUTOR API ==========
  const resetDistributorAPI = () => {
    try {
      dispatch(distributorAuthApi.util.resetApiState());
      dispatch(
        distributorAuthApi.util.invalidateTags([
          "DistributorCheckStatus",
          "DistributorStepData",
          "User",
          "Auth",
          "Registration",
          "DistributorPersonal",
          "DistributorSponsor",
          "DistributorAadhaar",
          "DistributorPAN",
          "DistributorBank",
          "DistributorLocation",
          "DistributorSubmit",
        ]),
      );
      console.log("✅ Distributor API reset successfully");
    } catch (error) {
      console.error("Error resetting distributor API:", error);
    }
  };

  // ========== COMPLETE CLEAR STATE ==========
  const clearAllState = (resetAPI: boolean = true) => {
    setFormData({
      full_name: "",
      date_of_birth: "",
      email: "",
      mobile: "",
      password: "",
      confirm_password: "",
      sponsor_id: "",
      placement_leg: "auto",
      email_verified: false,
      mobile_verified: false,
      aadhaar_number: "",
      aadhaar_consent: false,
      aadhaar_verified: false,
      pan_number: "",
      pan_verified: false,
      bank_account_holder_name: "",
      bank_account_number: "",
      bank_confirm_account_number: "",
      bank_ifsc_code: "",
      bank_name: "",
      bank_branch: "",
      bank_account_type: "savings",
      bank_verified: false,
      location_consent: false,
      location_verified: false,
      terms_accepted: false,
      agreement_accepted: false,
      code_of_conduct_accepted: false,
      account_type: "distributor",
      bank_title: "",
      bank_entity_type: "",
    });

    setErrors({});
    setStatusMessage("");
    setStatusType("info");
    setEmailError("");
    setFormError(null);
    setSuccessMessage(null);
    setEmail("");
    setCheckResponse(null); // ✅ NEW

    const itemsToClear = [
      "verified_phone",
      "phone_verified",
      "distributor_mobile",
      "distributor_email",
      "verified_email",
      "email_verified",
      "temp_token",
      "distributor_check_status",
      "distributor_phone",
      "distributor_exists",
      "distributor_status",
      "user_data",
      "customer_otp",
      "customer_phone",
      "distributor_application",
      "distributor_verified_phone",
      "distributor_phone_verified",
      "distributor_verified_email",
      "distributor_email_verified",
      "distributor_temp_token",
      "distributor_step_data",
      "distributor_step_completed",
      "distributor_fresh_registration",
      "distributor_user_data",
      "registration_step",
      "registration_data",
      "registration_completed",
      "auth_token",
      "auth_user",
      "auth_verified",
      "otp_timer",
      "otp_attempts",
      "otp_resend_timer",
    ];

    itemsToClear.forEach((key) => {
      if (localStorage.getItem(key) !== null) {
        localStorage.removeItem(key);
      }
    });

    sessionStorage.clear();

    if (resetAPI) {
      resetDistributorAPI();
    }

    setCurrentStep(-1);
    console.log("✅ All state cleared successfully");
  };

  // ========== HANDLE NEW REGISTRATION ==========
  const handleNewRegistration = () => {
    setIsResetting(true);
    clearAllState(true);
    setShowNewRegistrationModal(false);

    setTimeout(() => {
      setIsResetting(false);
      setStatusType("success");
      setTimeout(() => {
        setStatusMessage("");
        setStatusType("info");
      }, 3000);
    }, 500);
  };

  // ========== GO BACK TO EMAIL CHECK ==========
  const handleBackToEmailCheck = () => {
    clearAllState(true);
    setCurrentStep(-1);
  };

  // ========== ✅ FIXED: Email Check Handler ==========
  const handleCheckStatus = async (emailAddress: string) => {
    if (!emailAddress || !emailAddress.trim()) {
      setEmailError("Please enter your email address");
      return;
    }

    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    if (!emailRegex.test(emailAddress)) {
      setEmailError("Please enter a valid email address");
      return;
    }

    setEmailError("");
    setIsLoading(true);
    setStatusMessage("");

    try {
      const result = await checkStatus({ email: emailAddress }).unwrap();
      console.log("✅ Check Status Response:", result);

      if (result.status || result.success) {
        localStorage.setItem(
          "distributor_check_status",
          JSON.stringify(result),
        );
        localStorage.setItem("distributor_email", emailAddress);
        localStorage.setItem("temp_token", result.temp_token || "");

        setFormData((prev) => ({
          ...prev,
          email: emailAddress,
          email_verified: true,
        }));

        setEmail(emailAddress);

        // 🚫🚫🚫 CRITICAL FIX — is_registered === true par NO JUMP 🚫🚫🚫
        const isFullyRegistered =
          result.is_registered === true && result.exists === true;

        if (isFullyRegistered) {
          console.log(
            "⛔ is_registered = true → NO step jump. Modal will show.",
          );

          // ✅ checkResponse set karo — EmailCheckScreen modal khol dega
          setCheckResponse(result);

          // ✅ Status message set karo (modal ke peeche bhi dikhega)
          setStatusMessage(
            result.message || "Distributor already registered.",
          );
          setStatusType("success");

          setIsLoading(false);
          return; // ←←← YE RETURN JUMP ROKEGA
        }

        // ✅ Sirf PARTIAL registration (step 1-6) ke liye jump karo
        setCheckResponse(result);

        const stepFromApi = result.current_step || 1;
        let targetStep = stepFromApi - 1;
        if (targetStep < 0) targetStep = 0;
        if (targetStep >= steps.length) targetStep = steps.length - 1;

        setCurrentStep(targetStep);

        const stepName = steps[targetStep]?.title || "";
        setStatusMessage(
          `✅ ${result.message || "Status verified"} - Continuing from Step ${stepFromApi}: ${stepName}`,
        );
        setStatusType("success");

        if (result.user_data) {
          if (result.user_data.full_name) {
            setFormData((prev) => ({
              ...prev,
              full_name: result.user_data.full_name || prev.full_name,
              mobile: result.user_data.mobile || prev.mobile,
            }));
          }
        }
      } else {
        setStatusMessage(`❌ ${result.message || "Failed to check status"}`);
        setStatusType("error");
      }
    } catch (error: unknown) {
      console.error("❌ Error checking status:", error);
      setStatusMessage(
        `❌ ${readCaughtMessage(error, "data", "message") || "Failed to check status. Please try again."}`,
      );
      setStatusType("error");
    } finally {
      setIsLoading(false);
    }
  };

  const handleClearStatus = () => {
    setStatusMessage("");
    setStatusType("info");
    setEmailError("");
    setCheckResponse(null); // ✅ NEW
  };

  // ========== VALIDATE STEP ==========
  const validateStep = (step: number): boolean => {
    const newErrors: Record<string, string> = {};

    if (step === 0) {
      if (!formData.full_name.trim())
        newErrors.full_name = "Full name is required";
      if (!formData.date_of_birth)
        newErrors.date_of_birth = "Date of birth is required";
      if (!formData.email) newErrors.email = "Email is required";
      else if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(formData.email))
        newErrors.email = "Please enter a valid email";
      if (!formData.password) newErrors.password = "Password is required";
      else if (formData.password.length < 8)
        newErrors.password = "Password must be at least 8 characters";
      if (formData.password !== formData.confirm_password)
        newErrors.confirm_password = "Passwords do not match";
    }

    if (step === 1) {
      if (!formData.sponsor_id || formData.sponsor_id.trim().length === 0) {
        newErrors.sponsor_id = "Sponsor ID is required";
      }
    }

    if (step === 2) {
      const isFromAPI = formData.aadhaar_number?.includes("*") || false;
      if (!formData.aadhaar_verified) {
        if (!formData.aadhaar_number) {
          newErrors.aadhaar_number = "Aadhaar number is required";
        } else if (
          !isFromAPI &&
          formData.aadhaar_number.replace(/\D/g, "").length !== 12
        ) {
          newErrors.aadhaar_number =
            "Please enter a valid 12-digit Aadhaar number";
        }
        if (!formData.aadhaar_consent) {
          newErrors.aadhaar_consent =
            "You must consent to Aadhaar verification";
        }
      }
    }

    if (step === 3) {
      const isFromAPI = formData.pan_number?.includes("*") || false;
      if (!formData.pan_verified) {
        if (!formData.pan_number) {
          newErrors.pan_number = "PAN number is required";
        } else if (
          !isFromAPI &&
          formData.pan_number.replace(/[^A-Z0-9]/gi, "").length !== 10
        ) {
          newErrors.pan_number = "Please enter a valid 10-character PAN";
        }
      }
    }

    if (step === 4) {
      if (!formData.bank_verified) {
        if (!formData.bank_account_holder_name)
          newErrors.bank_account_holder_name =
            "Account holder name is required";
        if (!formData.bank_name) newErrors.bank_name = "Bank name is required";
        if (!formData.bank_account_number)
          newErrors.bank_account_number = "Account number is required";
        if (
          formData.bank_account_number !== formData.bank_confirm_account_number
        ) {
          newErrors.bank_confirm_account_number =
            "Account numbers do not match";
        }
        if (!formData.bank_ifsc_code)
          newErrors.bank_ifsc_code = "IFSC code is required";
        if (!formData.bank_account_type)
          newErrors.bank_account_type = "Please select account type";
      }
    }

    if (step === 5) {
      if (!formData.location_verified && !formData.location_consent) {
        newErrors.location_consent = "You must consent to location capture";
      }
    }

    if (step === 6) {
      if (!formData.terms_accepted)
        newErrors.terms_accepted = "You must accept the Terms of Use";
      if (!formData.agreement_accepted)
        newErrors.agreement_accepted =
          "You must accept the Distributor Agreement";
      if (!formData.code_of_conduct_accepted)
        newErrors.code_of_conduct_accepted =
          "You must accept the Code of Conduct";
    }

    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  };

  // ========== HANDLE NEXT ==========
  const handleNext = () => {
    const isStepCompleted = () => {
      switch (currentStep) {
        case 0:
          return formData.aadhaar_verified || false;
        case 1:
          return formData.sponsor_id && formData.sponsor_id.trim().length > 0;
        case 2:
          return formData.aadhaar_verified || false;
        case 3:
          return formData.pan_verified || false;
        case 4:
          return formData.bank_verified || false;
        case 5:
          return formData.location_verified || false;
        default:
          return false;
      }
    };

    if (isStepCompleted()) {
      console.log("✅ Step already completed, moving to next");
      setCurrentStep((prev) => prev + 1);
      setFormError(null);
      return;
    }

    if (validateStep(currentStep)) {
      setCurrentStep((prev) => prev + 1);
      setFormError(null);
    }
  };

  const handleBack = () => {
    setCurrentStep((prev) => prev - 1);
    setFormError(null);
  };

  const handleStepClick = (index: number) => {
    setCurrentStep(index);
    setFormError(null);
  };

  const handleChange = (
    e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>,
  ) => {
    const { name, value, type } = e.target;
    const checked = (e.target as HTMLInputElement).checked;

    setFormData((prev) => ({
      ...prev,
      [name]: type === "checkbox" ? checked : value,
    }));

    if (errors[name]) {
      setErrors((prev) => {
        const newErrors = { ...prev };
        delete newErrors[name];
        return newErrors;
      });
    }
  };

  const handleSubmit = async () => {
    if (!validateStep(6)) return;

    setIsLoading(true);
    setFormError(null);
    setSuccessMessage(null);

    try {
      const payload = {
        full_name: formData.full_name,
        date_of_birth: formData.date_of_birth,
        email: formData.email,
        mobile: formData.mobile,
        sponsor_id: formData.sponsor_id || undefined,
        placement_leg: formData.placement_leg,
        aadhaar_number: formData.aadhaar_number,
        aadhaar_verified: formData.aadhaar_verified,
        pan_number: formData.pan_number,
        pan_verified: formData.pan_verified,
        bank_details: {
          account_holder_name: formData.bank_account_holder_name,
          account_number: formData.bank_account_number,
          ifsc_code: formData.bank_ifsc_code,
          bank_name: formData.bank_name,
          branch: formData.bank_branch,
          account_type: formData.bank_account_type,
        },
        location: formData.location_consent
          ? {
            latitude: formData.latitude,
            longitude: formData.longitude,
            consent_granted: true,
          }
          : { consent_granted: false },
        terms_accepted: {
          terms_of_use: true,
          distributor_agreement: true,
          code_of_conduct: true,
          accepted_at: new Date().toISOString(),
        },
        account_type: "distributor",
      };

      console.log("Distributor Registration Payload:", payload);
      await new Promise((resolve) => setTimeout(resolve, 2000));

      setSuccessMessage(
        "Your distributor application has been submitted successfully! Our team will review and contact you within 3-5 business days.",
      );

      localStorage.setItem(
        "distributor_application",
        JSON.stringify({
          status: "submitted",
          submitted_at: new Date().toISOString(),
        }),
      );

      setTimeout(() => {
        router.push("/");
      }, 3000);
    } catch (err: unknown) {
      setFormError(readCaughtMessage(err, "message") || "Submission failed. Please try again.");
    } finally {
      setIsLoading(false);
    }
  };

  const showEmailCheck = currentStep === -1;
  const StepComponent = !showEmailCheck ? steps[currentStep]?.component : null;

  return (
    <RegistrationLayout showHeader={showEmailCheck}>
      {showEmailCheck ? (
        <div className="min-h-screen flex  items-center justify-center bg-white rounded-2xl shadow-xl border border-gray-100">
          <EmailCheckScreen
            onCheckStatus={handleCheckStatus}
            isLoading={isLoading}
            statusMessage={statusMessage}
            statusType={statusType}
            mobile={email}
            setMobile={setEmail}
            error={emailError}
            onClear={handleClearStatus}
            checkResponse={checkResponse}  // ✅ NEW — modal trigger karne ke liye
          />
        </div>
      ) : (
        <>
          <div className="mb-4">
            <ProgressSteps
              steps={steps}
              currentStep={currentStep}
              onStepClick={handleStepClick}
            />
          </div>

          <div className="bg-white rounded-2xl shadow-xl border border-gray-100 p-6 sm:p-8">
            <div className="flex items-center justify-between mb-6">
              <span className="text-xs text-gray-400 font-medium">
                Step {currentStep + 1} of {totalSteps}
              </span>
              <div className="flex items-center gap-2">
                <div className="w-20 h-1.5 bg-gray-100 rounded-full overflow-hidden">
                  <div
                    className="h-full bg-gradient-to-r from-[#F9C744] to-[#E6B33D] rounded-full transition-all duration-500"
                    style={{
                      width: `${((currentStep + 1) / totalSteps) * 100}%`,
                    }}
                  />
                </div>
                <span className="text-xs text-[#F9C744] font-medium">
                  {Math.round(((currentStep + 1) / totalSteps) * 100)}%
                </span>
              </div>
              <span className="text-xs text-[#F9C744] font-medium">
                {Math.round(((currentStep + 1) / totalSteps) * 100)}%
              </span>
            </div>

            {formError && <ErrorMessage message={formError} />}
            {successMessage && <SuccessMessage message={successMessage} />}

            {StepComponent && (
              <StepComponent
                data={formData}
                errors={errors}
                onChange={handleChange}
                onNext={handleNext}
                onBack={handleBack}
                onSubmit={handleSubmit}
                isLoading={isLoading}
                onBackToMobile={handleBackToEmailCheck}
              />
            )}
          </div>
        </>
      )}

      {/* New Registration Confirmation Modal */}
      {showNewRegistrationModal && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/60 backdrop-blur-sm animate-in fade-in duration-200">
          <div className="bg-white rounded-2xl max-w-md w-full mx-4 p-6 shadow-2xl relative animate-in slide-in-from-bottom-4 duration-300">
            <button
              type="button"
              onClick={() => setShowNewRegistrationModal(false)}
              className="absolute right-4 top-4 text-gray-400 hover:text-gray-600 transition-colors rounded-full hover:bg-gray-100 p-1"
            >
              <X className="w-5 h-5" />
            </button>

            <div className="flex justify-center mb-4">
              <div className="w-20 h-20 rounded-full bg-red-50 flex items-center justify-center border-4 border-red-100">
                <AlertTriangle className="w-10 h-10 text-red-500" />
              </div>
            </div>

            <h3 className="text-2xl font-bold text-center text-[#06101E] mb-2">
              Start New Registration?
            </h3>

            <p className="text-gray-500 text-center text-sm mb-6 leading-relaxed">
              This will clear all your current progress and data. You&apos;ll start
              fresh from the beginning.
            </p>

            <div className="bg-red-50 border border-red-200 rounded-xl p-4 mb-6">
              <div className="flex items-start gap-3">
                <Trash2 className="w-5 h-5 text-red-500 flex-shrink-0 mt-0.5" />
                <div>
                  <p className="text-sm font-medium text-red-700">
                    This action cannot be undone
                  </p>
                  <p className="text-xs text-red-600 mt-1">
                    All your entered information, verification status, and
                    progress will be permanently cleared.
                  </p>
                </div>
              </div>
            </div>

            <div className="flex gap-3">
              <Button
                type="button"
                onClick={() => setShowNewRegistrationModal(false)}
                className="flex-1 bg-gray-100 hover:bg-gray-200 text-gray-700 font-medium py-3 rounded-xl transition-all duration-200"
              >
                Cancel
              </Button>
              <Button
                type="button"
                onClick={handleNewRegistration}
                disabled={isResetting}
                className="flex-1 bg-red-500 hover:bg-red-600 text-white font-medium py-3 rounded-xl transition-all duration-200 flex items-center justify-center gap-2 disabled:opacity-50 disabled:cursor-not-allowed"
              >
                {isResetting ? (
                  <>
                    <Loader2 className="w-4 h-4 animate-spin" />
                    Clearing...
                  </>
                ) : (
                  <>
                    <RefreshCw className="w-4 h-4" />
                    Yes, Start New
                  </>
                )}
              </Button>
            </div>
          </div>
        </div>
      )}
    </RegistrationLayout>
  );
};

// Helper Components
const ErrorMessage = ({ message }: { message: string }) => (
  <div className="mb-4 text-sm text-red-600 bg-red-50 p-4 rounded-xl border border-red-100 flex items-start gap-2">
    <span className="text-lg flex-shrink-0">❌</span>
    <span>{message}</span>
  </div>
);

const SuccessMessage = ({ message }: { message: string }) => (
  <div className="mb-4 text-sm text-green-600 bg-green-50 p-4 rounded-xl border border-green-100 flex items-start gap-2">
    <span className="text-lg flex-shrink-0">✅</span>
    <span>{message}</span>
  </div>
);

export default DistributorRegistrationFlow;

// components/distributor/registration/components/common/DatePicker.tsx

"use client";

import React, { useState, useEffect, useRef } from "react";

interface DatePickerProps {
  value: string;
  onChange: (e: React.ChangeEvent<HTMLInputElement>) => void;
  error?: string;
  helperText?: string;
  label: string;
  required?: boolean;
}

// ✅ Helper: convert a Date to "YYYY-MM-DD" using LOCAL parts (no UTC shift)
const toLocalYMD = (date: Date): string => {
  const year = date.getFullYear();
  const month = String(date.getMonth() + 1).padStart(2, "0");
  const day = String(date.getDate()).padStart(2, "0");
  return `${year}-${month}-${day}`;
};

// ✅ Helper: parse "YYYY-MM-DD" (or ISO string) as a LOCAL Date
const parseLocalYMD = (dateStr: string): Date | null => {
  if (!dateStr) return null;
  const [year, month, day] = dateStr.split("T")[0].split("-").map(Number);
  if (!year || !month || !day) return null;
  return new Date(year, month - 1, day);
};

// Calendar Popover Component
const CalendarPopover: React.FC<{
  currentMonth: Date;
  months: string[];
  days: (Date | null)[];
  selectedDate: Date | null;
  onMonthChange: (increment: number) => void;
  onMonthSelect: (monthIndex: number) => void;
  onYearSelect: (year: number) => void;
  onDateSelect: (date: Date) => void;
  onClose: () => void;
  formatDisplayDate: (dateStr: string) => string;
  showMonthPicker: boolean;
  setShowMonthPicker: (show: boolean) => void;
  showYearPicker: boolean;
  setShowYearPicker: (show: boolean) => void;
}> = ({
  currentMonth,
  months,
  days,
  selectedDate,
  onMonthChange,
  onMonthSelect,
  onYearSelect,
  onDateSelect,
  onClose,
  formatDisplayDate,
  showMonthPicker,
  setShowMonthPicker,
  showYearPicker,
  setShowYearPicker,
}) => {
  const today = new Date();
  const maxDate = new Date(
    today.getFullYear() - 18,
    today.getMonth(),
    today.getDate(),
  );

  const monthPickerRef = useRef<HTMLDivElement>(null);
  const yearPickerRef = useRef<HTMLDivElement>(null);
  const currentYear = currentMonth.getFullYear();

  // Generate years (1900 to current year - 18)
  const years = [];
  const maxYear = new Date().getFullYear() - 18;
  for (let year = maxYear; year >= 1900; year--) {
    years.push(year);
  }

  // Close pickers on outside click
  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (
        monthPickerRef.current &&
        !monthPickerRef.current.contains(event.target as Node)
      ) {
        setShowMonthPicker(false);
      }
      if (
        yearPickerRef.current &&
        !yearPickerRef.current.contains(event.target as Node)
      ) {
        setShowYearPicker(false);
      }
    };
    document.addEventListener("mousedown", handleClickOutside);
    return () => document.removeEventListener("mousedown", handleClickOutside);
  }, [setShowMonthPicker, setShowYearPicker]);

  return (
    <div className="absolute top-full left-0 mt-2 bg-white rounded-xl shadow-2xl border border-gray-200 p-4 w-[320px] z-50">
      {/* Month/Year Header */}
      <div className="flex items-center justify-between mb-4">
        <button
          type="button"
          onClick={() => onMonthChange(-1)}
          className="p-2 hover:bg-gray-100 rounded-lg transition-colors hover:scale-110 active:scale-95"
          aria-label="Previous month"
        >
          <svg
            className="w-5 h-5 text-gray-700"
            fill="none"
            stroke="currentColor"
            viewBox="0 0 24 24"
          >
            <path
              strokeLinecap="round"
              strokeLinejoin="round"
              strokeWidth={2}
              d="M15 19l-7-7 7-7"
            />
          </svg>
        </button>

        <div className="flex items-center gap-2">
          {/* Month Picker Button */}
          <div className="relative">
            <button
              type="button"
              onClick={() => {
                setShowMonthPicker(!showMonthPicker);
                setShowYearPicker(false);
              }}
              className="font-semibold text-gray-900 hover:bg-gray-100 px-3 py-1 rounded-lg transition-colors flex items-center gap-1 min-w-[70px] justify-center"
            >
              {months[currentMonth.getMonth()]}
              <svg
                className={`w-4 h-4 text-gray-500 transition-transform ${showMonthPicker ? "rotate-180" : ""}`}
                fill="none"
                stroke="currentColor"
                viewBox="0 0 24 24"
              >
                <path
                  strokeLinecap="round"
                  strokeLinejoin="round"
                  strokeWidth={2}
                  d="M19 9l-7 7-7-7"
                />
              </svg>
            </button>

            {/* Month Picker Dropdown */}
            {showMonthPicker && (
              <div
                ref={monthPickerRef}
                className="absolute top-full left-0 mt-1 bg-white rounded-lg shadow-lg border border-gray-200 p-2 grid grid-cols-3 gap-1 w-[180px] z-50"
              >
                {months.map((month, index) => (
                  <button
                    key={month}
                    type="button"
                    onClick={() => {
                      onMonthSelect(index);
                      setShowMonthPicker(false);
                    }}
                    className={`px-2 py-1.5 text-sm rounded-lg transition-all hover:bg-[#F9C744]/20 ${
                      currentMonth.getMonth() === index
                        ? "bg-[#F9C744] text-black font-medium"
                        : "text-gray-700 hover:scale-105"
                    }`}
                  >
                    {month}
                  </button>
                ))}
              </div>
            )}
          </div>

          {/* Year Picker Button */}
          <div className="relative">
            <button
              type="button"
              onClick={() => {
                setShowYearPicker(!showYearPicker);
                setShowMonthPicker(false);
              }}
              className="font-semibold text-gray-900 hover:bg-gray-100 px-3 py-1 rounded-lg transition-colors flex items-center gap-1 min-w-[70px] justify-center"
            >
              {currentYear}
              <svg
                className={`w-4 h-4 text-gray-500 transition-transform ${showYearPicker ? "rotate-180" : ""}`}
                fill="none"
                stroke="currentColor"
                viewBox="0 0 24 24"
              >
                <path
                  strokeLinecap="round"
                  strokeLinejoin="round"
                  strokeWidth={2}
                  d="M19 9l-7 7-7-7"
                />
              </svg>
            </button>

            {/* Year Picker Dropdown */}
            {showYearPicker && (
              <div
                ref={yearPickerRef}
                className="absolute top-full left-0 mt-1 bg-white rounded-lg shadow-lg border border-gray-200 p-2 z-50 max-h-[200px] overflow-y-auto w-[100px]"
              >
                {years.map((year) => (
                  <button
                    key={year}
                    type="button"
                    onClick={() => {
                      onYearSelect(year);
                      setShowYearPicker(false);
                    }}
                    className={`w-full px-3 py-1.5 text-sm rounded-lg transition-all hover:bg-[#F9C744]/20 text-left ${
                      currentYear === year
                        ? "bg-[#F9C744] text-black font-medium"
                        : "text-gray-700 hover:scale-105"
                    }`}
                  >
                    {year}
                  </button>
                ))}
              </div>
            )}
          </div>
        </div>

        <button
          type="button"
          onClick={() => onMonthChange(1)}
          className="p-2 hover:bg-gray-100 rounded-lg transition-colors hover:scale-110 active:scale-95"
          aria-label="Next month"
        >
          <svg
            className="w-5 h-5 text-gray-700"
            fill="none"
            stroke="currentColor"
            viewBox="0 0 24 24"
          >
            <path
              strokeLinecap="round"
              strokeLinejoin="round"
              strokeWidth={2}
              d="M9 5l7 7-7 7"
            />
          </svg>
        </button>
      </div>

      {/* Day Names */}
      <div className="grid grid-cols-7 gap-1 mb-2">
        {["Su", "Mo", "Tu", "We", "Th", "Fr", "Sa"].map((day) => (
          <div
            key={day}
            className="text-center text-xs font-medium text-gray-500 py-1"
          >
            {day}
          </div>
        ))}
      </div>

      {/* Days Grid */}
      <div className="grid grid-cols-7 gap-1">
        {days.map((day, index) => {
          if (!day) {
            return <div key={`empty-${index}`} className="h-9" />;
          }

          const isSelected =
            selectedDate && day.toDateString() === selectedDate.toDateString();
          const isToday = day.toDateString() === new Date().toDateString();
          const isDisabled = day > maxDate;

          return (
            <button
              key={`day-${day.getFullYear()}-${day.getMonth()}-${day.getDate()}`}
              type="button"
              onClick={() => !isDisabled && onDateSelect(day)}
              disabled={isDisabled}
              className={`
                h-9 rounded-lg text-sm font-medium transition-all duration-200
                ${isDisabled ? "text-gray-300 cursor-not-allowed opacity-50" : "text-gray-900 hover:bg-[#F9C744]/20 hover:scale-105 active:scale-95"}
                ${isSelected ? "bg-[#F9C744] text-black hover:bg-[#e5b33a] shadow-md" : ""}
                ${isToday && !isSelected ? "border-2 border-[#F9C744] text-gray-900" : ""}
                ${!isDisabled && !isSelected ? "hover:bg-[#F9C744]/10" : ""}
              `}
            >
              {day.getDate()}
            </button>
          );
        })}
      </div>

      {/* Footer */}
      <div className="mt-3 pt-3 border-t border-gray-200 flex justify-between items-center">
        <span className="text-xs text-gray-600">
          {selectedDate
            ? `Selected: ${formatDisplayDate(toLocalYMD(selectedDate))}`
            : "Select a date"}
        </span>
        <button
          type="button"
          onClick={onClose}
          className="text-xs text-[#F9C744] hover:text-[#e5b33a] font-medium transition-colors hover:underline"
        >
          Close
        </button>
      </div>
    </div>
  );
};

export const DatePicker: React.FC<DatePickerProps> = ({
  value,
  onChange,
  error,
  helperText,
  label,
  required,
}) => {
  const [showCalendar, setShowCalendar] = useState(false);
  const [showMonthPicker, setShowMonthPicker] = useState(false);
  const [showYearPicker, setShowYearPicker] = useState(false);

  // ✅ Initialize selectedDate as LOCAL date
  const [selectedDate, setSelectedDate] = useState<Date | null>(() =>
    parseLocalYMD(value),
  );
  const [currentMonth, setCurrentMonth] = useState(new Date());
  const pickerRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (
        pickerRef.current &&
        !pickerRef.current.contains(event.target as Node)
      ) {
        setShowCalendar(false);
        setShowMonthPicker(false);
        setShowYearPicker(false);
      }
    };
    document.addEventListener("mousedown", handleClickOutside);
    return () => document.removeEventListener("mousedown", handleClickOutside);
  }, []);

  // ✅ Sync selectedDate when parent's `value` changes (e.g., after API fetch)
  useEffect(() => {
    setSelectedDate(parseLocalYMD(value));
  }, [value]);

  const months = [
    "Jan",
    "Feb",
    "Mar",
    "Apr",
    "May",
    "Jun",
    "Jul",
    "Aug",
    "Sep",
    "Oct",
    "Nov",
    "Dec",
  ];

  const getDaysInMonth = (date: Date) => {
    const year = date.getFullYear();
    const month = date.getMonth();
    const firstDay = new Date(year, month, 1);
    const lastDay = new Date(year, month + 1, 0);
    const days: (Date | null)[] = [];
    const startingDay = firstDay.getDay();

    for (let i = 0; i < startingDay; i++) {
      days.push(null);
    }

    for (let i = 1; i <= lastDay.getDate(); i++) {
      days.push(new Date(year, month, i));
    }

    return days;
  };

  const handleDateSelect = (date: Date) => {
    setSelectedDate(date);

    // ✅ Format as YYYY-MM-DD using LOCAL parts
    const formattedDate = toLocalYMD(date);

    onChange({
      target: { name: "date_of_birth", value: formattedDate },
    } as any);
    setShowCalendar(false);
  };

  const handleMonthChange = (increment: number) => {
    const newDate = new Date(currentMonth);
    newDate.setMonth(newDate.getMonth() + increment);
    setCurrentMonth(newDate);
  };

  const handleMonthSelect = (monthIndex: number) => {
    const newDate = new Date(currentMonth);
    newDate.setMonth(monthIndex);
    setCurrentMonth(newDate);
  };

  const handleYearSelect = (year: number) => {
    const newDate = new Date(currentMonth);
    newDate.setFullYear(year);
    setCurrentMonth(newDate);
  };

  // ✅ Parse the string as LOCAL date before formatting
  const formatDisplayDate = (dateStr: string) => {
    if (!dateStr) return "";
    const date = parseLocalYMD(dateStr);
    if (!date) return "";
    return date.toLocaleDateString("en-US", {
      year: "numeric",
      month: "short",
      day: "numeric",
    });
  };

  const days = getDaysInMonth(currentMonth);

  return (
    <div className="space-y-1.5 relative" ref={pickerRef}>
      <label className="text-sm font-medium text-gray-700 block">
        {label} {required && <span className="text-red-500">*</span>}
      </label>
      <div
        className="relative cursor-pointer"
        onClick={() => {
          setShowCalendar(!showCalendar);
          setShowMonthPicker(false);
          setShowYearPicker(false);
        }}
      >
        <input
          type="text"
          value={formatDisplayDate(value)}
          placeholder="Select date of birth"
          readOnly
          className={`w-full h-14 px-4 text-black rounded-xl border ${
            error ? "border-red-500" : "border-gray-200"
          } bg-white cursor-pointer focus:border-[#F9C744] focus:ring-2 focus:ring-[#F9C744]/20 transition-all duration-200 outline-none hover:border-gray-300`}
        />
        <div className="absolute right-4 top-1/2 -translate-y-1/2 pointer-events-none">
          <svg
            className="w-5 h-5 text-gray-400"
            fill="none"
            stroke="currentColor"
            viewBox="0 0 24 24"
          >
            <path
              strokeLinecap="round"
              strokeLinejoin="round"
              strokeWidth={2}
              d="M8 7V3m8 4V3m-9 8h10M5 21h14a2 2 0 002-2V7a2 2 0 00-2-2H5a2 2 0 00-2 2v12a2 2 0 002 2z"
            />
          </svg>
        </div>
      </div>
      {error && <p className="text-xs text-red-500 mt-1">{error}</p>}
      {helperText && !error && (
        <p className="text-xs text-gray-400 mt-1">{helperText}</p>
      )}

      {showCalendar && (
        <CalendarPopover
          currentMonth={currentMonth}
          months={months}
          days={days}
          selectedDate={selectedDate}
          onMonthChange={handleMonthChange}
          onMonthSelect={handleMonthSelect}
          onYearSelect={handleYearSelect}
          onDateSelect={handleDateSelect}
          onClose={() => {
            setShowCalendar(false);
            setShowMonthPicker(false);
            setShowYearPicker(false);
          }}
          formatDisplayDate={formatDisplayDate}
          showMonthPicker={showMonthPicker}
          setShowMonthPicker={setShowMonthPicker}
          showYearPicker={showYearPicker}
          setShowYearPicker={setShowYearPicker}
        />
      )}
    </div>
  );
};

