      return;
    }
    if (isDataLoadedFromAPI) {
      setIsDataLoadedFromAPI(false);
      setHasBankData(false);
    }
    setBankError("");
    const value = e.target.value
      .toUpperCase()
      .replace(/[^A-Z0-9]/g, "")
