// components/distributor/registration/components/layout/RegistrationLayout.tsx

"use client";

import React, { useMemo } from "react";
import { Logo } from "@/components/common/Logo";
import ConstellationBackground from "@/components/common/ConstellationBackground";

interface RegistrationLayoutProps {
    children: React.ReactNode;
    showHeader?: boolean;
}

export const RegistrationLayout: React.FC<RegistrationLayoutProps> = ({
    children,
    showHeader = true,
}) => {
    return (
        <div className="fixed inset-0 flex bg-[#FAF8F4] overflow-hidden">
            <LeftPanel />

            {/* 3. RIGHT PANEL - PURE WHITE */}
            <RightPanel showHeader={showHeader}>{children}</RightPanel>
        </div>
    );
};

const LeftPanel = () => {
    // Generate fixed positions for dots - only runs once
    const dotPositions = useMemo(() => {
        const positions = [];
        for (let i = 0; i < 20; i++) {
            positions.push({
                top: 5 + Math.floor(Math.random() * 90),
                left: 5 + Math.floor(Math.random() * 90),
                delay: (i % 5) * 0.6,
            });
        }
        return positions;
    }, []);

    return (
        <div className="hidden lg:flex lg:w-5/12 h-full flex-shrink-0 overflow-hidden bg-gradient-to-br from-[#0F2038] via-[#06101E] to-[#030810] p-12 flex-col justify-between relative">
            {/* Constellation Background */}
            <ConstellationBackground
                starColor="#F9C744"
                starCount={40}
                connectionDistance={18}
                animationSpeed={1.0}
                showParticles={true}
                particleCount={15}
                showShootingStars={true}
                shootingStarCount={3}
                glowIntensity={1.0}
                interactive={true}
                onStarClick={(starId) => {
                    console.log(`✨ Star ${starId} clicked!`);
                }}
            />

            {/* Background patterns - kept for subtle overlay */}
            <div className="absolute inset-0 opacity-[0.03] pointer-events-none z-0">
                <div
                    className="absolute inset-0"
