// =====================================================
// CONSTANTS
// =====================================================

const PAGE_SIZES = [5, 10, 20, 50] as const;

const PANEL =
    "rounded-[18px] border border-[#E7EAF0] bg-white shadow-[0_4px_22px_rgba(16,24,40,0.035)]";

// =====================================================
// NORMALIZE VALUE
// =====================================================

function normalize(value: unknown): string {
    if (value === null || value === undefined || value === "") {
        return "—";
    }

    return String(value)
        .replace(/[_-]/g, " ")
        .replace(/\b\w/g, (c) => c.toUpperCase());
}

// =====================================================
// GET ACCOUNT ID
// =====================================================

function getAccountId(item: MyAccountRecord): string {
    return String(
        item.account_id ||
        item.ba_id ||
        item.id ||
        "—"
    );
}

// =====================================================
// GET RANK
// =====================================================

function getRank(item: MyAccountRecord): string {
    return normalize(item.rank_name ?? item.rank);
}

// =====================================================
// GET STATUS
// =====================================================

function getStatus(item: MyAccountRecord): string {
    return normalize(item.status ?? item.membership_status);
}

// =====================================================
// GET ACCOUNT TYPE
// =====================================================

function getAccountType(item: MyAccountRecord): string {
    return normalize(item.type);
}

// =====================================================
// STATUS COLORS
// =====================================================

function statusColors(status: string): string {
    const s = status.toLowerCase();

    if (
        ["activated", "active", "qualified", "approved"].some(
            (v) => s.includes(v)
        )
    ) {
        return "border-[#D8EBDF] bg-[#EFF8F2] text-[#287A50]";
    }

    if (
        ["rejected", "blocked", "inactive", "suspended"].some(
            (v) => s.includes(v)
        )
    ) {
        return "border-[#F2DBDB] bg-[#FFF4F4] text-[#B44F4F]";
    }

    if (
        ["pending", "processing"].some(
            (v) => s.includes(v)
        )
    ) {
        return "border-[#F0E4D0] bg-[#FFF9EE] text-[#9D752D]";
    }

    return "border-[#E7EAF0] bg-[#F7F8FA] text-[#667085]";
}

// =====================================================
// API ERROR MESSAGE
// =====================================================

function getApiErrorMessage(error: unknown): string {
    if (typeof error === "string") {
        return error;
    }

    if (!error || typeof error !== "object") {
        return "Unable to load accounts. Please try again.";
    }

    const apiError = error as {
        data?: unknown;
        error?: string;
        message?: string;
    };

    if (
        apiError.data &&
        typeof apiError.data === "object" &&
        "message" in apiError.data
    ) {
        const message = (
            apiError.data as { message?: unknown }
        ).message;

        if (typeof message === "string" && message.trim()) {
            return message;
        }
    }

    if (apiError.error) {
        return apiError.error;
    }

    if (apiError.message) {
        return apiError.message;
    }

    return "Unable to load accounts. Please try again.";
}

// =====================================================
// MY ACCOUNTS PAGE
// =====================================================

export default function MyAccountsPage({
    accounts,
    loading = false,
    fetching = false,
    error = null,
    onRefresh,
    onBack,
    demoAccounts,
    className = "",
}: MyAccountsPageProps) {

    // =================================================
    // LOCAL STATES
    // =================================================

    const [search, setSearch] = useState("");
    const [pageSize, setPageSize] = useState<number>(10);
    const [page, setPage] = useState(1);
    const [sortAscending, setSortAscending] = useState(true);

    // =================================================
    // GET MY ACCOUNTS API
    // =================================================

    const {
        data: myAccountsResponse,
        isLoading: apiLoading,
        isFetching: apiFetching,
        isError: apiIsError,
        error: apiError,
        refetch,
    } = useGetMyAccountsQuery();

    // =================================================
    // API RESPONSE DATA
    // =================================================

    const apiAccounts: MyAccountRecord[] =
        myAccountsResponse?.data ?? [];

    // =================================================
    // ACCOUNT SOURCE
    // =================================================

    // External accounts have priority.
    // Otherwise, use live API data.
    // Demo data is only used when API data is not available.

    const source: MyAccountRecord[] =
        accounts ?? (
            myAccountsResponse
                ? apiAccounts
                : demoAccounts ?? []
        );

    // =================================================
    // TOTAL ACCOUNTS
    // =================================================

    const totalAccounts =
        accounts !== undefined
            ? source.length
            : myAccountsResponse?.total ?? source.length;

    // =================================================
    // LOADING & FETCHING
    // =================================================

    const isLoading =
        loading || (accounts === undefined && apiLoading);

    const isFetching =
        fetching || (accounts === undefined && apiFetching);

    // =================================================
    // ERROR HANDLING
    // =================================================

    const displayError =
        error ??
        (
            accounts === undefined && apiIsError
                ? getApiErrorMessage(apiError)
                : null
        );

    // =================================================
    // REFRESH API
    // =================================================

    const handleRefresh = () => {
        if (onRefresh) {
            void onRefresh();
            return;
        }

        void refetch();
    };

    // =================================================
    // SEARCH HANDLER
    // =================================================

    const handleSearch = (value: string) => {
        setSearch(value);
        setPage(1);
    };

    // =================================================
    // FILTER & SORT RECORDS
    // =================================================

    const rows = useMemo(() => {
        const q = search.trim().toLowerCase();

        return source
            .filter((item) => {
                if (!q) return true;

                return [
                    getAccountId(item),
                    getRank(item),
                    getStatus(item),
                    getAccountType(item),
                    String(item.member_id ?? ""),
                    item.created_at || "",
                ].some((value) =>
                    value.toLowerCase().includes(q)
                );
            })
            .sort((a, b) =>
                getAccountId(a).localeCompare(
                    getAccountId(b),
                    undefined,
                    { numeric: true }
                ) * (sortAscending ? 1 : -1)
            );
    }, [source, search, sortAscending]);

    // =================================================
    // PAGINATION
    // =================================================

    const totalPages = Math.max(
        1,
        Math.ceil(rows.length / pageSize)
    );

    const currentPage = Math.min(page, totalPages);

    const firstIndex = (currentPage - 1) * pageSize;

    const visibleRows = rows.slice(
        firstIndex,
        firstIndex + pageSize
    );

    const start = rows.length
        ? firstIndex + 1
        : 0;

    const end = Math.min(
        firstIndex + pageSize,
        rows.length
    );

    // =================================================
    // COMPONENT UI
    // =================================================

    return (
        <main
            className={`min-h-[100dvh] flex-1 w-full min-w-0 text-[#1D2939] ${className}`}
            style={{
                fontFamily: "'Lato', Arial, sans-serif",
            }}
        >
            <div className="mx-auto max-w-[1500px] space-y-5">

                {/* =====================================
                    HEADER
                ===================================== */}

                <header className="flex flex-wrap items-start justify-between gap-3">

                    <div className="flex min-w-0 items-start gap-3">

                        {onBack && (
                            <button
                                type="button"
                                onClick={onBack}
                                aria-label="Go back"
                                className="mt-0.5 inline-flex h-9 w-9 shrink-0 items-center justify-center rounded-[10px] border border-[#E5E8EE] bg-white text-[#354052] transition hover:bg-[#F3F4F6] focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[#344054]/30"
                            >
                                <ArrowLeft size={16} />
                            </button>
                        )}

                        <div className="min-w-0">

                            <div className="mb-1 flex items-center gap-2 text-[11px] font-semibold text-[#8792A2]">
                                <span>Distributor</span>
                                <span className="text-[#BBC2CE]">/</span>
                                <span>My Accounts</span>
                            </div>

                            <h1 className="text-[22px] font-bold tracking-[-0.035em] text-[#17212F] sm:text-[26px]">
                                My Accounts
                            </h1>

                            <p className="mt-1 text-[12px] leading-5 text-[#758195]">
                                View and manage your distributor account records.
                            </p>

                        </div>
                    </div>

                    {/* REFRESH BUTTON */}

                    <button
                        type="button"
                        onClick={handleRefresh}
                        disabled={isLoading || isFetching}
                        className="inline-flex h-9 items-center gap-2 rounded-[10px] border border-[#DCE1E8] bg-white px-3.5 text-[11px] font-semibold text-[#344054] transition hover:border-[#BFC7D2] hover:bg-[#F9FAFB] disabled:cursor-not-allowed disabled:opacity-50"
                    >
                        <RefreshCw
                            size={14}
                            className={isFetching ? "animate-spin" : ""}
                        />
                        Refresh
                    </button>

                </header>

                {/* =====================================
                    ACCOUNT DIRECTORY
                ===================================== */}

                <section
                    aria-label="My Accounts"
                    className={`${PANEL} overflow-hidden`}
                >

                    {/* =================================
                        SECTION HEADER
                    ================================= */}

                    <div className="flex flex-wrap items-center justify-between gap-3 border-b border-[#EEF0F3] p-4 sm:px-5 sm:py-4">

                        <div className="flex min-w-0 items-center gap-2.5">

                            <span className="flex h-9 w-9 shrink-0 items-center justify-center rounded-[11px] bg-[#EFF3F8] text-[#61758D]">
                                <UsersRound size={17} />
                            </span>

                            <div>

                                <h2 className="text-[14px] font-bold text-[#202B3A] sm:text-[15px]">
                                    Account Directory
                                </h2>

                                <p className="mt-0.5 text-[10.5px] text-[#8A95A5]">
                                    Account ID, rank and activation status
                                </p>

                            </div>

                        </div>

                        {/* TOTAL ACCOUNT COUNT */}

                        <span className="rounded-full border border-[#E7EAF0] bg-[#FAFBFC] px-3 py-1 text-[10.5px] font-semibold text-[#68768A]">
                            {totalAccounts}{" "}
                            {totalAccounts === 1 ? "account" : "accounts"}
                        </span>

                    </div>

                    {/* =================================
                        SEARCH SECTION
                    ================================= */}

                    <div className="flex flex-wrap items-center justify-between gap-3 px-4 py-4 sm:px-5">

                        <div className="relative w-full max-w-[360px]">

                            <Search
                                size={16}
                                className="pointer-events-none absolute left-3.5 top-1/2 -translate-y-1/2 text-[#98A2B3]"
                            />

                            <input
                                value={search}
                                onChange={(e) =>
                                    handleSearch(e.target.value)
                                }
                                type="search"
                                aria-label="Quick search accounts"
                                placeholder="Search account ID, rank, status..."
                                className="h-10 w-full rounded-[10px] border border-[#E1E5EC] bg-[#F9FAFC] py-2 pl-10 pr-9 text-[12px] text-[#253143] outline-none transition placeholder:text-[#A6AFBC] focus:border-[#9BA6B5] focus:bg-white focus:ring-2 focus:ring-[#98A2B3]/15"
                            />

                            {search && (
                                <button
                                    type="button"
                                    aria-label="Clear search"
                                    onClick={() => handleSearch("")}
                                    className="absolute right-2.5 top-1/2 -translate-y-1/2 rounded p-1 text-[#818B9A] hover:text-black"
                                >
                                    <X size={14} />
                                </button>
                            )}

                        </div>

                        <span className="text-[11px] text-[#919BAB]">
                            {rows.length} matching records
                        </span>

                    </div>

                    {/* =================================
                        ERROR MESSAGE
                    ================================= */}

                    {displayError && (
                        <div
                            role="alert"
                            className="mx-4 mb-4 flex items-center gap-2 rounded-[10px] border border-[#F0D6D6] bg-[#FFF6F6] px-3.5 py-3 text-[12px] text-[#A94343] sm:mx-5"
                        >
                            <CircleHelp
                                size={16}
                                className="shrink-0"
                            />
                            {displayError}
                        </div>
                    )}

                    {/* =================================
                        LOADING STATE
                    ================================= */}

                    {isLoading ? (

                        <div className="flex min-h-[280px] flex-col items-center justify-center gap-3 text-[12px] text-[#7F8B9C]">

                            <Loader2
                                size={26}
                                className="animate-spin text-[#53657C]"
                            />

                            Loading accounts...

                        </div>

                    ) : rows.length === 0 ? (

                        /* =================================
                           EMPTY STATE
                        ================================= */

                        <div className="flex min-h-[250px] flex-col items-center justify-center px-4 pb-6 text-center">

                            <span className="flex h-12 w-12 items-center justify-center rounded-[14px] bg-[#F2F4F7] text-[#9AA5B4]">
                                <Search size={21} />
                            </span>

                            <p className="mt-3 text-[13px] font-semibold text-[#344054]">
                                {search
                                    ? "No matching accounts"
                                    : "No accounts available"}
                            </p>

                            <p className="mt-1 max-w-[300px] text-[11px] leading-5 text-[#8B95A5]">
                                {search
                                    ? "Try another account ID, rank or status."
                                    : "Your accounts will appear here once provided by your backend."}
                            </p>

                            {search && (
                                <button
                                    type="button"
                                    onClick={() => handleSearch("")}
                                    className="mt-3 rounded-[9px] bg-[#171717] px-4 py-2 text-[11px] font-semibold text-white hover:bg-[#363636]"
                                >
                                    Clear search
                                </button>
                            )}

                            {!search && displayError && (
                                <button
                                    type="button"
                                    onClick={handleRefresh}
                                    className="mt-3 inline-flex items-center gap-2 rounded-[9px] border border-[#E5E8ED] px-4 py-2 text-[11px] font-semibold text-[#344054] hover:bg-[#F8F9FB]"
                                >
                                    <RefreshCw size={13} />
                                    Try Again
                                </button>
                            )}

                        </div>

