                                    <thead>

                                        <tr className="border-y border-[#ECEFF3] bg-[#F8F9FB] text-[10px] font-bold uppercase tracking-[0.065em] text-[#7D899A]">

                                            <th className="w-[46%] px-5 py-3.5">

                                                <button
                                                    type="button"
                                                    onClick={() => {
                                                        setSortAscending((v) => !v);
                                                        setPage(1);
                                                    }}
                                                    className="inline-flex items-center gap-1.5 transition hover:text-[#17212F]"
                                                    aria-label="Sort by account ID"
                                                >
                                                    Account ID

                                                    <ChevronDown
                                                        size={12}
                                                        className={`transition-transform ${
                                                            sortAscending
                                                                ? "rotate-180"
                                                                : ""
                                                        }`}
                                                    />

                                                </button>

                                            </th>

                                            <th className="w-[25%] px-5 py-3.5">
                                                Rank
                                            </th>

                                            <th className="w-[29%] px-5 py-3.5">
                                                Status
                                            </th>

                                        </tr>

                                    </thead>

                                    <tbody>

                                        {visibleRows.map((item, i) => {

                                            const status = getStatus(item);

                                            return (

                                                <tr
                                                    key={`${getAccountId(item)}-${item.member_id ?? item.id ?? i}`}
                                                    className="border-b border-[#F0F2F5] transition-colors last:border-b-0 hover:bg-[#FAFBFC]"
                                                >

                                                    <td className="break-all px-5 py-4 text-[12px] font-bold text-[#293448]">
                                                        {getAccountId(item)}
                                                    </td>

                                                    <td className="px-5 py-4 text-[12px] font-medium text-[#566276]">
                                                        {getRank(item)}
                                                    </td>

                                                    <td className="px-5 py-4">

                                                        <span
                                                            className={`inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[10.5px] font-semibold ${statusColors(status)}`}
                                                        >

                                                            <span className="h-1.5 w-1.5 rounded-full bg-current opacity-70" />

                                                            {status}

                                                        </span>

                                                    </td>

                                                </tr>

                                            );

                                        })}

                                    </tbody>

                                </table>

                            </div>

                            {/* =================================
                                MOBILE ACCOUNT CARDS
                            ================================= */}

                            <div className="space-y-2 px-4 pb-3 sm:hidden">

                                {visibleRows.map((item, i) => {

                                    const status = getStatus(item);

                                    return (

                                        <div
                                            key={`${getAccountId(item)}-${item.member_id ?? item.id ?? i}`}
                                            className="rounded-[12px] border border-[#E9ECF1] bg-[#FCFCFD] p-3.5"
                                        >

                                            <div className="flex flex-wrap items-start justify-between gap-2">

                                                <div className="min-w-0">

                                                    <p className="text-[10px] text-[#919BA9]">
                                                        Account ID
                                                    </p>

                                                    <p className="mt-1 break-all text-[12px] font-bold text-[#263143]">
                                                        {getAccountId(item)}
                                                    </p>

                                                </div>

                                                <span
                                                    className={`inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[10px] font-semibold ${statusColors(status)}`}
                                                >

                                                    <span className="h-1.5 w-1.5 rounded-full bg-current opacity-70" />

                                                    {status}

                                                </span>

                                            </div>

                                            <div className="mt-3 flex items-center gap-2 border-t border-[#E9ECF1] pt-3">

                                                <ShieldCheck
                                                    size={14}
                                                    className="text-[#8793A4]"
                                                />

                                                <span className="text-[10.5px] text-[#8793A4]">
                                                    Rank
                                                </span>

                                                <span className="ml-auto text-[11.5px] font-semibold text-[#405066]">
                                                    {getRank(item)}
                                                </span>

                                            </div>

                                        </div>

                                    );

                                })}

                            </div>

                        </>

                    )}

                    {/* =================================
                        PAGINATION FOOTER
                    ================================= */}

                    <footer className="flex flex-wrap items-center justify-between gap-x-4 gap-y-3 border-t border-[#EDF0F3] px-4 py-3.5 sm:px-5">

                        <div className="flex flex-wrap items-center gap-3">

                            {/* PAGE SIZE */}

                            <div className="relative">

                                <select
                                    value={pageSize}
                                    onChange={(e) => {
                                        setPageSize(Number(e.target.value));
                                        setPage(1);
                                    }}
                                    aria-label="Records per page"
                                    className="h-9 appearance-none rounded-[9px] border border-[#E5E8ED] bg-[#FAFAFB] py-1 pl-3 pr-8 text-[11px] font-semibold text-[#536175] outline-none focus:border-[#98A2B3]"
                                >

                                    {PAGE_SIZES.map((size) => (

                                        <option
                                            value={size}
                                            key={size}
                                        >
                                            {size}
                                        </option>

                                    ))}

                                </select>

                                <ChevronDown
                                    size={13}
                                    className="pointer-events-none absolute right-2.5 top-1/2 -translate-y-1/2 text-[#7F8C9D]"
                                />

                            </div>

                            {/* RECORD COUNT */}

                            <span className="text-[11px] text-[#8A95A5]">

                                Showing{" "}

                                <strong className="font-semibold text-[#405066]">
                                    {start}–{end}
                                </strong>

                                {" "}of{" "}

                                <strong className="font-semibold text-[#405066]">
                                    {rows.length}
                                </strong>

                                {" "}records

                            </span>

                        </div>

                        {/* PAGINATION BUTTONS */}

                        <nav
                            aria-label="Account pagination"
                            className="flex items-center gap-1.5"
                        >

                            <button
                                type="button"
                                aria-label="Previous page"
                                disabled={currentPage <= 1}
                                onClick={() => setPage(currentPage - 1)}
                                className="flex h-8 w-8 items-center justify-center rounded-[8px] border border-[#E7EAF0] bg-white text-[#596579] transition hover:bg-[#F5F6F8] disabled:cursor-not-allowed disabled:opacity-35"
                            >
                                <ChevronLeft size={15} />
                            </button>

                            <span className="flex h-8 min-w-8 items-center justify-center rounded-[8px] bg-[#171717] px-2 text-[11px] font-bold text-white">
                                {currentPage}
                            </span>

                            <span className="px-1 text-[11px] text-[#A0A8B5]">
                                / {totalPages}
                            </span>

                            <button
                                type="button"
                                aria-label="Next page"
                                disabled={currentPage >= totalPages}
                                onClick={() => setPage(currentPage + 1)}
                                className="flex h-8 w-8 items-center justify-center rounded-[8px] border border-[#E7EAF0] bg-white text-[#596579] transition hover:bg-[#F5F6F8] disabled:cursor-not-allowed disabled:opacity-35"
                            >
                                <ChevronRight size={15} />
                            </button>

                        </nav>

                    </footer>

                </section>

            </div>
        </main>
    );
}

