    useLazyGetCoolingOffEligibilityQuery,
    useWithdrawCoolingOffMutation,
} from "@/lib/redux/api/distributor/coolingOffApi";
import {
    ChevronDown,
    ChevronLeft,
    ChevronRight,
    Search,
    X,
    Package,
    Loader2,
    AlertCircle,
    ShieldOff,
