                    {/* Body */}
                    <div className="px-5 py-5">
                        <div className="rounded-[8px] border border-[#F0CFCF] bg-[#FDF2F2] p-3.5">
                            <div className="flex items-start gap-2.5">
                                <AlertCircle className="mt-0.5 h-4 w-4 flex-shrink-0 text-[#B24C4C]" />
