            ].map((item) => (
              <div
                key={item.label}
                className="min-w-0 rounded-[15px] border border-[#E7ECF3] px-2 py-4 text-center"
                style={{ backgroundColor: item.bg }}
              >
                <p
                  className="dashboard-number text-[29px] font-extrabold leading-tight sm:text-[34px]"
