  const [showFilters, setShowFilters] = useState(false);

  // --------------------------------------------------
  // My Referrals API
  // --------------------------------------------------
  const {
    data: response,
    isLoading,
    isFetching,
    isError,
    refetch,
  } = useGetDistributorMyReferralsQuery();

  // API response:
  // {
  //   success: true,
  //   data: [...referrals],
  //   pagination: { total, per_page, current_page, last_page }
  // }
  const referrals = response?.data ?? [];
  const totalReferrals = response?.pagination?.total ?? referrals.length;

  // --------------------------------------------------
  // Search / Filter
  // --------------------------------------------------
  const filteredReferrals = useMemo(() => {
    const query = searchQuery.trim().toLowerCase();
    return referrals
      .filter((member) => {
        const matchesText =
          !query ||
          (member.ba_id ?? "").toLowerCase().includes(query) ||
          (member.full_name ?? "").toLowerCase().includes(query) ||
          String(member.member_id).includes(query);
        return (
          matchesText &&
          (sideFilter === "all" || String(member.binary_side) === sideFilter)
        );
