                        {line.item_reference_id ?? `Line #${line.line_id}`}
                      </p>
                      <span className="mt-1.5 inline-flex rounded-md bg-[#F0F4FA] px-2 py-0.5 text-[10px] font-semibold text-[#45627E]">
                        {formatStatusLabel(line.delivery_status)}
