                      <span>CGST: {formatCurrency(tax.cgst_amount)}</span>
                      <span>SGST: {formatCurrency(tax.sgst_amount)}</span>
                      <span>IGST: {formatCurrency(tax.igst_amount)}</span>
                    </div>
