export type ReturnMethod = "doorstep" | "courier";


export interface ReturnItem {
  order_line_id: number;
  product_id: number;
  product_name: string;
  quantity: number;
  unit_price: number;
  gst_rate: number;
  subtotal: number;
  tax: number;
  line_total: number;
  reason?: string;
  image_paths?: string[];
  image_urls?: string[];
