"use client";

import { Loader2, ChevronDown, ArrowLeftRight } from "lucide-react";
import { useEffect, useRef, useState } from "react";
import { createPortal } from "react-dom";
import type { PendingPlacement } from "@/lib/redux/api/distributor/distributorPendingPlacementsApi";


// ==================================================

// PLACE ACTION CELL

// ==================================================

export function PlaceAction({
  member,

  isPlacing,

  onPlace,
}: {
  member: PendingPlacement;

  isPlacing: boolean;

  onPlace: (baId: string, side: 1 | 2) => void;
}) {
  const [open, setOpen] = useState(false);

  const [menuPosition, setMenuPosition] = useState<{
    top: number;
    left: number;
  } | null>(null);

  const triggerRef = useRef<HTMLButtonElement | null>(null);

  const menuRef = useRef<HTMLDivElement | null>(null);

  useEffect(() => {
    if (!open || isPlacing) {
      setMenuPosition(null);

      return;
    }

    // Keep the menu attached to the Place button even when the table scrolls.

    // Rendering through a portal prevents the table's overflow-x-auto from clipping it.

    const MENU_WIDTH = 144;

    const MENU_HEIGHT = 84;

    const VIEWPORT_GAP = 8;

    const updateMenuPosition = () => {
      const trigger = triggerRef.current;

      if (!trigger) return;

      const rect = trigger.getBoundingClientRect();

      const menuWidth = menuRef.current?.offsetWidth || MENU_WIDTH;

      const menuHeight = menuRef.current?.offsetHeight || MENU_HEIGHT;

      const maxLeft = Math.max(
        VIEWPORT_GAP,
        window.innerWidth - menuWidth - VIEWPORT_GAP,
      );

      const left = Math.max(
        VIEWPORT_GAP,
        Math.min(rect.right - menuWidth, maxLeft),
      );

      const spaceBelow = window.innerHeight - rect.bottom;

      const openAbove =
        spaceBelow < menuHeight + VIEWPORT_GAP &&
        rect.top > menuHeight + VIEWPORT_GAP;

      const preferredTop = openAbove
        ? rect.top - menuHeight - 4
        : rect.bottom + 4;

      const maxTop = Math.max(
        VIEWPORT_GAP,
        window.innerHeight - menuHeight - VIEWPORT_GAP,
      );

      const top = Math.max(VIEWPORT_GAP, Math.min(preferredTop, maxTop));

      setMenuPosition({ top, left });
    };

    updateMenuPosition();

    window.addEventListener("resize", updateMenuPosition);

    // Capture scroll events from the table and other scrollable containers too.

    window.addEventListener("scroll", updateMenuPosition, true);

    return () => {
      window.removeEventListener("resize", updateMenuPosition);

      window.removeEventListener("scroll", updateMenuPosition, true);
    };
  }, [open, isPlacing]);

  const placeMember = (side: 1 | 2) => {
    setOpen(false);

    setMenuPosition(null);

    onPlace(member.ba_id, side);
  };

  return (
    <div className="relative inline-flex">
      <button
        ref={triggerRef}

        type="button"

        onClick={() => setOpen((value) => !value)}

        disabled={isPlacing}

        aria-expanded={open}

        aria-haspopup="menu"

        className="inline-flex items-center gap-1.5 rounded-[8px] border border-[#e5e9ef] bg-white px-2.5 py-1.5 text-[11px] font-bold text-[#3955A6] transition-colors hover:bg-[#f7f8fa] disabled:opacity-50"
      >
        {isPlacing ? (
          <Loader2 size={12} className="animate-spin" />
        ) : (
          <ArrowLeftRight size={12} />
        )}
        Place
        <ChevronDown
          size={12}

          className={
            open ? "rotate-180 transition-transform" : "transition-transform"
          }
        />
      </button>

      {open && !isPlacing && menuPosition && typeof document !== "undefined"
        ? createPortal(
            <>
              {/* Full-screen click-away layer; the menu is stacked above it. */}

              <button
                type="button"

                aria-label="Close placement menu"

                onClick={() => {
                  setOpen(false);

                  setMenuPosition(null);
                }}

                className="fixed inset-0 z-[2147483646] m-0 cursor-default border-0 bg-transparent p-0"
              />

              <div
                ref={menuRef}

                role="menu"

                style={{ top: menuPosition.top, left: menuPosition.left }}

                className="fixed z-[2147483647] w-36 overflow-hidden rounded-[10px] border border-[#e5e9ef] bg-white shadow-[0_8px_24px_-10px_rgba(16,24,40,0.2)]"
              >
                <button
                  type="button"

                  role="menuitem"

                  onClick={() => placeMember(1)}

                  className="flex w-full items-center gap-2 px-3 py-2.5 text-left text-[11px] font-semibold text-[#344054] hover:bg-[#f7f8fa]"
                >
                  <span className="flex h-4 w-4 items-center justify-center rounded-full bg-[#eaf7f0] text-[9px] font-black text-[#18794e]">
                    L
                  </span>
                  Place Left
                </button>

                <button
                  type="button"

                  role="menuitem"

                  onClick={() => placeMember(2)}

                  className="flex w-full items-center gap-2 border-t border-[#f0f2f5] px-3 py-2.5 text-left text-[11px] font-semibold text-[#344054] hover:bg-[#f7f8fa]"
                >
                  <span className="flex h-4 w-4 items-center justify-center rounded-full bg-[#eceffb] text-[9px] font-black text-[#3955A6]">
                    R
                  </span>
                  Place Right
                </button>
              </div>
            </>,

            document.body,
          )
        : null}
    </div>
  );
}

"use client";

import { AlertCircle, CheckCircle2, GitBranch, Inbox, Loader2, RefreshCw, Search, Users, ChevronDown, Network, ShoppingBag, X } from "lucide-react";

import { useMemo, useState } from "react";


import {
  useGetDistributorPendingPlacementsQuery,
  useSetDistributorPlacementMutation,
} from "@/lib/redux/api/distributor/distributorPendingPlacementsApi";


import { BRASS, EMERALD, FontImport, INDIGO, NAVY, PendingPlacementsError, PendingPlacementsLoader, RED, formatNumber } from "@/features/distributor/routes/pending-placements/PendingPlacements.parts/support";
import { StatCard } from "@/features/distributor/routes/pending-placements/PendingPlacements.parts/StatCard";
import { MemberTable } from "@/features/distributor/routes/pending-placements/PendingPlacements.parts/MemberTable";


// ==================================================

// MAIN COMPONENT

// ==================================================

export default function PendingPlacements() {
  const {
    data: response,

    isLoading,

    isFetching,

    isError,

    refetch,
  } = useGetDistributorPendingPlacementsQuery(undefined, {
    refetchOnMountOrArgChange: true,
  });

  const [setPlacement, { isLoading: isPlacingMutation }] =
    useSetDistributorPlacementMutation();

  const [searchQuery, setSearchQuery] = useState("");

  const [orderFilter, setOrderFilter] = useState("all");

  const [deadlineFilter, setDeadlineFilter] = useState("all");

  // track which member is currently being placed (for per-row spinner)

  const [placingBaId, setPlacingBaId] = useState<string | null>(null);

  // Confirm the chosen position before changing the member's placement.
  const [pendingChoice, setPendingChoice] = useState<{
    baId: string;
    side: 1 | 2;
    name: string;
  } | null>(null);

  // toast-like feedback

  const [feedback, setFeedback] = useState<{
    type: "success" | "error";

    message: string;
  } | null>(null);

  const members = response?.data ?? [];

  const filteredMembers = useMemo(() => {
    const query = searchQuery.trim().toLowerCase();

    return members.filter((member) => {
      const searchableValues = [
        member.ba_id,

        member.fullname,

        member.registered_at,

        member.placement_deadline,
      ];

      const matchesSearch =
        !query ||
        searchableValues.some((value) =>
          String(value ?? "")
            .toLowerCase()
            .includes(query),
        );

      const matchesOrder =
        orderFilter === "all" ||
        (orderFilter === "ordered" && member.has_ordered) ||
        (orderFilter === "not_ordered" && !member.has_ordered);

      const matchesDeadline =
        deadlineFilter === "all" ||
        (deadlineFilter === "overdue" && member.is_overdue) ||
        (deadlineFilter === "upcoming" && !member.is_overdue);

      return matchesSearch && matchesOrder && matchesDeadline;
    });
  }, [members, searchQuery, orderFilter, deadlineFilter]);

  const totalPending = response?.total ?? members.length;

  const overdueCount = members.filter((member) => member.is_overdue).length;

  const noOrderCount = members.filter((member) => !member.has_ordered).length;

  const totalUnplacedDownlines = members.reduce(
    (sum, member) => sum + (member.unplaced_downline_count ?? 0),

    0,
  );

  const requestPlacement = (baId: string, side: 1 | 2) => {
    if (isPlacingMutation || placingBaId) return;
    const member = members.find((item) => item.ba_id === baId);
    setPendingChoice({ baId, side, name: member?.fullname || "Member" });
  };

  const handlePlace = async (baId: string, side: 1 | 2) => {
    setPendingChoice(null);
    setPlacingBaId(baId);

    setFeedback(null);

    try {
      const result = await setPlacement({ ba_id: baId, side }).unwrap();

      if (result.success === false) {
        setFeedback({
          type: "error",

          message: result.message || "Failed to set placement.",
        });

        return;
      }

      setFeedback({
        type: "success",

        message:
          result.message ||
          `Member placed successfully on the ${side === 1 ? "left" : "right"} side.`,
      });

      // refetch to reflect updated pending list

      void refetch();
    } catch (err: unknown) {
      const message =
        (err as { data?: { message?: string } })?.data?.message ||
        "Something went wrong while setting placement.";

      setFeedback({ type: "error", message });
    } finally {
      setPlacingBaId(null);
    }
  };

  if (isLoading) return <PendingPlacementsLoader />;

  if (isError || response?.success === false) {
    return <PendingPlacementsError onRetry={() => void refetch()} />;
  }

  const clearFilters = () => {
    setSearchQuery("");

    setOrderFilter("all");

    setDeadlineFilter("all");
  };

  const hasActiveFilters =
    Boolean(searchQuery) || orderFilter !== "all" || deadlineFilter !== "all";

  return (
    <div
      style={{ fontFamily: "'Lato', sans-serif" }}

      className="min-w-0 space-y-5 bg-[#f6f8fc] p-3 sm:p-5 lg:p-6"
    >
      <FontImport />

      {/* =========================================*

          HEADER

*      ========================================= */}

      <header className="relative overflow-hidden rounded-[22px] bg-gradient-to-br from-[#0E1B3D] via-[#172D59] to-[#2958A1] px-5 py-6 text-white shadow-[0_14px_40px_rgba(14,27,61,.15)] sm:px-7 sm:py-7">
        <div
          aria-hidden="true"
          className="pointer-events-none absolute -right-16 -top-28 h-64 w-64 rounded-full border-[34px] border-white/5"
        />
        <div
          aria-hidden="true"
          className="pointer-events-none absolute -bottom-24 right-24 h-44 w-44 rounded-full bg-white/5 blur-2xl"
        />
        <div className="relative flex flex-wrap items-center justify-between gap-4">
          <div className="flex min-w-0 items-start gap-4">
            <span className="flex h-12 w-12 shrink-0 items-center justify-center rounded-2xl border border-white/15 bg-white/10">
              <Network size={24} />
            </span>
            <div className="min-w-0">
              <p className="text-[10px] font-bold uppercase tracking-[.17em] text-blue-100/80">
                Distributor network / Management
              </p>
              <h1 className="mt-1 text-[22px] font-black tracking-tight sm:text-[28px]">
                Pending Placements
              </h1>
              <p className="mt-1 max-w-xl text-[12px] leading-5 text-blue-100/85 sm:text-[13px]">
                Review unplaced members, monitor deadlines and assign a left or
                right position.
              </p>
            </div>
          </div>
          <button
            type="button"
            onClick={() => void refetch()}
            disabled={isFetching || isPlacingMutation}
            className="inline-flex h-10 items-center gap-2 rounded-xl border border-white/20 bg-white/15 px-4 text-[12px] font-bold text-white backdrop-blur-sm transition hover:bg-white/25 disabled:opacity-50"
          >
            <RefreshCw size={15} className={isFetching ? "animate-spin" : ""} />{" "}
            {isFetching ? "Refreshing..." : "Refresh list"}
          </button>
        </div>
        <div className="relative mt-5 flex flex-wrap items-center gap-2 text-[11px] text-blue-100/90">
          <span className="rounded-full border border-white/15 bg-white/10 px-3 py-1.5">
            {totalPending} pending members
          </span>
          {overdueCount > 0 && (
            <span className="rounded-full border border-rose-200/20 bg-rose-300/15 px-3 py-1.5 text-rose-100">
              {overdueCount} overdue
            </span>
          )}
          <span className="rounded-full border border-white/15 bg-white/10 px-3 py-1.5">
            Live data from distributor API
          </span>
        </div>
      </header>

      {/* =========================================*

          FEEDBACK BANNER

*      ========================================= */}

      {feedback && (
        <div
          className={`flex items-start gap-2.5 rounded-[10px] border px-3.5 py-3 text-[12px] font-semibold ${
            feedback.type === "success"
              ? "border-[#bfe8d4] bg-[#eaf7f0] text-[#18794e]"
              : "border-[#f5c6c2] bg-[#fff0ef] text-[#b42318]"
          }`}
        >
          {feedback.type === "success" ? (
            <CheckCircle2 size={16} className="mt-0.5 shrink-0" />
          ) : (
            <AlertCircle size={16} className="mt-0.5 shrink-0" />
          )}

          <p className="flex-1">{feedback.message}</p>

          <button
            type="button"

            onClick={() => setFeedback(null)}

            className="shrink-0 opacity-70 hover:opacity-100"

            aria-label="Dismiss"
          >
            <X size={14} />
          </button>
        </div>
      )}

      {/* =========================================*

          SUMMARY CARDS

*      ========================================= */}

      <div className="grid grid-cols-1 gap-3 sm:grid-cols-2 xl:grid-cols-4">
        <StatCard
          label="Pending placements"

          value={formatNumber(totalPending)}

          icon={<Users size={20} />}

          color={INDIGO}

          background="#eceffb"

          note="Records returned by API"
        />

        <StatCard
          label="No order yet"

          value={formatNumber(noOrderCount)}

          icon={<ShoppingBag size={20} />}

          color={BRASS}

          background="#f8f1e4"

          note="Members without an order"
        />

        <StatCard
          label="Overdue"

          value={formatNumber(overdueCount)}

          icon={<AlertCircle size={20} />}

          color={overdueCount ? RED : EMERALD}

          background={overdueCount ? "#fff0ef" : "#eaf7f0"}

          note="Past placement deadline"
        />

        <StatCard
          label="Unplaced downlines"

          value={formatNumber(totalUnplacedDownlines)}

          icon={<GitBranch size={20} />}

          color={NAVY}

          background="#eceefb"

          note="Sum across displayed members"
        />
      </div>

      {/* =========================================*

          SEARCH & FILTERS

*      ========================================= */}

      <section>
        <div className="flex flex-wrap items-center justify-between gap-3">
          <div>
            <h2 className="text-[14px] font-bold text-[#101828]">
              Pending member list
            </h2>

            <p className="mt-1 text-[11px] text-[#667085]">
              Search by name or distributor ID.
            </p>
          </div>

          <span className="text-[11px] font-semibold text-[#667085]">
            Showing {filteredMembers.length} of {members.length}
          </span>
        </div>

        <div className="mt-4 grid grid-cols-1 gap-3 md:grid-cols-[minmax(220px,1fr)_190px_190px]">
          <div className="relative min-w-0">
            <Search
              size={16}

              className="absolute left-3 top-1/2 -translate-y-1/2 text-[#98a2b3]"
            />

            <input
              type="search"

              value={searchQuery}

              onChange={(event) => setSearchQuery(event.target.value)}

              placeholder="Search member name or ID..."

              className="h-[41px] w-full rounded-[9px] border border-[#e5e9ef] bg-[#f7f8fa] pl-10 pr-4 text-[12px] text-[#101828] outline-none placeholder:text-[#a0a8b6] focus:border-[#0E1B3D] focus:bg-white focus:ring-2 focus:ring-[#0E1B3D]/10"
            />
          </div>

          <div className="relative min-w-0">
            <select
              value={orderFilter}

              onChange={(event) => setOrderFilter(event.target.value)}

              className="h-[41px] w-full appearance-none rounded-[9px] border border-[#e5e9ef] bg-[#f7f8fa] px-3 pr-9 text-[12px] text-[#101828] outline-none focus:border-[#0E1B3D] focus:bg-white focus:ring-2 focus:ring-[#0E1B3D]/10"
            >
              <option value="all">All order statuses</option>

              <option value="ordered">Order placed</option>

              <option value="not_ordered">No order yet</option>
            </select>

            <ChevronDown
              size={15}

              className="pointer-events-none absolute right-3 top-1/2 -translate-y-1/2 text-[#98a2b3]"
            />
          </div>

          <div className="relative min-w-0">
            <select
              value={deadlineFilter}

              onChange={(event) => setDeadlineFilter(event.target.value)}

              className="h-[41px] w-full appearance-none rounded-[9px] border border-[#e5e9ef] bg-[#f7f8fa] px-3 pr-9 text-[12px] text-[#101828] outline-none focus:border-[#0E1B3D] focus:bg-white focus:ring-2 focus:ring-[#0E1B3D]/10"
            >
              <option value="all">All deadlines</option>

              <option value="overdue">Overdue only</option>

              <option value="upcoming">Not overdue</option>
            </select>

            <ChevronDown
              size={15}

              className="pointer-events-none absolute right-3 top-1/2 -translate-y-1/2 text-[#98a2b3]"
            />
          </div>
        </div>

        {hasActiveFilters && (
          <div className="mt-3 flex justify-end">
            <button
              type="button"

              onClick={clearFilters}

              className="text-[12px] font-semibold text-[#3955A6] hover:underline"
            >
              Clear filters
            </button>
          </div>
        )}
      </section>

      {/* =========================================*

          MEMBER TABLE

*      ========================================= */}

      {filteredMembers.length ? (
        <MemberTable
          members={filteredMembers}

          placingBaId={placingBaId}

          onPlace={requestPlacement}
        />
      ) : (
        <div className="flex min-h-[240px] flex-col items-center justify-center gap-3 rounded-[14px] bg-[#f7f8fa] p-6 text-center">
          <div className="flex h-11 w-11 items-center justify-center rounded-full bg-white">
            <Inbox size={22} className="text-[#98a2b3]" />
          </div>

          <p className="text-[13px] font-semibold text-[#344054]">
            {members.length
              ? "No matching members found"
              : "No pending placements found"}
          </p>

          <p className="max-w-md text-[12px] text-[#8a92a6]">
            {members.length
              ? "Try changing the search term or filters."
              : "There are currently no pending placement records in the API response."}
          </p>

          {hasActiveFilters && (
            <button
              type="button"

              onClick={clearFilters}

              className="text-[12px] font-semibold text-[#3955A6] hover:underline"
            >
              Clear filters
            </button>
          )}
        </div>
      )}

      {/* =========================================*

          FOOTER

*      ========================================= */}

      <div className="flex flex-wrap items-center justify-between gap-3 border-t border-[#f0f2f5] pt-4">
        <p className="text-[11px] text-[#8a92a6]">
          Pending placements data is loaded from the distributor genealogy API.
          {isPlacingMutation && " · Setting placement..."}
        </p>

        <button
          type="button"

          onClick={() => void refetch()}

          disabled={isFetching || isPlacingMutation}

          className="flex items-center gap-2 text-[12px] font-semibold text-[#3955A6] hover:underline disabled:opacity-50"
        >
          <RefreshCw size={13} className={isFetching ? "animate-spin" : ""} />
          Update placements
        </button>
      </div>

      {pendingChoice && (
        <div
          className="fixed inset-0 z-[2147483600] flex items-center justify-center bg-[#101828]/60 p-4 backdrop-blur-[3px]"
          role="presentation"
          onMouseDown={(event) => {
            if (event.target === event.currentTarget && !isPlacingMutation)
              setPendingChoice(null);
          }}
        >
          <div
            role="dialog"
            aria-modal="true"
            aria-labelledby="confirm-placement-title"
            className="w-full max-w-md overflow-hidden rounded-[20px] bg-white shadow-[0_30px_90px_rgba(0,0,0,.25)]"
          >
            <div className="border-b border-[#edf0f5] px-5 py-4 sm:px-6">
              <div className="flex items-start justify-between gap-3">
                <span className="flex h-11 w-11 items-center justify-center rounded-[13px] bg-[#edf2ff] text-[#3955A6]">
                  <GitBranch size={21} />
                </span>
                <button
                  type="button"
                  aria-label="Cancel placement"
                  disabled={isPlacingMutation}
                  onClick={() => setPendingChoice(null)}
                  className="rounded-lg p-2 text-[#6b7586] hover:bg-[#f4f6fa]"
                >
                  <X size={17} />
                </button>
              </div>
              <h2
                id="confirm-placement-title"
                className="mt-3 text-[18px] font-extrabold text-[#101828]"
              >
                Confirm member placement
              </h2>
              <p className="mt-1 text-[12px] leading-5 text-[#667085]">
                Please review the position before submitting this placement to
                the API.
              </p>
            </div>
            <div className="space-y-3 px-5 py-5 sm:px-6">
              <div className="rounded-xl bg-[#f7f9fd] p-4 text-[12px]">
                <p className="font-bold text-[#101828]">{pendingChoice.name}</p>
                <p className="mt-1 break-all text-[#667085]">
                  BA ID: {pendingChoice.baId}
                </p>
                <p className="mt-3 text-[#667085]">
                  Selected position:{" "}
                  <strong
                    className={
                      pendingChoice.side === 1
                        ? "text-[#1f9d6b]"
                        : "text-[#3955A6]"
                    }
                  >
                    {pendingChoice.side === 1 ? "Left leg" : "Right leg"}
                  </strong>
                </p>
              </div>
              <p className="text-[11px] leading-5 text-[#8a94a5]">
                Placement availability and rules are validated by your backend.
                A successful response will refresh the pending list.
              </p>
              <div className="flex gap-2 pt-1">
                <button
                  type="button"
                  disabled={isPlacingMutation}
                  onClick={() => setPendingChoice(null)}
                  className="h-10 flex-1 rounded-xl border border-[#e0e6ef] bg-white text-[12px] font-bold text-[#475467] hover:bg-[#f7f9fc]"
                >
                  Cancel
                </button>
                <button
                  type="button"
                  disabled={isPlacingMutation}
                  onClick={() =>
                    void handlePlace(pendingChoice.baId, pendingChoice.side)
                  }
                  className="flex h-10 flex-1 items-center justify-center gap-2 rounded-xl bg-[#0E1B3D] text-[12px] font-bold text-white hover:bg-[#223a69] disabled:opacity-50"
                >
                  {isPlacingMutation ? (
                    <Loader2 className="animate-spin" size={15} />
                  ) : (
                    <CheckCircle2 size={15} />
                  )}{" "}
                  Confirm placement
                </button>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

"use client";

import { useCallback, useEffect, useState } from "react";

import { CreditCard, Download, Loader2, Printer, RefreshCw, ShieldCheck, X } from "lucide-react";


import Logo from "../../../../../public/indiekonnect-web/images/logo.png";
import { Address, FONT_FAMILY, MM_H, MM_W, OrderResponse, PHOTO, PX_H, PX_W, Quote, User, api, drawCard, emptyAddress, getProfilePhotoUrl, img, loadPhotoForCanvas, loadPoppins, loadRazorpay } from "@/features/distributor/routes/profile/DistributorPVCSection.parts/support";


declare global {
  interface Window {
    Razorpay?: new (options: Record<string, unknown>) => { open(): void };
  }
}

export default function DistributorPVCSection({ user }: { user: User }) {
  const profilePhotoUrl = getProfilePhotoUrl(user);

  const [front, setFront] = useState("");

  const [back, setBack] = useState("");

  const [photoExportError, setPhotoExportError] = useState("");

  const [busy, setBusy] = useState<
    "render" | "download" | "print" | "quote" | "pay" | null
  >("render");

  const [modal, setModal] = useState(false);

  const [quote, setQuote] = useState<Quote | null>(null);

  const [address, setAddress] = useState<Address>(emptyAddress);

  const [error, setError] = useState("");

  const [message, setMessage] = useState("");

  useEffect(() => {
    void loadPoppins();
  }, []);

  const render = useCallback(async () => {
    setBusy("render");

    setError("");

    setPhotoExportError("");

    try {
      const [localLogo, photoResult] = await Promise.all([
        img(Logo.src, false).catch(() => null),

        profilePhotoUrl
          ? Promise.resolve()

              .then(() => loadPhotoForCanvas(profilePhotoUrl))

              .then((image) => ({ image, problem: "" }))

              .catch((cause) => ({
                image: null,

                problem:
                  cause instanceof Error
                    ? cause.message
                    : "Profile photo could not be loaded",
              }))
          : Promise.resolve({ image: null, problem: "" }),

        loadPoppins(),
      ]).then(([logoImage, photo]) => [logoImage, photo] as const);

      if (profilePhotoUrl && !photoResult.image) {
        setPhotoExportError(
          `Profile photo could not be embedded in the card (${photoResult.problem}). Check the image URL and image-proxy server route.`,
        );
      }

      const [frontImg, backImg] = await Promise.all([
        drawCard(user, "front", photoResult.image, localLogo),

        drawCard(user, "back", photoResult.image, localLogo),
      ]);

      setFront(frontImg);

      setBack(backImg);
    } catch (err) {
      setError(err instanceof Error ? err.message : "Card preview failed");
    } finally {
      setBusy(null);
    }
  }, [
    profilePhotoUrl,

    user.full_name,

    user.distributor_id,

    user.profile_picture,

    user.profile_image,

    user.avatar,

    user.account_type,

    user.distributor_status,

    user.is_active,

    user.phone,

    user.email,

    user.created_at,

    user.joining_date,

    user.state,

    user.country,

    user.distributor_profile,
  ]);

  useEffect(() => {
    void render();
  }, [render]);

  // ======================================================// DOWNLOAD PDF// ======================================================

  const download = async () => {
    if (!front || !back) return;

    if (photoExportError) {
      setError(photoExportError);

      return;
    }

    setBusy("download");

    setError("");

    try {
      const { jsPDF } = await import("jspdf");
      const pdf = new jsPDF({
        orientation: "portrait",

        unit: "mm",

        format: [MM_W, MM_H],

        compress: true,
      });

      pdf.addImage(front, "PNG", 0, 0, MM_W, MM_H);

      pdf.addPage([MM_W, MM_H], "portrait");

      pdf.addImage(back, "PNG", 0, 0, MM_W, MM_H);

      pdf.save(
        `Indiekonnect-${(user.distributor_id || "card").replace(
          /[^\w-]/g,

          "",
        )}.pdf`,
      );
    } catch (err) {
      setError(err instanceof Error ? err.message : "PDF download failed");
    } finally {
      setBusy(null);
    }
  };

  // ======================================================// PRINT CARD// ======================================================

  const print = () => {
    if (!front || !back) return;

    if (photoExportError) {
      setError(photoExportError);

      return;
    }

    const popup = window.open("", "_blank");

    if (!popup) {
      setError("Allow pop-ups to print the card");

      return;
    }

    setBusy("print");

    setError("");

    try {
      popup.document.open();

      popup.document.write(`<!doctype html>

<html>

<head>

<meta charset="utf-8" />

<title>Print Indiekonnect ID</title>

<style>

@page{size:A4 portrait;margin:15mm}

*{box-sizing:border-box}

body{font:13px Arial,sans-serif;padding:0;margin:0}

.card-wrap{

  position:relative;

  width:54mm;

  height:85.6mm;

  margin:0 0 12mm 0;

  print-color-adjust:exact;

  -webkit-print-color-adjust:exact

}

.card{

  position:absolute;

  inset:0;

  width:100%;

  height:100%;

  display:block

}

.note{margin:0 0 8mm 0;padding:0}

@media print{.note{display:none}}

</style>

</head>

<body>

<p class="note">Print at 100% / Actual Size. Front and back are separate; align carefully for duplex printing.</p>

<div class="card-wrap">

  <img class="card" src="${front}" alt="Front card" />

</div>

<div class="card-wrap">

  <img class="card" src="${back}" alt="Back card" />

</div>

<script>

window.addEventListener('load', function(){

  setTimeout(function(){ window.print(); }, 300);

});

<\/script>

</body>

</html>`);

      popup.document.close();
    } catch (err) {
      popup.close();

      setError(err instanceof Error ? err.message : "Print failed");
    } finally {
      setBusy(null);
    }
  };

  // ======================================================// REQUEST PVC CARD DELIVERY// ======================================================

  const startRequest = async () => {
    setBusy("quote");

    setError("");

    setMessage("");

    try {
      const q = await api<Quote>("/quote");

      if (
        !q.quote_id ||
        !Number.isSafeInteger(q.amount_paise) ||
        q.amount_paise <= 0 ||
        q.currency !== "INR"
      ) {
        throw new Error("Invalid price quote");
      }

      setQuote(q);

      setAddress((prev) => ({
        ...prev,

        full_name: prev.full_name || user.full_name || "",
      }));

      setModal(true);
    } catch (err) {
      setError(err instanceof Error ? err.message : "Price unavailable");
    } finally {
      setBusy(null);
    }
  };

  const pay = async () => {
    if (!quote || busy) return;

    if (
      !address.full_name.trim() ||
      !/^\d{10}$/.test(address.phone) ||
      !address.address_line1.trim() ||
      !address.city.trim() ||
      !address.state.trim() ||
      !/^\d{6}$/.test(address.pincode)
    ) {
      setError(
        "Enter recipient name, 10-digit mobile, complete address, and 6-digit PIN.",
      );

      return;
    }

    setBusy("pay");

    setError("");

    try {
      const order = await api<OrderResponse>("/requests", {
        method: "POST",

        headers: {
          "Idempotency-Key": quote.quote_id,
        },

        body: JSON.stringify({
          quote_id: quote.quote_id,

          delivery_address: address,
        }),
      });

      if (
        !order.razorpay_order_id ||
        !order.razorpay_key ||
        order.amount_paise !== quote.amount_paise
      ) {
        throw new Error("Payment order mismatch");
      }

      await loadRazorpay();

      if (!window.Razorpay) {
        throw new Error("Razorpay unavailable");
      }

      new window.Razorpay({
        key: order.razorpay_key,

        amount: order.amount_paise,

        currency: "INR",

        order_id: order.razorpay_order_id,

        name: "Indiekonnect",

        description: "Distributor PVC card home delivery",

        prefill: {
          name: address.full_name,

          contact: address.phone,
        },

        theme: {
          color: "#087F86",
        },

        handler: async (response: unknown) => {
          try {
            await api(
              `/requests/${encodeURIComponent(order.request_id)}/verify`,

              {
                method: "POST",

                body: JSON.stringify(response),
              },
            );

            setModal(false);

            setMessage(
              "Payment verified. Your card request has been submitted.",
            );
          } catch {
            setError(
              "Payment received but verification is pending. Check your request status before paying again.",
            );
          }
        },

        modal: {
          ondismiss: () => {
            setMessage(
              "Payment window closed. Request remains unconfirmed until payment is verified.",
            );
          },
        },
      }).open();
    } catch (err) {
      setError(err instanceof Error ? err.message : "Unable to start payment");
    } finally {
      setBusy(null);
    }
  };

  const fields: {
    key: keyof Address;

    label: string;

    placeholder: string;
  }[] = [
    {
      key: "full_name",

      label: "Recipient name",

      placeholder: "Full name",
    },

    {
      key: "phone",

      label: "Mobile number",

      placeholder: "10-digit mobile",
    },

    {
      key: "address_line1",

      label: "Address line 1",

      placeholder: "House / flat, building, street",
    },

    {
      key: "address_line2",

      label: "Address line 2",

      placeholder: "Area / landmark (optional)",
    },

    {
      key: "city",

      label: "City",

      placeholder: "City",
    },

    {
      key: "state",

      label: "State",

      placeholder: "State",
    },

    {
      key: "pincode",

      label: "PIN code",

      placeholder: "6-digit PIN",
    },
  ];

  return (
    <section
      style={{ fontFamily: FONT_FAMILY }}

      className="w-full min-w-0 rounded-2xl border border-gray-200 bg-white p-4 font-medium text-black shadow-sm sm:p-6"
    >
      {/* Section header */}

      <div className="mb-5 flex flex-wrap items-center justify-between gap-3">
        <div className="flex items-center gap-3">
          <span className="rounded-xl bg-gray-100 p-2.5 text-black">
            <CreditCard size={22} />
          </span>

          <div>
            <h2 className="break-words text-[14px] font-semibold text-[#101828]">
              My Indiekonnect Distributor ID
            </h2>

            <p className=" break-words text-[11px] leading-4 text-[#98a2b3] sm:text-[11.5px]">
              Vertical PVC card • front and back • 54 × 85.6 mm
            </p>
          </div>
        </div>

        <button
          type="button"

          onClick={() => void render()}

          disabled={!!busy}

          className="flex items-center gap-1.5 rounded-lg border border-gray-200 bg-gray-50 px-3 py-2 text-xs font-semibold text-black transition-colors hover:bg-gray-100 disabled:opacity-50"
        >
          <RefreshCw size={14} />
          Refresh Card
        </button>
      </div>

      {/* Front and back preview */}

      <div className="grid grid-cols-2 gap-2 sm:gap-4 xl:gap-5">
        {(
          [
            { label: "FRONT", src: front },

            { label: "BACK", src: back },
          ] as const
        ).map((card) => (
          <div
            key={card.label}

            className="min-w-0 rounded-2xl border border-gray-200 bg-gray-50 p-3 sm:p-5"
          >
            <div className="mb-3 flex items-center justify-between">
              <span className="text-xs font-semibold tracking-widest text-black">
                {card.label}
              </span>

              <span className="text-[11px] font-medium text-gray-500">
                Portrait
              </span>
            </div>

            <div className="relative mx-auto w-full max-w-[340px] aspect-[54/85.6] overflow-hidden rounded-[4%] border border-gray-200 bg-white shadow-[0_16px_32px_rgba(0,0,0,.1)]">
              {card.src ? (
                <img
                  src={card.src}

                  alt={`${card.label} of personalized distributor card`}

                  className="absolute inset-0 h-full w-full object-fill"
                />
              ) : (
                <div className="absolute inset-0 flex items-center justify-center text-sm font-medium text-gray-500">
                  <Loader2
                    size={18}

                    className="mr-2 animate-spin"
                  />
                  Preparing card…
                </div>
              )}

              {/* Always show the original photo in preview when PDF embedding fails. */}

              {card.label === "FRONT" &&
                profilePhotoUrl &&
                photoExportError && (
                  <img
                    src={profilePhotoUrl}

                    alt="Distributor profile photo"

                    loading="eager"

                    className="absolute object-cover"

                    style={{
                      left: `${(PHOTO.x / PX_W) * 100}%`,

                      top: `${(PHOTO.y / PX_H) * 100}%`,

                      width: `${(PHOTO.w / PX_W) * 100}%`,

                      height: `${(PHOTO.h / PX_H) * 100}%`,

                      borderRadius: "13%",
                    }}
                  />
                )}
            </div>
          </div>
        ))}
      </div>

      {/* Action buttons */}

      <div className="mt-5 flex flex-wrap gap-3">
        <button
          type="button"

          disabled={!!busy || !front || !back || !!photoExportError}

          onClick={download}

          className="inline-flex items-center gap-2 rounded-xl bg-[#087F86] px-5 py-3 text-xs font-semibold text-white shadow-sm transition-colors hover:bg-[#066C72] disabled:opacity-50"
        >
          <Download size={16} />
          Download Print PDF
        </button>

        <button
          type="button"

          disabled={!!busy || !front || !back || !!photoExportError}

          onClick={print}

          className="inline-flex items-center gap-2 rounded-xl border border-gray-200 bg-white px-5 py-3 text-xs font-semibold text-black transition-colors hover:bg-gray-50 disabled:opacity-50"
        >
          <Printer size={16} />
          Print Card
        </button>
      </div>

      <p className="mt-4 flex gap-2 text-xs font-medium leading-5 text-gray-500">
        <ShieldCheck size={15} className="mt-0.5 shrink-0" />
        This is an Indiekonnect company-issued ID, not government
        identification. Delivery is available only after server-confirmed
        payment.
      </p>

      {!profilePhotoUrl && (
        <p
          role="alert"

          className="mt-3 rounded-lg border border-amber-200 bg-amber-50 p-3 text-xs text-amber-900"
        >
          Profile image URL missing in distributor user data. Check
          profile_picture, profile_image, avatar, and distributor_profile fields
          returned by the backend.
        </p>
      )}

      {photoExportError && (
        <p
          role="alert"

          className="mt-3 rounded-lg border border-amber-200 bg-amber-50 p-3 text-xs text-amber-900"
        >
          Profile photo could not be embedded in the PDF: {photoExportError}. If
          the preview photo is also missing, verify the image URL is publicly
          accessible to the signed-in browser. Check that the same-origin image
          proxy route exists and returns image bytes. PDF is disabled until
          embedding succeeds.
        </p>
      )}

      {message && (
        <p
          role="status"

          className="mt-2 text-xs font-medium text-emerald-700"
        >
          {message}
        </p>
      )}

      {!modal && error && (
        <p
          role="alert"

          className="mt-2 text-xs font-medium text-red-600"
        >
          {error}
        </p>
      )}

      {/* PVC delivery modal */}

      {modal && quote && (
        <div
          role="dialog"

          aria-modal="true"

          aria-label="Request card delivery"

          style={{ fontFamily: FONT_FAMILY }}

          className="fixed inset-0 z-[9999] flex items-center justify-center bg-[#087F86]/40 p-4"
        >
          <div className="max-h-[90dvh] w-full max-w-lg overflow-y-auto rounded-2xl border border-gray-200 bg-white p-5 shadow-2xl">
            <div className="flex items-center justify-between">
              <h3 className="text-lg font-semibold text-black">
                Print and deliver my PVC card
              </h3>

              <button
                type="button"

                onClick={() => setModal(false)}

                aria-label="Close"

                className="rounded-lg p-2 text-black transition-colors hover:bg-gray-100"
              >
                <X size={19} />
              </button>
            </div>

            <div className="mt-4 rounded-xl border border-gray-200 bg-gray-50 p-4">
              <div className="text-xs font-medium text-gray-500">
                Total price including delivery
              </div>

              <div className="mt-1 text-2xl font-semibold text-black">
                ₹{(quote.amount_paise / 100).toFixed(2)}
              </div>

              <div className="text-xs font-medium text-gray-500">
                {quote.description || "PVC card printing + home delivery"}
              </div>
            </div>

            <div className="mt-4 grid grid-cols-1 gap-3 sm:grid-cols-2">
              {fields.map((field) => (
                <label
                  key={field.key}

                  className={
                    field.key.startsWith("address_line") ? "sm:col-span-2" : ""
                  }
                >
                  <span className="mb-1 block text-xs font-semibold text-black">
                    {field.label}
                  </span>

                  <input
                    className="h-10 w-full rounded-lg border border-gray-300 bg-white px-3 text-sm font-medium text-black outline-none transition-colors placeholder:text-gray-400 focus:border-black focus:ring-1 focus:ring-black"

                    value={address[field.key]}

                    placeholder={field.placeholder}

                    onChange={(e) =>
                      setAddress((prev) => ({
                        ...prev,

                        [field.key]:
                          field.key === "phone" || field.key === "pincode"
                            ? e.target.value

                                .replace(/\D/g, "")

                                .slice(
                                  0,

                                  field.key === "phone" ? 10 : 6,
                                )
                            : e.target.value,
                      }))
                    }
                  />
                </label>
              ))}
            </div>

            {error && (
              <p
                role="alert"

                className="mt-3 text-xs font-medium text-red-600"
              >
                {error}
              </p>
            )}

            <button
              type="button"

              disabled={!!busy}

              onClick={pay}

              className="mt-5 flex w-full items-center justify-center gap-2 rounded-xl bg-[#087F86] px-4 py-3 text-sm font-semibold text-white shadow-sm transition-colors hover:bg-[#066C72] disabled:opacity-50"
            >
              {busy === "pay" && <Loader2 className="animate-spin" size={16} />}
              Pay ₹{(quote.amount_paise / 100).toFixed(2)} & Request Card
            </button>

            <p className="mt-3 text-[11px] font-medium leading-5 text-gray-500">
              Order confirmation requires backend payment verification. Do not
              retry while verification is pending.
            </p>
          </div>
        </div>
      )}
    </section>
  );
}

