"use client";

import { useEffect, useMemo, useState } from "react";
import {
  useGetMyAccountsQuery,
  useGetUserDashboardQuery,
} from "@/lib/redux/api/distributor/userDashboardApi";
import { useLazyGetTrackingCvCounterQuery } from "@/lib/redux/api/distributor/trackingCvCounterApi";
import Sidebar from "@/features/distributor/shell/Sidebar";
import DashboardHeader from "@/features/distributor/shell/DashboardHeader";
import { Activity, ArrowRight, CircleDollarSign, Coins, GitBranch, HandCoins, Link2, Loader2, Network, Search, ShoppingBag, TrendingUp, AlertCircle, BarChart3, RefreshCw } from "lucide-react";
import { Metric, MetricCard, SelectField, ValueCell, asArray, asObject, blackButton, card, dateShort, extractAccountRows, extractCalendar, extractCvPayload, extractIgnite, fmt, fmtCount, heading, numeric, pickValue, sub } from "@/features/distributor/routes/profile/ba-board/page.parts/support";

export type TrackingAccount = { id: string; label?: string; baId?: string };
export type TrackingWeek = {
  weekNo: number;
  year: number;
  start: string;
  end: string;
  label?: string;
};
export type TrackingSummary = {
  retailProfit?: Metric;
  floatingRetailProfit?: Metric;
  totalPairedCv?: Metric;
  pairingCommission?: Metric;
  unilevelCommission?: Metric;
  greenCoinEarned?: Metric;
  yellowCoinEarned?: Metric;
  blueCoinEarned?: Metric;
};
export type TrackingCv = {
  accountId?: string;
  baId?: string;
  leftCv?: Metric;
  rightCv?: Metric;
  carryForwardLeft?: Metric;
  carryForwardRight?: Metric;
  pairedCv?: Metric;
  pairingCommission?: Metric;
  greenCoins?: Metric;
  yellowCoins?: Metric;
  blueCoins?: Metric;
  floatingCvLeft?: Metric;
  floatingCvRight?: Metric;
  totalCvLeft?: Metric;
  totalCvRight?: Metric;
  rankNo?: Metric;
  totalSteps?: Metric;
  isSettled?: boolean;
  weekYear?: number;
  weekNo?: number;
  hasWeekResult?: boolean;
};
export type TrackingCommission = {
  pairingCommission?: Metric;
  retailProfit?: Metric;
  unilevelCommission?: Metric;
};
export type TrackingTree = {
  totalDirects?: Metric;
  totalDownline?: Metric;
};
export type TrackingTrendPoint = {
  label: string;
  value: number; // cash credits in USD, sourced from cash_bal history
  outflow?: number; // absolute cash debits in USD
  isCurrent?: boolean;
};
export type HistoryEntry = {
  id?: number | string;
  category?: string;
  tx_type?: string;
  description?: string;
  amount?: number | string;
  date_created?: string;
};

/** Optional pre-computed counts for the Commission History breakdown.
 *  When provided, these override the counts derived from `history`. */
export type CommissionHistoryCounts = {
  cash_count?: number;
  yellow_count?: number;
  green_count?: number;
  blue_count?: number;
  other_count?: number;
};

export interface TrackingCenterPremiumProps {
  summary?: TrackingSummary | null;
  accounts?: TrackingAccount[];
  weeks?: TrackingWeek[];
  years?: number[];
  cv?: TrackingCv | null;
  commission?: TrackingCommission | null;
  commissionHistory?: HistoryEntry[];
  commissionCounts?: CommissionHistoryCounts | null;
  trend?: TrackingTrendPoint[];
  tree?: TrackingTree | null;
  initialAccountId?: string;
  initialWeekNo?: number;
  initialYear?: number;
  isLoading?: boolean;
  isFetching?: boolean;
  error?: string | null;
  onShowCv?: (selection: {
    accountId: string;
    weekNo: number;
    year: number;
  }) => Promise<void> | void;
  onRefresh?: () => Promise<void> | void;
  onViewGenealogy?: () => void;
}

function CvOverview({
  cv,
  isFetching,
}: {
  cv?: TrackingCv | null;
  isFetching?: boolean;
}) {
  return (
    <section className={`${card} p-4 sm:p-5`}>
      <div className="flex flex-wrap items-start justify-between gap-2">
        <div>
          <h3 className={heading}>{cv?.accountId || "CV Overview"}</h3>
          <p className={`mt-1 ${sub}`}>
            Selected account’s sales week performance
          </p>
        </div>
        <div className="flex flex-wrap items-center gap-2">
          {cv?.weekNo != null && (
            <span className="rounded-[7px] border border-[#E8EAED] bg-[#F6F7F9] px-2.5 py-1.5 text-[10px] font-semibold text-[#5F6773]">
              Week {cv.weekNo} · {cv.weekYear}
            </span>
          )}
          {cv?.isSettled !== undefined && (
            <span
              className={`rounded-[7px] border px-2.5 py-1.5 text-[10px] font-semibold ${cv.isSettled ? "border-[#D7EADB] bg-[#F1F9F3] text-[#277A51]" : "border-[#F0E1C1] bg-[#FFF9EB] text-[#956B25]"}`}
            >
              {cv.isSettled ? "Settled" : "Not settled"}
            </span>
          )}
          {cv?.baId && (
            <span className="max-w-full break-all rounded-[7px] border border-[#E8EAED] bg-[#F6F7F9] px-2.5 py-1.5 text-[10px] font-semibold text-[#5F6773]">
              {cv.baId}
            </span>
          )}
        </div>
      </div>
      {cv ? (
        <>
