          >
            <List size={15} />
            Table view
          </button>
        </div>
        <div className="flex flex-wrap items-center gap-3">
          {view === "table" && (
            <button
              type="button"
              onClick={() => setIsRankTableOpen((open) => !open)}
              aria-expanded={isRankTableOpen}
              aria-controls="rank-requirements-table-panel"
              title={
