export type DropdownOption<T extends string | number> = {
  value: T;

  label: string;

  description?: string;
};


export type SearchableDropdownProps<T extends string | number> = {
  id: string;

  label: string;

  options: DropdownOption<T>[];

  value: T;

  onChange: (value: T) => void;

  searchPlaceholder: string;

  emptyMessage: string;

  disabled?: boolean;

  featuredOption?: DropdownOption<T>;

  featuredLabel?: string;
};


export type PairingsResponse = {
  data?: unknown;
  isFetching: boolean;
  isLoading: boolean;
  isError: boolean;
  error?: unknown;
  refetch: () => unknown;
};


export type MetricRow = { name: string; value: string | number };


export function extractPairingRows(value: unknown): MetricRow[] {
  if (!value || typeof value !== "object") return [];

  const root = value as Record<string, unknown>;

  const payload =
    root.data && typeof root.data === "object"
      ? (root.data as Record<string, unknown>)
      : root;

  const candidates = [
    payload.ignite,
    payload.cv_counter,
    payload.cv_summary,
    payload.summary,
    payload.stats,
    payload,
  ];

  const keys = [
    "cv_left",
    "cv_right",
    "total_cv_left",
    "total_cv_right",
    "floating_cv_left",
    "floating_cv_right",
    "total_steps",
    "paired_cv",
    "pairing_commission",
    "weekly_pairing_usd",
    "rank_no",
  ];

  const rows: MetricRow[] = [];

  for (const candidate of candidates) {
    if (!candidate || typeof candidate !== "object" || Array.isArray(candidate))
      continue;

    const data = candidate as Record<string, unknown>;

    for (const key of keys) {
      const val = data[key];

      if (
        (typeof val === "string" || typeof val === "number") &&
        !rows.some((row) => row.name === key)
      ) {
        rows.push({ name: key, value: val });
      }
    }
  }

  return rows;
}


export function getErrorText(error: unknown) {
  if (!error || typeof error !== "object")
    return "Unable to load CV data. Please try again.";

  const e = error as { data?: { message?: string }; message?: string };

  return (
    e.data?.message || e.message || "Unable to load CV data. Please try again."
  );
}

