"use client";

import { useEffect, useMemo, useRef, useState } from "react";
import {
  motion,
  useInView,
  useReducedMotion,
} from "framer-motion";

import { Accent, Display, Lede, Section, Wrap, cx } from "@/features/landing/components/design-system/index";

import { ease } from "@/features/landing/components/design-system/index";
import styles from "@/features/landing/components/components/sections/Ladder.module.css";

import { useGetLandingPageQuery } from "@/lib/redux/api/Landing/landingPageApi";

/* =========================================================
   MOBILE DETECTION
========================================================= */

function useIsMobile() {
  const [isMobile, setIsMobile] =
    useState(false);

  useEffect(() => {
    const checkMobile = () => {
      setIsMobile(
        window.innerWidth < 768
      );
    };

    checkMobile();

    window.addEventListener(
      "resize",
      checkMobile
    );

    return () => {
      window.removeEventListener(
        "resize",
        checkMobile
      );
    };
  }, []);

  return isMobile;
}

/* =========================================================
   STEP TYPE
========================================================= */

type LadderStep = {
  id: number | string;
  mark: string;
  level: string;
  title: string;
  body: string;
};

/* =========================================================
   CHAPTER SIX
========================================================= */

export function Ladder() {
  const [current, setCurrent] =
    useState(0);

  const isMobile = useIsMobile();

  /* =========================================================
     API
  ========================================================= */

  const { data: landingData } =
    useGetLandingPageQuery();

  /* =========================================================
     FIND CHAPTER SIX BY SLUG
  ========================================================== */

  const chapterSixPage =
    landingData?.data?.find(
      (item: any) =>
        item?.slug === "chapter-six"
    );

  /* =========================================================
     GET CHAPTER BLOCKS
  ========================================================== */

  const chapterSixBlocks =
    useMemo(() => {
      const blocks =
        chapterSixPage?.blocks || [];

      const main =
        blocks.find(
          (block: any) =>
            block?.sort_order === 0
        ) || null;

      const stepBlocks =
        blocks
          .filter(
            (block: any) =>
              block?.sort_order > 0
          )
          .sort(
            (a: any, b: any) =>
              (a?.sort_order ?? 0) -
              (b?.sort_order ?? 0)
          );

      return {
        main,
        stepBlocks,
      };
    }, [chapterSixPage]);

  /* =========================================================
     MAIN CONTENT
  ========================================================== */

  const chapterHeading =
    chapterSixBlocks.main?.heading?.trim() ||
    "Chapter Six · The Opportunity";

  const chapterShortDescription =
    chapterSixBlocks.main?.short_description?.trim() ||
    "A growth ladder\nfor leaders";

  const chapterDescription =
    chapterSixBlocks.main?.description?.trim() ||
    "A clear, milestone-driven journey built on leadership development, mentorship and shared success. Every rung is earned, and every rung is published.";

  /* =========================================================
     DYNAMIC LADDER STEPS
  ========================================================== */

  const steps = useMemo<LadderStep[]>(
    () => {
      return chapterSixBlocks.stepBlocks.map(
        (block: any, index: number) => ({
          id:
            block?.id ??
            block?.sort_order ??
            index + 1,

          mark: String(
            block?.sort_order ??
              index + 1
          ).padStart(2, "0"),

          level:
            block?.heading?.trim() ||
            `Level ${String(
              index + 1
            ).padStart(2, "0")}`,

          title:
            block?.short_description?.trim() ||
            `Level ${index + 1}`,

          body:
            block?.description?.trim() ||
            "",
        })
      );
    },
    [chapterSixBlocks]
  );

  /* =========================================================
     KEEP CURRENT INDEX VALID
  ========================================================== */

  useEffect(() => {
    if (!steps.length) {
      setCurrent(0);
      return;
    }

    setCurrent((prev) =>
      Math.min(
        prev,
        steps.length - 1
      )
    );
  }, [steps.length]);

  /* =========================================================
     MAIN SHORT DESCRIPTION

     API:
     "A growth ladder\r\nfor leaders"

     Render as:
     A growth ladder
     for leaders
  ========================================================== */

  const shortDescriptionLines =
    chapterShortDescription.split(
      /\r?\n/
    );

  return (
    <Section
      id="ladder"
      label="The growth ladder"
      className={styles.ladder}
    >
      <Wrap className={styles.in}>
        {/* =====================================================
            LEFT / STICKY CONTENT
        ====================================================== */}

        <div className={styles.sticky}>
          {/* Dynamic Chapter Heading */}
          {/* <Eyebrow>
            {chapterHeading}
          </Eyebrow> */}

          {/* Dynamic Main Heading */}
          <Display
            size="lg"
            style={{
              marginTop: 20,
            }}
          >
            {shortDescriptionLines.map(
              (
                line: string,
                index: number
              ) => {
                const isLast =
                  index ===
                  shortDescriptionLines.length -
                    1;

                /*
                 * Last word of last line
                 * is highlighted.
                 */
                if (isLast) {
                  const words =
                    line
                      .split(
                        /\s+/
                      )
                      .filter(
                        Boolean
                      );

                  if (
                    words.length >
                    1
                  ) {
                    return (
                      <span
                        key={`${line}-${index}`}
                      >
                        {words
                          .slice(
                            0,
                            -1
                          )
                          .join(
                            " "
                          )}{" "}
                        <Accent>
                          {
                            words[
                              words.length -
                                1
                            ]
                          }
                        </Accent>
                      </span>
                    );
                  }
                }

                return (
                  <span
                    key={`${line}-${index}`}
                  >
                    {line}
                  </span>
                );
              }
            )}
          </Display>

          {/* Dynamic Description */}
          <Lede
            style={{
              marginTop: 20,
            }}
          >
            {chapterDescription}
          </Lede>

          {/* =================================================
              DESKTOP METER
          ================================================= */}

          {!isMobile &&
            steps.length > 0 && (
              <div
                className={
                  styles.meter
                }
                aria-hidden="true"
              >
                <span
                  className={
                    styles.num
                  }
                >
                  {String(
                    current + 1
                  ).padStart(2, "0")}
                </span>

                <span
                  className={
                    styles.track
                  }
                >
                  <i
                    className={
                      styles.fill
                    }
                    style={{
                      width:
                        `${
                          ((current +
                            1) /
                            steps.length) *
                          100
                        }%`,
                    }}
                  />
                </span>

                <span
                  className={
                    styles.num
                  }
                  style={{
                    opacity: 0.4,
                  }}
                >
                  {String(
                    steps.length
                  ).padStart(
                    2,
                    "0"
                  )}
                </span>
              </div>
            )}
        </div>

        {/* =====================================================
            STEPS
        ====================================================== */}

        <div
          className={cx(
            styles.steps,
            isMobile &&
              styles.stepsMobile
          )}
        >
          {steps.map(
            (
              step,
              index
            ) => (
              <Step
                key={step.id}
                step={step}
                index={index}
                onActive={
                  setCurrent
                }
                isMobile={
                  isMobile
                }
              />
            )
          )}
        </div>
      </Wrap>
    </Section>
  );
}

/* =========================================================
   STEP COMPONENT
========================================================= */

function Step({
  step,
  index,
  onActive,
  isMobile,
}: {
  step: LadderStep;
  index: number;
  onActive: (
    index: number
  ) => void;
  isMobile: boolean;
}) {
  const reduced =
    useReducedMotion();

  const ref =
    useRef<HTMLElement>(null);

  /* Entrance animation */
  const seen = useInView(ref, {
    once: true,
    margin:
      "0px 0px -12% 0px",
  });

  /* Active/crossing state */
  const crossing = useInView(
    ref,
    {
      margin:
        "-62% 0px -38% 0px",
    }
  );

  useEffect(() => {
    if (crossing) {
      onActive(index);
    }
  }, [
    crossing,
    index,
    onActive,
  ]);

  /*
   * Disable animations on mobile
   * or when reduced motion is preferred.
   */
  const shouldAnimate =
    !reduced &&
    !isMobile;

  return (
    <motion.article
      ref={ref}
      className={cx(
        styles.step,
        crossing &&
          styles.on,
        isMobile &&
          styles.stepMobile
      )}
      initial={
        shouldAnimate
          ? {
              x: 44,
              opacity: 0,
            }
          : undefined
      }
      animate={
        seen || !shouldAnimate
          ? {
              x: 0,
              opacity: 1,
            }
          : undefined
      }
      transition={
        shouldAnimate
          ? {
              duration: 0.8,
              ease: ease.power3Out,
            }
          : undefined
      }
    >
      {/* =================================================
          STEP NUMBER
      ================================================= */}

      <span
        className={
          styles.mark
        }
      >
        {step.mark}
      </span>

      {/* =================================================
          LEVEL

          API heading:
          Level 01
          Level 02
          ...
      ================================================= */}

      <p
        className={
          styles.lvl
        }
      >
        {step.level}
      </p>

      {/* =================================================
          STEP TITLE

          API short_description:
          Associate
          Builder
          Leader
          Director
          Ambassador
      ================================================= */}

      <h3>
        {step.title}
      </h3>

      {/* =================================================
          STEP DESCRIPTION
      ================================================= */}

      <p>
        {step.body}
      </p>
    </motion.article>
  );
}

"use client";

import Image from "next/image";
import { useMemo, useRef } from "react";

import {
  motion,
  useReducedMotion,
  useScroll,
  useSpring,
  useTransform,
  type MotionValue,
} from "framer-motion";

import { Eyebrow, Section } from "@/features/landing/components/design-system/index";
import { scrub } from "@/features/landing/components/design-system/motion";
import styles from "@/features/landing/components/components/sections/Nation.module.css";

import { useGetLandingPageQuery } from "@/lib/redux/api/Landing/landingPageApi";

/* =========================================================
   TYPES
========================================================= */

type NationImage = {
  id: number | string;
  url: string;
  alt_text?: string | null;
  is_primary?: boolean;
};

type NationBlock = {
  id?: number | string;
  heading?: string | null;
  short_description?: string | null;
  description?: string | null;
  sort_order?: number;
  images?: NationImage[];
  videos?: unknown[];
};

/* =========================================================
   HELPERS — strip HTML and check for real text
========================================================= */

/**
 * Strip HTML tags and return plain text.
 * Returns "" if nothing meaningful remains.
 */
function stripHtml(html?: string | null): string {
  if (!html) return "";

  // Remove tags, decode a few common entities, collapse whitespace
  const text = html
    .replace(/<[^>]*>/g, " ")           // drop tags
    .replace(/&nbsp;/gi, " ")
    .replace(/&amp;/gi, "&")
    .replace(/&lt;/gi, "<")
    .replace(/&gt;/gi, ">")
    .replace(/&quot;/gi, '"')
    .replace(/&#39;/gi, "'")
    .replace(/\s+/g, " ")               // collapse whitespace
    .trim();

  return text;
}

/**
 * Returns true only if the HTML contains real visible content
 * (e.g. "<p></p>", "<p> </p>", "<br/>" → false).
 */
function hasMeaningfulContent(html?: string | null): boolean {
  return stripHtml(html).length > 0;
}

/* =========================================================
   COLUMN DRIFT
========================================================= */

const COLUMN_DRIFTS = [18, 26, 16, 24, 19];

/* =========================================================
   NATION
========================================================= */

export function Nation() {
  const reduced = useReducedMotion();
  const ref = useRef<HTMLElement>(null);

  const { data: landingData } = useGetLandingPageQuery();

  /* =========================================================
     CHAPTER ONE
  ========================================================= */

  const chapterOneBlock = useMemo<NationBlock | null>(() => {
    const chapterOnePage = landingData?.data?.find(
      (item: any) =>
        item?.slug === "chapter-one" || item?.title === "Chapter One"
    );

    const blocks = chapterOnePage?.blocks || [];

    return blocks.find((block: any) => block?.sort_order === 0) || null;
  }, [landingData]);

  /* =========================================================
     DYNAMIC CONTENT  (FIXED)
  ========================================================= */

  // Heading: only use API value if it has real text — NO fallback
  const chapterHeading = useMemo(() => {
    const apiHeading = chapterOneBlock?.heading;
    return hasMeaningfulContent(apiHeading) ? stripHtml(apiHeading) : "";
  }, [chapterOneBlock]);

  // Description: strip HTML; fall back if nothing meaningful
  const chapterDescription = useMemo(() => {
    const apiDesc =
      chapterOneBlock?.description ?? chapterOneBlock?.short_description;
    return hasMeaningfulContent(apiDesc)
      ? stripHtml(apiDesc)
      : "people. One shared ambition. Before IndieKonnect was a brand, it was an observation: India does not lack talent, it lacks doorways.";
  }, [chapterOneBlock]);

  const chapterImages = useMemo<NationImage[]>(
    () =>
      (chapterOneBlock?.images || []).filter((image: any) =>
        Boolean(image?.url)
      ),
    [chapterOneBlock]
  );

  /* =========================================================
     SPLIT API IMAGES INTO 5 COLUMNS
  ========================================================= */

  const nationColumns = useMemo(() => {
    const totalColumns = COLUMN_DRIFTS.length;

    if (!chapterImages.length) {
      return Array.from({ length: totalColumns }, (_, index) => ({
        images: [] as NationImage[],
        drift: COLUMN_DRIFTS[index],
      }));
    }

    const columns: NationImage[][] = Array.from(
      { length: totalColumns },
      () => []
    );

    chapterImages.forEach((image, index) => {
      columns[index % totalColumns].push(image);
    });

    return columns.map((images, index) => ({
      images,
      drift: COLUMN_DRIFTS[index],
    }));
  }, [chapterImages]);

  /* =========================================================
     PIN PROGRESS
  ========================================================= */

  const { scrollYProgress } = useScroll({
    target: ref,
    offset: ["start start", "end end"],
  });

  const p = useSpring(scrollYProgress, scrub.s08);

  /* =========================================================
     SECTION DRIFT
  ========================================================= */

  const { scrollYProgress: pass } = useScroll({
    target: ref,
    offset: ["start end", "end start"],
  });

  const drift = useSpring(pass, scrub.s10);

  /* =========================================================
     CORE ANIMATION
  ========================================================= */

  const value = useTransform(p, (v) => (v * 1.4).toFixed(1));
  const coreScale = useTransform(p, [0, 1], [0.82, 1]);
  const coreOpacity = useTransform(p, [0, 1], [0.4, 1]);
  const colsOpacity = useTransform(p, [0, 1], [0.1, 0.34]);

  return (
    <Section
      id="nation"
      label="The scale of the movement"
      className={styles.nation}
      ref={ref}
    >
      <div className={styles.pin}>
        {/* BACKGROUND IMAGE COLUMNS */}
        <motion.div
          className={styles.cols}
          style={{ opacity: reduced ? 0.3 : colsOpacity }}
          aria-hidden="true"
        >
          {nationColumns.map((column, columnIndex) => (
            <NationColumn
              key={columnIndex}
              drift={drift}
              amount={column.drift}
              images={column.images}
              reduced={Boolean(reduced)}
            />
          ))}
        </motion.div>

        {/* CENTER CONTENT */}
        <div className={styles.core}>
          {chapterHeading && (
            <Eyebrow center style={{ marginBottom: 22 }}>
              {chapterHeading}
            </Eyebrow>
          )}

          <motion.p
            className={styles.count}
            style={{
              scale: reduced ? 1 : coreScale,
              opacity: reduced ? 1 : coreOpacity,
            }}
          >
            <motion.span>{reduced ? "1.4" : value}</motion.span>
            <sup>billion</sup>
          </motion.p>

          <p className={styles.sub}>{chapterDescription}</p>
        </div>
      </div>
    </Section>
  );
}

/* =========================================================
   NATION COLUMN
========================================================= */

function NationColumn({
  drift,
  amount,
  images,
  reduced,
}: {
  drift: MotionValue<number>;
  amount: number;
  images: NationImage[];
  reduced: boolean;
}) {
  const y = useTransform(drift, [0, 1], [`-${amount}%`, `${amount}%`]);

  return (
    <motion.div
      className={styles.col}
      style={reduced ? undefined : { y }}
    >
      {images.map((image, index) => (
        <figure key={`${image.id}-${index}`}>
          <Image
            src={image.url}
            alt={image.alt_text || ""}
            fill
            sizes="20vw"
          />
        </figure>
      ))}
    </motion.div>
  );
}

