"use client";

import { useObjectUrlRegistry } from "@/hooks/useObjectUrlRegistry";

import React, {
  useState,
  useRef,
  ChangeEvent,
  useEffect,
} from "react";

import {
  motion,
  AnimatePresence,
} from "framer-motion";

import {
  X,
  Trash2,
  AlertCircle,
  Ban,
  RotateCcw,
  Plus,
  Camera,
  Truck,
  Home,
  Info,
} from "lucide-react";

export interface OrderImage {
  id?: string;
  file: File;
  preview: string;
  isUploading?: boolean;
  uploadProgress?: number;
}

export type ReturnMethod = "doorstep" | "courier";

export interface CancelOrderData {
  reason: string;
  images: File[];
  quantity?: number;
  return_method?: ReturnMethod;
  courier?: string;
}

export interface OrderCancelModalProps {
  isOpen: boolean;
  onClose: () => void;
  orderReference: string;
  onCancel: (data: CancelOrderData) => void;
  isLoading?: boolean;
  maxImages?: number;
  maxFileSize?: number;
  minReasonLength?: number;
  modalType?: "cancel" | "return";
  order?: any;
}

const OrderCancelModal: React.FC<
  OrderCancelModalProps
> = ({
  isOpen,
  onClose,
  orderReference,
  onCancel,
  isLoading = false,
  maxImages = 5,
  maxFileSize = 5,
  minReasonLength = 10,
  modalType = "cancel",
  order,
}) => {
  const { createObjectUrl, revokeObjectUrl } = useObjectUrlRegistry();
  const [reason, setReason] =
    useState("");

  const [images, setImages] =
    useState<OrderImage[]>([]);

  const [error, setError] =
    useState("");

  const [isDragging, setIsDragging] =
    useState(false);

  /* ============================================================
     RETURN METHOD STATE
  ============================================================ */
  const [returnMethod, setReturnMethod] =
    useState<ReturnMethod>("doorstep");

  const [courierName, setCourierName] =
    useState("");

  const fileInputRef =
    useRef<HTMLInputElement>(null);

  const isReturn =
    modalType === "return";

  const title = isReturn
    ? "Return Order"
    : "Cancel request";

  const IconComponent = isReturn
    ? RotateCcw
    : Ban;

  const buttonColor = isReturn
    ? "bg-orange-500 hover:bg-orange-600"
    : "bg-red-500 hover:bg-red-600";

  const buttonText = isReturn
    ? "Submit Return Request"
    : "Confirm Cancellation";

  const placeholder = isReturn
    ? "Please tell us why you want to return this order..."
    : "Please tell us why you want to cancel this order...";

  const maxReturnQuantity =
    Number(
      order?.available_for_return
    ) ||
    Number(order?.quantity) ||
    1;

  useEffect(() => {
    resetForm();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [isOpen, order]);

  const resetForm = () => {
    images.forEach((img) => {
      if (img.preview) {
        revokeObjectUrl(
          img.preview
        );
      }
    });

    setImages([]);
    setReason("");
    setError("");

    setReturnMethod("doorstep");
    setCourierName("");

    if (fileInputRef.current) {
      fileInputRef.current.value =
        "";
    }
  };

  const validateFile = (
    file: File
  ): string | null => {
    const maxSizeBytes =
      maxFileSize * 1024 * 1024;

    if (file.size > maxSizeBytes) {
      return `File "${file.name}" exceeds ${maxFileSize}MB limit`;
    }

    if (
      !file.type.startsWith(
        "image/"
      )
    ) {
      return `File "${file.name}" is not an image`;
    }

    const validTypes = [
      "image/jpeg",
      "image/png",
      "image/gif",
      "image/webp",
      "image/svg+xml",
    ];

    if (
      !validTypes.includes(
        file.type
      )
    ) {
      return `File "${file.name}" format not supported`;
    }

    return null;
  };

  const handleImageUpload = (
    event: ChangeEvent<HTMLInputElement>
  ) => {
    const files = event.target.files;

    if (
      !files ||
      files.length === 0
    ) {
      return;
    }

    processFiles(files);

    if (fileInputRef.current) {
      fileInputRef.current.value =
        "";
    }
  };

  const handleDragOver = (
    e: React.DragEvent
  ) => {
    e.preventDefault();
    setIsDragging(true);
  };

  const handleDragLeave = (
    e: React.DragEvent
  ) => {
    e.preventDefault();
    setIsDragging(false);
  };

  const handleDrop = (
    e: React.DragEvent
  ) => {
    e.preventDefault();
    setIsDragging(false);

    const files =
      e.dataTransfer.files;

    if (
      files &&
      files.length > 0
    ) {
      processFiles(files);
    }
  };

  const processFiles = (
    files: FileList
  ) => {
    if (
      images.length +
        files.length >
      maxImages
    ) {
      setError(
        `Maximum ${maxImages} images allowed`
      );

      setTimeout(
        () => setError(""),
        3000
      );

      return;
    }

    const validImages: OrderImage[] =
      [];

    let hasError = false;

    Array.from(files).forEach(
      (file) => {
        const validationError =
          validateFile(file);

        if (validationError) {
          setError(
            validationError
          );

          hasError = true;

          return;
        }

        validImages.push({
          file,

          preview:
            createObjectUrl(
              file
            ),

          isUploading: false,

          uploadProgress: 0,
        });
      }
    );

    if (hasError) {
      setTimeout(
        () => setError(""),
        3000
      );

      return;
    }

    setImages((prev) => [
      ...prev,
      ...validImages,
    ]);
  };

  const removeImage = (
    index: number
  ) => {
    setImages((prev) => {
      const newImages = [
        ...prev,
      ];

      if (
        newImages[index]
          ?.preview
      ) {
        revokeObjectUrl(
          newImages[index].preview
        );
      }

      newImages.splice(
        index,
        1
      );

      return newImages;
    });
  };

  const handleSubmit = (
    e: React.FormEvent
  ) => {
    e.preventDefault();

    setError("");

    if (!reason.trim()) {
      setError(
        `Please provide a reason for ${
          isReturn
            ? "return"
            : "cancellation"
        }`
      );

      return;
    }

    if (
      reason.trim().length <
      minReasonLength
    ) {
      setError(
        `Please provide a more detailed reason (minimum ${minReasonLength} characters)`
      );

      return;
    }

    if (
      isReturn &&
      returnMethod === "courier" &&
      !courierName.trim()
    ) {
      setError(
        "Please enter the courier name"
      );

      return;
    }

    const files = images.map(
      (img) => img.file
    );

    onCancel({
      reason:
        reason.trim(),

      images: files,

      ...(isReturn
        ? {
            quantity:
              maxReturnQuantity,

            return_method:
              returnMethod,

            courier:
              returnMethod ===
              "courier"
                ? courierName.trim()
                : undefined,
          }
        : {}),
    });
  };

  const backdropVariants = {
    hidden: { opacity: 0 },
    visible: { opacity: 1 },
  };

  const modalVariants = {
    hidden: {
      opacity: 0,
      scale: 0.9,
      y: 20,
    },

    visible: {
      opacity: 1,
      scale: 1,
      y: 0,

      transition: {
        type: "spring",
        damping: 25,
        stiffness: 300,
      },
    },

    exit: {
      opacity: 0,
      scale: 0.9,
      y: 20,

      transition: {
        duration: 0.2,
      },
    },
  };

  const imageVariants = {
    hidden: {
      opacity: 0,
      scale: 0.8,
    },

    visible: {
      opacity: 1,
      scale: 1,

      transition: {
        type: "spring",
        damping: 20,
        stiffness: 300,
      },
    },

    exit: {
      opacity: 0,
      scale: 0.8,

      transition: {
        duration: 0.15,
      },
    },
  };

  if (!isOpen) {
    return null;
  }

  return (
    <AnimatePresence>
      {isOpen && (
        <div className="fixed inset-0 z-[9999] overflow-y-auto">
          {/* BACKDROP */}

          <motion.div
            variants={backdropVariants}
            initial="hidden"
            animate="visible"
            exit="hidden"
            className="fixed inset-0 bg-black/60 backdrop-blur-md"
            onClick={onClose}
            aria-hidden="true"
          />

          {/* MODAL */}

          <div className="relative z-[10000] flex min-h-full items-center justify-center p-4">
            <motion.div
              variants={modalVariants}
              initial="hidden"
              animate="visible"
              exit="exit"
              className="relative w-full max-w-lg overflow-hidden rounded-2xl bg-white shadow-2xl"
              onClick={(e) =>
                e.stopPropagation()
              }
            >
              {/* HEADER */}

              <div className="sticky top-0 z-10 border-b border-gray-100 bg-white px-6 py-4">
                <div className="flex items-start justify-between">
                  <div className="flex items-start gap-3">
                    <div
                      className={`flex h-10 w-10 flex-shrink-0 items-center justify-center rounded-xl ${
                        isReturn
                          ? "bg-orange-100"
                          : "bg-red-100"
                      }`}
                    >
                      <IconComponent
                        className={`h-5 w-5 ${
                          isReturn
                            ? "text-orange-600"
                            : "text-red-600"
                        }`}
                      />
                    </div>

                    <div>
                      <h3 className="text-lg font-bold text-gray-900">
                        {title}
                      </h3>

                      <p className="mt-0.5 text-xs text-gray-500">
                        Order:{" "}
                        <span className="font-medium text-gray-700">
                          {orderReference}
                        </span>
                      </p>
                    </div>
                  </div>

                  <button
                    onClick={onClose}
                    className="rounded-lg p-1.5 transition-colors hover:bg-gray-100"
                    disabled={isLoading}
                  >
                    <X className="h-5 w-5 text-gray-500" />
                  </button>
                </div>

                {order && (
                  <div className="mt-3 flex flex-wrap gap-2">
                    <span className="rounded-full bg-gray-100 px-2.5 py-0.5 text-xs text-gray-600">
                      {order.items?.length || 1}{" "}
                      items
                    </span>

                    <span className="rounded-full bg-gray-100 px-2.5 py-0.5 text-xs text-gray-600">
                      ₹
                      {Math.round(
                        Number(
                          order.line_total
                        ) || 0
                      )}
                    </span>
                  </div>
                )}
              </div>

              {/* BODY */}

              <div className="max-h-[calc(90vh-180px)] overflow-y-auto px-6 py-4">
                <form
                  onSubmit={handleSubmit}
                  className="space-y-5"
                >
                  {/* ============================================
                      ✅ RETURN METHOD (only for return)
                  ============================================ */}
                  {isReturn && (
                    <div className="space-y-3">
                      <label className="block text-sm font-medium text-gray-700">
                        Return Method{" "}
                        <span className="text-red-500">
                          *
                        </span>
                      </label>

                      <div className="grid grid-cols-2 gap-3">
                        {/* DOORSTEP */}
                        <button
                          type="button"
                          onClick={() =>
                            setReturnMethod(
                              "doorstep"
                            )
                          }
                          disabled={isLoading}
                          className={`flex flex-col items-start gap-2 rounded-xl border-2 p-3.5 text-left transition-all ${
                            returnMethod ===
                            "doorstep"
                              ? "border-orange-500 bg-orange-50"
                              : "border-gray-200 bg-white hover:border-gray-300"
                          } disabled:cursor-not-allowed disabled:opacity-60`}
                        >
                          <div className="flex w-full items-center justify-between">
                            <Home
                              className={`h-5 w-5 ${
                                returnMethod ===
                                "doorstep"
                                  ? "text-orange-600"
                                  : "text-gray-400"
                              }`}
                            />

                            <div
                              className={`h-4 w-4 rounded-full border-2 ${
                                returnMethod ===
                                "doorstep"
                                  ? "border-orange-500 bg-orange-500"
                                  : "border-gray-300"
                              }`}
                            >
                              {returnMethod ===
                                "doorstep" && (
                                <div className="m-auto mt-[2px] h-1.5 w-1.5 rounded-full bg-white" />
                              )}
                            </div>
                          </div>

                          <div>
                            <p
                              className={`text-sm font-semibold ${
                                returnMethod ===
                                "doorstep"
                                  ? "text-orange-700"
                                  : "text-gray-700"
                              }`}
                            >
                              Doorstep
                            </p>

                            <p className="mt-0.5 text-[11px] leading-tight text-gray-500">
                              Pickup from your
                              address
                            </p>
                          </div>
                        </button>

                        {/* COURIER */}
                        <button
                          type="button"
                          onClick={() =>
                            setReturnMethod(
                              "courier"
                            )
                          }
                          disabled={isLoading}
                          className={`flex flex-col items-start gap-2 rounded-xl border-2 p-3.5 text-left transition-all ${
                            returnMethod ===
                            "courier"
                              ? "border-orange-500 bg-orange-50"
                              : "border-gray-200 bg-white hover:border-gray-300"
                          } disabled:cursor-not-allowed disabled:opacity-60`}
                        >
                          <div className="flex w-full items-center justify-between">
                            <Truck
                              className={`h-5 w-5 ${
                                returnMethod ===
                                "courier"
                                  ? "text-orange-600"
                                  : "text-gray-400"
                              }`}
                            />

                            <div
                              className={`h-4 w-4 rounded-full border-2 ${
                                returnMethod ===
                                "courier"
                                  ? "border-orange-500 bg-orange-500"
                                  : "border-gray-300"
                              }`}
                            >
                              {returnMethod ===
                                "courier" && (
                                <div className="m-auto mt-[2px] h-1.5 w-1.5 rounded-full bg-white" />
                              )}
                            </div>
                          </div>

                          <div>
                            <p
                              className={`text-sm font-semibold ${
                                returnMethod ===
                                "courier"
                                  ? "text-orange-700"
                                  : "text-gray-700"
                              }`}
                            >
                              Courier
                            </p>

                            <p className="mt-0.5 text-[11px] leading-tight text-gray-500">
                              Ship it yourself
                            </p>
                          </div>
                        </button>
                      </div>

                      {/* COURIER NAME (only when courier selected) */}
                      {returnMethod ===
                        "courier" && (
                        <motion.div
                          initial={{
                            opacity: 0,
                            height: 0,
                          }}
                          animate={{
                            opacity: 1,
                            height: "auto",
                          }}
                          exit={{
                            opacity: 0,
                            height: 0,
                          }}
                          transition={{
                            duration: 0.2,
                          }}
                        >
                          <label
                            htmlFor="courierName"
                            className="mb-1.5 block text-sm font-medium text-gray-700"
                          >
                            Courier Name{" "}
                            <span className="text-red-500">
                              *
                            </span>
                          </label>

                          <input
                            id="courierName"
                            type="text"
                            value={courierName}
                            onChange={(e) =>
                              setCourierName(
                                e.target.value
