"use client";

import { useObjectUrlRegistry } from "@/hooks/useObjectUrlRegistry";

import { useState, useRef, useEffect } from "react";
import { motion, AnimatePresence } from "framer-motion";
import Image from "next/image";
import {
  Star,
  X,
  Plus,
  Camera,
  Trash2,
  Send,
  AlertCircle,
  Check,
  Package,
} from "lucide-react";
import { readCaughtMessage } from "@/lib/utils/readCaughtMessage";


interface ReviewModalProps {
  isOpen: boolean;
  onClose: () => void;
  order: any; // This is actually a line item now
  onSubmit: (reviewData: any) => Promise<void>;
}

const ReviewModal = ({
  isOpen,
  onClose,
  order,
  onSubmit,
}: ReviewModalProps) => {
  const { createObjectUrl, revokeObjectUrl } = useObjectUrlRegistry();
  const [rating, setRating] = useState(0);
  const [hoverRating, setHoverRating] = useState(0);
  const [reviewText, setReviewText] = useState("");
  const [images, setImages] = useState<File[]>([]);
  const [imagePreviews, setImagePreviews] = useState<string[]>([]);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [error, setError] = useState("");
  const [isSuccess, setIsSuccess] = useState(false);

  const fileInputRef = useRef<HTMLInputElement>(null);
  const textareaRef = useRef<HTMLTextAreaElement>(null);

  useEffect(() => {
    if (!isOpen) {
      imagePreviews.forEach((url) => revokeObjectUrl(url));

      setRating(0);
      setHoverRating(0);
      setReviewText("");
      setImages([]);
      setImagePreviews([]);
      setError("");
      setIsSuccess(false);
      setIsSubmitting(false);
    }
  }, [isOpen]);

  useEffect(() => {
    if (isOpen && textareaRef.current) {
      const timer = setTimeout(() => {
        textareaRef.current?.focus();
      }, 300);

      return () => clearTimeout(timer);
    }
  }, [isOpen]);

  const handleImageUpload = (
    e: React.ChangeEvent<HTMLInputElement>,
  ) => {
    const files = Array.from(e.target.files || []);
    setError("");

    if (!files.length) return;

    if (files.length + images.length > 5) {
      setError("You can upload maximum 5 images.");
      return;
    }

    const oversizedFiles = files.filter(
      (file) => file.size > 5 * 1024 * 1024,
    );

    if (oversizedFiles.length > 0) {
      setError("Some files exceed the 5MB limit.");
      return;
    }

    const validTypes = [
      "image/jpeg",
      "image/png",
      "image/gif",
      "image/webp",
    ];

    const invalidFiles = files.filter(
      (file) => !validTypes.includes(file.type),
    );

    if (invalidFiles.length > 0) {
      setError("Only JPG, PNG, GIF, and WEBP formats are allowed.");
      return;
    }

    const newPreviews = files.map((file) =>
      createObjectUrl(file),
    );

