                                  </div>
                                </div>

                                {representative.delivery_address && (
                                  <div className="border-t border-[#EDF0F3] px-4 py-4 sm:px-5">
                                    <p className="text-[10px] font-medium uppercase tracking-[0.08em] text-[#8A92A6]">
                                      Shipping Address
                                    </p>
                                    <div className="mt-1.5 flex items-start gap-2 text-[12.5px] leading-5 text-[#344054]">
                                      <MapPin
                                        size={14}
                                        className="mt-0.5 shrink-0 text-[#98a2b3]"
                                      />
                                      <span className="break-words">
                                        {representative.delivery_address
                                          ?.full_address || "N/A"}
                                      </span>
                                    </div>
                                  </div>
                                )}
                              </div>

                              {/* REVIEWS */}
                              {linesWithReviews.length > 0 && (
                                <div className="space-y-3">
                                  <p className="text-[10px] font-medium uppercase tracking-[0.08em] text-[#888888]">
                                    Product Reviews
                                  </p>

                                  {linesWithReviews.map((l) => (
                                    <div key={l.display_id}>
                                      {lines.length > 1 && (
                                        <p className="mb-1.5 text-[11px] font-semibold text-[#344054]">
                                          {l.product_name}
                                        </p>
                                      )}
                                      <ReviewDisplay
                                        reviews={l.product_reviews}
                                      />
                                    </div>
                                  ))}
                                </div>
                              )}

                              {/* REFUND / CREDIT NOTES */}
                              {creditNotes.length > 0 && (
                                <RefundCreditDisplay
                                  creditNotes={creditNotes}
                                />
                              )}

                              {/* FOOTER ACTIONS */}
                              <div className="flex flex-wrap items-center justify-between gap-2.5 border-t border-[#E6E6E4] pt-4">
                                <button
                                  type="button"
                                  onClick={() => openTrackModal(group)}
                                  className="inline-flex items-center gap-1.5 rounded-[8px] border border-[#CBD5F0] bg-[#EEF1FB] px-3.5 py-2 text-[11px] font-semibold text-[#3E5AA8] transition hover:bg-[#3E5AA8] hover:text-white"
                                >
                                  <Truck className="h-3.5 w-3.5" />
                                  Track Order
                                </button>

                                <div className="flex flex-wrap items-center gap-2">
                                  <button
                                    type="button"
                                    onClick={() => setBreakupOrder(group)}
                                    className="inline-flex items-center gap-1.5 rounded-[8px] border border-[#C9D5F7] bg-[#F4F6FC] px-3.5 py-2 text-[11px] font-semibold text-[#3955A6] transition hover:bg-[#ECEFFC]"
                                  >
                                    <LuReceiptIndianRupee size={14} />
                                    View Breakup
                                  </button>
                                </div>
                              </div>
                            </div>
                          </motion.div>
                        )}
                      </AnimatePresence>
                    </motion.article>
                  );
                })}
              </motion.div>
            )}
          </motion.div>
        </div>

        {/* ========================================================
            BREAKUP MODAL
        ======================================================== */}

        <AnimatePresence>
          {breakupOrder && (
            <motion.div
              className="fixed inset-0 z-[100] flex items-center justify-center bg-black/35 p-3 font-sans backdrop-blur-[2px] sm:p-4"
              initial={{ opacity: 0 }}
              animate={{ opacity: 1 }}
              exit={{ opacity: 0 }}
              onClick={() => setBreakupOrder(null)}
            >
              <motion.div
                initial={{ opacity: 0, scale: 0.98, y: 12 }}
                animate={{ opacity: 1, scale: 1, y: 0 }}
                exit={{ opacity: 0, scale: 0.98, y: 12 }}
                transition={{ duration: 0.2 }}
                onClick={(e) => e.stopPropagation()}
                className="flex max-h-[92vh] w-full max-w-2xl flex-col overflow-hidden rounded-[16px] border border-[#E4E4E2] bg-white shadow-[0_18px_60px_rgba(0,0,0,0.14)]"
              >
                <div className="flex shrink-0 items-center justify-between border-b border-[#E6E6E4] px-4 py-4 sm:px-5">
                  <div className="min-w-0">
                    <h3 className="text-[16px] font-semibold text-[#171717]">
                      Order Price Breakup
                    </h3>

                    <p className="mt-0.5 break-all text-[10px] text-[#888888]">
                      {breakupOrder.order_reference}
                    </p>
                  </div>

                  <button
                    onClick={() => setBreakupOrder(null)}
                    className="flex h-8 w-8 shrink-0 items-center justify-center rounded-[6px] border border-[#D7D7D5] bg-white text-[#777777] transition hover:border-[#BDBDBA] hover:text-[#111111]"
                  >
                    <X className="h-4 w-4" />
                  </button>
                </div>

                <div className="min-h-0 flex-1 overflow-y-auto p-4 sm:p-5">
                  <div className="space-y-2.5">
                    {breakupOrder.lines.map((item: any) => {
                      const isCancelled =
                        normalizeStatus(item.delivery_status) === "cancelled";

                      return (
                        <div
                          key={item.line_id}
                          className={`flex items-center justify-between gap-3 rounded-[10px] border p-3 sm:p-3.5 ${
                            isCancelled
                              ? "border-[#F0CFCF] bg-[#FDF2F2]"
                              : "border-[#E4E4E2] bg-[#FAFAF9]"
                          }`}
                        >
                          <div className="flex min-w-0 items-center gap-3">
                            <div className="relative h-12 w-12 flex-shrink-0 overflow-hidden rounded-[8px] border border-[#E4E4E2] bg-white">
                              {item.primary_image ? (
                                <Image
                                  src={item.primary_image}
                                  alt={item.product_name || "Product"}
                                  fill
                                  sizes="48px"
                                  className="object-contain p-1"
                                />
                              ) : (
                                <div className="flex h-full items-center justify-center">
                                  <Package className="h-4 w-4 text-[#999999]" />
                                </div>
                              )}
                            </div>

                            <div className="min-w-0">
                              <p className="truncate text-[12px] font-medium text-[#171717]">
                                {item.product_name}
                                {isCancelled && (
                                  <span className="ml-2 text-[10px] font-medium text-[#B24C4C]">
                                    (Cancelled)
                                  </span>
                                )}
                              </p>

                              <p className="mt-0.5 text-[10px] text-[#888888]">
                                Qty: {item.quantity}
                                {Number(item.gst_amount) > 0
                                  ? ` • GST: ${item.gst_rate}%`
                                  : ""}
                              </p>
                            </div>
                          </div>

                          <div className="shrink-0 text-right">
                            <p
                              className={`text-[14px] font-semibold ${
                                isCancelled
                                  ? "text-[#B24C4C]"
                                  : "text-[#111111]"
                              }`}
                            >
                              {formatPrice(Number(item.final_amount) || 0)}
                            </p>

                            <p className="mt-0.5 text-[10px] text-[#888888]">
                              {formatPrice(Number(item.unit_price) || 0)} ×{" "}
                              {item.quantity}
                            </p>
                          </div>
                        </div>
                      );
                    })}
                  </div>

                  <div className="mt-4 border-t border-[#E6E6E4] pt-4">
                    <div className="flex justify-between py-1.5 text-[12px]">
                      <span className="text-[#888888]">Subtotal</span>

                      <span className="font-medium text-[#171717]">
                        {formatPrice(
                          Number(breakupOrder.representative.subtotal) || 0,
                        )}
                      </span>
                    </div>

                    <div className="flex justify-between py-1.5 text-[12px]">
                      <span className="text-[#888888]">GST</span>

                      <span className="font-medium text-[#171717]">
                        {formatPrice(
                          Number(breakupOrder.representative.total_gst) || 0,
                        )}
                      </span>
                    </div>

                    <div className="flex justify-between py-1.5 text-[12px]">
                      <span className="text-[#888888]">Shipping</span>

                      <span className="font-medium text-[#171717]">
                        {formatPrice(
                          Number(breakupOrder.representative.shipping_charge) ||
                            0,
                        )}
                      </span>
                    </div>

                    {Number(breakupOrder.representative.coin_redeemed_amount) >
                      0 && (
                      <div className="flex justify-between py-1.5 text-[12px]">
                        <span className="text-[#888888]">Coins Redeemed</span>

                        <span className="font-medium text-[#3F765A]">
                          -
                          {formatPrice(
                            Number(
                              breakupOrder.representative.coin_redeemed_amount,
                            ) || 0,
                          )}
                        </span>
                      </div>
                    )}

                    <div className="mt-2 flex justify-between border-t border-[#E6E6E4] pt-3">
                      <span className="text-[13px] font-semibold text-[#171717]">
                        Final Amount
                      </span>

                      <span className="text-[17px] font-semibold text-[#111111]">
                        {formatPrice(breakupOrder.total)}
                      </span>
                    </div>
                  </div>
                </div>
              </motion.div>
            </motion.div>
          )}
        </AnimatePresence>

        {/* ========================================================
            TRACK MODAL
        ======================================================== */}

        <AnimatePresence>
          {showTrackModal && (
            <TrackModal
              isOpen={showTrackModal}
              onClose={() => {
                setShowTrackModal(false);
                setSelectedOrderForTracking(null);
              }}
              order={selectedOrderForTracking}
              tracking={
                indiaPostTrackingResponse?.data &&
                // Never show previous order's cached tracking in a new modal.
                Number(indiaPostTrackingResponse.data.order_id) ===
                  Number(selectedOrderForTracking?.order_id) &&
                // Reference must also match whenever Laravel sends it.
                (!indiaPostTrackingResponse.data.order_reference ||
                  indiaPostTrackingResponse.data.order_reference ===
                    selectedOrderForTracking?.order_reference)
                  ? indiaPostTrackingResponse.data
                  : null
              }
              loading={isIndiaPostTracking}
              loadFailed={isIndiaPostTrackingError}
              onRefresh={refreshIndiaPostTracking}
            />
          )}
        </AnimatePresence>
      </div>
    </>
  );
}

"use client";

import Header from "@/components/common/Header";
import Footer from "@/components/Footer/Footer";
import { useGetFAQsQuery } from "@/lib/redux/api/faqApi";
import { useGetContentsQuery } from "@/lib/redux/api/Home/contentApi";
import { useParams } from "next/navigation";
import { useEffect, useMemo, useState } from "react";
import { ContentData, FAQItem, FAQResponse, FAQSectionItem, SafeHtml } from "@/features/policies/routes/[slug]/FooterPolicyClient.parts/support";


/* =========================================================
   MAIN COMPONENT
========================================================= */

export const FooterPolicyClient =
  () => {
    const params = useParams();

    const slug =
      typeof params?.slug ===
      "string"
        ? params.slug
        : "";

    const isFAQsPage =
      slug.toLowerCase() ===
      "faqs";

    /* =====================================================
       POLICY API
    ===================================================== */

    const {
      data: contentsData,
      isLoading: contentsLoading,
      error: contentsError,
    } = useGetContentsQuery(
      {},
      {
        skip: isFAQsPage,
      }
    );

    /* =====================================================
       FAQ API

       Your faqApi endpoint expects `void`,
       therefore use undefined as argument.
    ===================================================== */

    const {
      data: faqData,
      isLoading: faqLoading,
      error: faqError,
    } = useGetFAQsQuery(
      undefined,
      {
        skip: !isFAQsPage,
      }
    );

    const [content, setContent] =
      useState<ContentData | null>(
        null
      );

    /* =====================================================
       FAQ DATA
    ===================================================== */

    const faqResponse =
      faqData as
        | FAQResponse
        | undefined;

    const faqItems =
      faqResponse?.data || [];

    /* =====================================================
       FIND POLICY CONTENT
    ===================================================== */

    useEffect(() => {
      if (
        isFAQsPage ||
        !contentsData?.data ||
        !slug
      ) {
        return;
      }

      const found =
        contentsData.data.find(
          (item: ContentData) =>
            item.slug === slug
        );

      setContent(
        found || null
      );
    }, [
      contentsData,
      slug,
      isFAQsPage,
    ]);

    /* =====================================================
       GROUP FAQS BY SECTION
    ===================================================== */

    const groupedFaqs = useMemo(() => {
      const grouped: Record<
        string,
        {
          sectionId: number;
          sectionName: string;
          sectionSlug: string;
          faqs: FAQItem[];
        }
      > = {};

      const activeFaqs =
        faqItems
          .filter(
            (faq) =>
              faq.is_active === true
          )
          .sort((a, b) => {
            if (
              a.order !== b.order
            ) {
              return (
                a.order - b.order
              );
            }

            return a.id - b.id;
          });

      activeFaqs.forEach(
        (faq) => {
          const sectionId =
            faq.section &&
            faq.section.id
              ? faq.section.id
              : faq.section_id;

          const sectionName =
            faq.section &&
            faq.section.name
              ? faq.section.name
              : "Support";

          const sectionSlug =
            faq.section &&
            faq.section.slug
              ? faq.section.slug
              : "section-" +
                String(sectionId);

          if (
            !grouped[sectionSlug]
          ) {
            grouped[sectionSlug] = {
              sectionId:
                sectionId,
              sectionName:
                sectionName,
              sectionSlug:
                sectionSlug,
              faqs: [],
            };
          }

          grouped[
            sectionSlug
          ].faqs.push(faq);
        }
      );

      return Object.values(
        grouped
      );
    }, [faqItems]);

    /* =====================================================
       HEADING RENDER
    ===================================================== */

    const renderHeading = (
      heading: string
    ) => {
      if (!heading) {
        return null;
      }

      if (
        heading.includes("<h1") ||
        heading.includes("<h2") ||
        heading.includes("<h3") ||
        heading.includes("<h4")
      ) {
        return (
          <SafeHtml
            html={heading}
            className="policy-heading-html"
          />
        );
      }

      let headingLevel:
        | "h1"
        | "h2"
        | "h3"
        | "h4" = "h4";

      if (
        heading
          .toLowerCase()
          .startsWith("h1")
      ) {
        headingLevel = "h1";
      } else if (
        heading
          .toLowerCase()
          .startsWith("h2")
      ) {
        headingLevel = "h2";
      } else if (
        heading
          .toLowerCase()
          .startsWith("h3")
      ) {
        headingLevel = "h3";
      }

      const cleanText =
        heading
          .replace(
            /<h[1-4]>/gi,
            ""
          )
          .replace(
            /<\/h[1-4]>/gi,
            ""
          )
          .trim();

      if (
        headingLevel === "h1"
      ) {
        return (
          <h1 className="font-bold tracking-[-0.01em] text-[#1a1a2e]">
            {cleanText}
          </h1>
        );
      }

      if (
        headingLevel === "h2"
      ) {
        return (
          <h2 className="font-bold tracking-[-0.01em] text-[#1a1a2e]">
            {cleanText}
          </h2>
        );
      }

      if (
        headingLevel === "h3"
      ) {
        return (
          <h3 className="font-bold tracking-[-0.01em] text-[#1a1a2e]">
            {cleanText}
          </h3>
        );
      }

      return (
        <h4 className="font-bold tracking-[-0.01em] text-[#1a1a2e]">
          {cleanText}
        </h4>
      );
    };

    /* =====================================================
       FAQ LOADING
    ===================================================== */

    if (
      isFAQsPage &&
      faqLoading
    ) {
      return (
        <div className="min-h-screen bg-[#f5f6f8]">
          <Header />

          <main className="min-h-[700px]">
            {/* FAQ HERO */}

            <div className="relative overflow-hidden bg-gradient-to-br from-[#1a1a2e] via-[#2d2b4a] to-[#3d3a5c] px-6 py-20 text-center md:py-[60px]">
              <div className="relative z-10 mx-auto max-w-[800px]">
                <span className="mb-5 inline-block rounded-full border border-[rgba(249,199,68,0.2)] bg-[rgba(249,199,68,0.15)] px-5 py-1.5 text-[13px] font-semibold uppercase tracking-[2px] text-[#f9c744]">
                  Help Center
                </span>

                <h1 className="mb-4 text-[clamp(2rem,5vw,3.5rem)] font-bold leading-[1.15] tracking-[-0.02em] text-white">
                  Frequently Asked Questions
                </h1>

                <p className="text-[15px] text-white/60">
                  Find answers to common questions
                  about IndieKonnect
                </p>
              </div>

              <div className="absolute bottom-0 left-0 right-0 h-1 bg-gradient-to-r from-[#f9c744] via-[#8b7bbf] via-[#c44a6a] to-[#4bbf8a] to-[#f9c744]" />
            </div>

            {/* LOADER */}

            <div className="flex min-h-[450px] flex-col items-center justify-center gap-5">
              <div className="h-12 w-12 animate-spin rounded-full border-4 border-[#f9c744] border-t-transparent" />

              <p className="text-[15px] text-[#9a97b0]">
                Loading FAQs...
              </p>
            </div>
          </main>

          <Footer />
        </div>
      );
    }

    /* =====================================================
       FAQ ERROR
    ===================================================== */

    if (
      isFAQsPage &&
      faqError
    ) {
      return (
        <div className="min-h-screen bg-[#f5f6f8]">
          <Header />

          <main>
            <div className="relative overflow-hidden bg-gradient-to-br from-[#1a1a2e] via-[#2d2b4a] to-[#3d3a5c] px-6 py-20 text-center md:py-[60px]">
              <div className="relative z-10 mx-auto max-w-[800px]">
                <span className="mb-5 inline-block rounded-full border border-[rgba(249,199,68,0.2)] bg-[rgba(249,199,68,0.15)] px-5 py-1.5 text-[13px] font-semibold uppercase tracking-[2px] text-[#f9c744]">
                  Help Center
                </span>

                <h1 className="text-[clamp(2rem,5vw,3.5rem)] font-bold text-white">
                  Frequently Asked Questions
                </h1>
              </div>
            </div>

            <div className="flex min-h-[500px] flex-col items-center justify-center px-5 text-center">
              <div className="mb-5 text-6xl">
                ❓
              </div>

              <h2 className="mb-3 text-2xl font-bold text-[#1a1a2e]">
                FAQs Not Available
              </h2>

              <p className="max-w-[450px] text-[15px] leading-7 text-[#6b6882]">
                We could not load the FAQ sections
                right now. Please try again later.
              </p>
            </div>
          </main>

          <Footer />
        </div>
      );
    }

    /* =====================================================
       FAQ PAGE
    ===================================================== */

    if (isFAQsPage) {
      return (
        <div className="min-h-screen bg-[#f5f6f8]">
          <Header />

          <main>
            {/* FAQ HERO */}

            <div className="relative overflow-hidden bg-gradient-to-br from-[#1a1a2e] via-[#2d2b4a] to-[#3d3a5c] px-6 py-20 text-center md:py-[60px]">
              <div className="absolute -right-[20%] -top-[50%] h-[600px] w-[600px] rounded-full bg-[radial-gradient(circle,rgba(249,199,68,0.08)_0%,transparent_70%)]" />

              <div className="absolute -bottom-[30%] -left-[10%] h-[400px] w-[400px] rounded-full bg-[radial-gradient(circle,rgba(139,123,191,0.06)_0%,transparent_70%)]" />

              <div className="relative z-10 mx-auto max-w-[800px]">
                <span className="mb-5 inline-block rounded-full border border-[rgba(249,199,68,0.2)] bg-[rgba(249,199,68,0.15)] px-5 py-1.5 text-[13px] font-semibold uppercase tracking-[2px] text-[#f9c744] backdrop-blur-[10px]">
                  Help Center
                </span>

                <h1 className="mb-4 text-[clamp(2rem,5vw,3.5rem)] font-bold leading-[1.15] tracking-[-0.02em] text-white">
                  Frequently Asked Questions
                </h1>

                <p className="text-[15px] tracking-[0.3px] text-white/60">
                  Find answers to common questions
                  about IndieKonnect
                </p>
              </div>

              <div className="absolute bottom-0 left-0 right-0 h-1 bg-gradient-to-r from-[#f9c744] via-[#8b7bbf] via-[#c44a6a] to-[#4bbf8a] to-[#f9c744] bg-[length:200%_100%] animate-[gradientMove_4s_ease-in-out_infinite]" />
            </div>

            {/* FAQ CONTENT */}

            <section className="bg-[#f5f6f8] px-5 py-10 pb-20 md:px-8 md:py-14 md:pb-24">
              <div className="mx-auto max-w-[1280px]">
                {groupedFaqs.length > 0 ? (
                  <div className="space-y-9 md:space-y-10">
                    {groupedFaqs.map(
                      (section) => (
                        <FAQSectionItem
                          key={
                            section.sectionId
                          }
                          section={
                            section
                          }
                        />
                      )
                    )}
                  </div>
                ) : (
                  <div className="flex min-h-[350px] flex-col items-center justify-center text-center">
                    <div className="mb-5 text-5xl">
                      ❓
                    </div>

                    <h2 className="mb-2 text-2xl font-bold text-[#1a1a2e]">
                      No FAQ Sections Found
                    </h2>

                    <p className="text-[15px] text-[#6b6882]">
                      FAQ sections are currently
                      unavailable.
                    </p>
                  </div>
                )}
              </div>
            </section>
          </main>

          <Footer />

          <style jsx global>{`
            @keyframes gradientMove {
              0%,
              100% {
                background-position: 0% 50%;
              }

              50% {
                background-position: 100% 50%;
              }
            }

            .faq-answer-html {
              color: #707070;
              font-size: 15px;
              line-height: 1.8;
            }

            .faq-answer-html p {
              margin: 0 0 14px;
            }

            .faq-answer-html p:last-child {
              margin-bottom: 0;
            }

            .faq-answer-html strong,
            .faq-answer-html b {
              color: #181818;
              font-weight: 700;
            }

