              ))}
            </div>
          </div>
        )}
      </div>

      <style jsx global>{`
        .policy-content h1 {
          font-size: 2.25rem;
          font-weight: 700;
          color: #1a1a2e;
          line-height: 1.2;
          margin-bottom: 0.5rem;
        }

        .policy-content h2 {
          font-size: 1.75rem;
          font-weight: 700;
          color: #1a1a2e;
          line-height: 1.25;
          margin-bottom: 0.5rem;
        }

        .policy-content h3 {
          font-size: 1.35rem;
          font-weight: 700;
          color: #1a1a2e;
          line-height: 1.3;
          margin-bottom: 0.5rem;
