        .policy-content p {
          font-size: 1rem;
          line-height: 1.8;
          color: #6b6882;
          margin-bottom: 1rem;
        }

        .policy-content ul {
          padding: 0;
          margin: 1rem 0 1.25rem;
          list-style: none;
        }

        .policy-content li {
          position: relative;
          padding: 0.5rem 0 0.5rem 1.75rem;
          font-size: 1rem;
          line-height: 1.7;
          color: #6b6882;
          border-bottom: 1px solid rgba(0, 0, 0, 0.06);
        }

        .policy-content li:last-child {
          border-bottom: none;
        }

        .policy-content li::before {
          content: "✦";
          position: absolute;
          left: 0;
          top: 0.5rem;
          color: #f9c744;
        }

        .policy-content strong {
          color: #1a1a2e;
          font-weight: 600;
        }

        .policy-content a {
          color: #8b7bbf;
          text-decoration: none;
        }

        .policy-content a:hover {
          color: #e8a82c;
        }

        @media (max-width: 768px) {
          .policy-content h1 {
            font-size: 1.75rem;
          }

          .policy-content h2 {
            font-size: 1.4rem;
          }

          .policy-content h3 {
            font-size: 1.15rem;
          }

          .policy-content p,
          .policy-content li {
            font-size: 0.95rem;
          }
        }
      `}</style>
    </div>
  );
}

