export default function ProductCard(props: ProductCardProps) {
  const item = props?.product;

  if (
    !item ||
    typeof item !== "object" ||
    item.id === null ||
    item.id === undefined
  ) {
    return null;
  }

  return <ProductCardInner {...props} product={item} />;
}

