                    ([key, value]) => (
                      <span key={key}>
                        {key}:
                        <span className="ml-1 font-semibold text-[#111]">
                          {value}
                        </span>
                      </span>
                    ),
                  )}
                </div>
              </div>
            )}

            {/* ACTIONS */}
            <div className="mt-5 flex items-center gap-2 border-t border-[#E8E8E8] pt-4">
              {mainPurchaseAvailable ? (
                <>
                  <motion.button
                    whileTap={{
                      scale: 0.98,
