                    <p className="mt-2 text-xs text-[#777]">
                      {product.reviews}{" "}
                      {product.reviews === 1 ? "review" : "reviews"}
                    </p>

                    {reviewsSummary?.rating_distribution && (
                      <div className="mt-4 space-y-1.5 text-left">
                        {[5, 4, 3, 2, 1].map((star) => {
                          const count = Number(
                            reviewsSummary.rating_distribution?.[star] || 0,
