                          return (
                            <div
                              key={star}
                              className="flex items-center gap-2 text-[9px] text-[#777]"
                            >
                              <span className="w-5">{star}★</span>

                              <div className="h-1.5 flex-1 overflow-hidden rounded-full bg-[#EDEDED]">
