const {
    isCombo,
    comboItems,
    manufacturingInfo,
    reviewsSummary,
    reviewsList,
    product,
    productGallery,
    comboTotals,
  } = useProductModel(apiProduct, userAccountType);

const {
    variantEntries,
    hasVariants,
    variantAttributeOptions,
    displayVariants,
    isMainProductSelected,
    selectedVariant,
    selectedAllowsPurchaseWithoutStock,
    mainPurchaseAvailable,
    gallery,
  } = useProductVariants(apiProduct, product, productGallery, selectedVariantId);

const [previousProductId, setPreviousProductId] = useState(product?.id);
if (previousProductId !== product?.id) {
    setPreviousProductId(product?.id);
    if (product) {
      setSelectedVariantId(null);
      setSelectedVariantAttributes({});
      setActiveImage(0);
    }
  }

const handleSelectMainProduct = () => {
    if (product?.slug && product.slug !== activeProductSlug) {
      router.replace(buildProductPath(product.slug), {
        scroll: false,
      });
    }

    setSelectedVariantId(null);
    setSelectedVariantAttributes({});
    setActiveImage(0);
  };

const handleSelectVariant = (variant: any) => {
    if (variant?.isMainProduct || variant?.id === "main-product") {
      handleSelectMainProduct();
      return;
    }

    if (
      variant?.slug &&
      String(variant?.product_id ?? variant?.id) !== String(product?.id)
    ) {
      setSelectedVariantId(variant.id);

      setSelectedVariantAttributes(
        variant?.parsedAttributes || parseJsonObject(variant?.attributes),
      );

      setActiveImage(0);
      setQuantity(1);

      if (variant.slug !== activeProductSlug) {
        router.replace(buildProductPath(variant.slug), {
          scroll: false,
        });
      }

      return;
    }

    setSelectedVariantId(variant.id);

    const attrs =
      variant?.parsedAttributes || parseJsonObject(variant?.attributes);

    setSelectedVariantAttributes({
      ...attrs,
    });

    setActiveImage(0);
  };

const handleAttributeSelect = (attributeKey: string, value: string) => {
    const nextAttributes = {
      ...selectedVariantAttributes,
      [attributeKey]: value,
    };

    setSelectedVariantAttributes(nextAttributes);

    const matchingVariant = variantEntries.find((variant: any) => {
      const attrs = variant?.parsedAttributes || {};

      return Object.entries(nextAttributes).every(
        ([key, selectedValue]) =>
          String(attrs?.[key] ?? "") === String(selectedValue),
      );
    });

    if (matchingVariant) {
      setSelectedVariantId(matchingVariant.id);
      setActiveImage(0);
    }
  };

useEffect(() => {
    if (hasToken !== true) {
      setIsWishlisted(false);
      setWishlistState({});
      return;
    }

    if (wishlistData?.data && product?.id) {
      const exists = wishlistData.data.some(
        (item: any) => String(item.product_id) === String(product.id),
      );

      setIsWishlisted(exists);
    }
  }, [wishlistData, product?.id, hasToken]);

useEffect(() => {
    if (hasToken !== true || !wishlistData?.data) return;

    const map: Record<number, boolean> = {};

    wishlistData.data.forEach((item: any) => {
      map[item.product_id] = true;
    });

    setWishlistState(map);
  }, [wishlistData, hasToken]);

const handleWishlistToggle = async (e?: React.MouseEvent<HTMLElement>) => {
    if (!product || isWishlistLoading) return;

    if (hasToken !== true) {
      router.push(getLoginPath());
      return;
    }

    if (e) popHeart(e);

    setIsWishlistLoading(true);

    try {
      if (isWishlisted) {
        await removeFromWishlist({
          product_id: product.id,
        }).unwrap();

        setIsWishlisted(false);

        dispatch(
          showToast({
            message: `${product.name} removed from wishlist`,
            type: "info",
          }),
        );
      } else {
        await addToWishlist({
          product_id: product.id,
        }).unwrap();

        setIsWishlisted(true);

        dispatch(
          showToast({
            message: `${product.name} added to wishlist! ❤️`,
            type: "success",
          }),
        );
      }

      await refetchWishlist();
    } catch (error: unknown) {
      dispatch(
        showToast({
          message: readCaughtMessage(error, "data", "message") || "Failed to update wishlist",
          type: "error",
        }),
      );
    } finally {
      setIsWishlistLoading(false);
    }
  };

const toggleWishlist = async (productId: number) => {
    if (hasToken !== true) {
      router.push(getLoginPath());
      return;
    }

    try {
      const exists = wishlistState[productId] || false;

      if (exists) {
        await removeFromWishlist({
          product_id: productId,
        }).unwrap();

        setWishlistState((prev) => ({
          ...prev,
          [productId]: false,
        }));

        dispatch(
          showToast({
            message: "Removed from wishlist",
            type: "info",
          }),
        );
      } else {
        await addToWishlist({
          product_id: productId,
        }).unwrap();

        setWishlistState((prev) => ({
          ...prev,
          [productId]: true,
        }));

        dispatch(
          showToast({
            message: "Added to wishlist! ❤️",
            type: "success",
          }),
        );
      }

      await refetchWishlist();
    } catch (error: unknown) {
      dispatch(
        showToast({
          message: readCaughtMessage(error, "data", "message") || "Failed to update wishlist",
          type: "error",
        }),
      );
    }
  };

const checkFreshStock = async (
    productIdToCheck: number,
    qty: number,
    purchaseWithoutStock = false,
  ): Promise<boolean> => {
    const id = Number(productIdToCheck);
    const quantityToCheck = Number(qty);

    if (
      !Number.isInteger(id) ||
      id <= 0 ||
      !Number.isInteger(quantityToCheck) ||
      quantityToCheck <= 0
    ) {
      throw new Error(
        "Invalid product or quantity. Please refresh and try again.",
      );
    }

    // Whitelisted products may be purchased regardless of inventory.
    // Skip ONLY the stock check; the cart/order API remains authoritative.
    if (purchaseWithoutStock) return true;

    let result;

    try {
      result = await checkProductStock({
        product_id: id,
        quantity: quantityToCheck,
      }).unwrap();
    } catch (error: unknown) {
      throw new Error(
        readCaughtMessage(error, "data", "message") || "Unable to verify live stock. Please retry.",
      );
    }

    const stock = result?.data;

    if (
      result?.success !== true ||
      Number(stock?.product_id) !== id ||
      typeof stock?.available !== "boolean" ||
      !Number.isFinite(stock?.stock_quantity) ||
      stock.stock_quantity < 0
    ) {
      throw new Error("Invalid stock API response. Please retry.");
    }

    if (!stock.available || stock.stock_quantity < quantityToCheck) {
      throw new Error(
        "This product is currently out of stock or the requested quantity is unavailable.",
      );
    }

    return true;
  };

const handleAddToCart = async (e?: React.MouseEvent<HTMLElement>) => {
    if (!product || !mainPurchaseAvailable) return;

    if (hasToken !== true) {
      router.push(getLoginPath());
      return;
    }

    if (e) {
      fireRipple(e);

      flyImageToCart(
        mainImageBoxRef.current,
        gallery[activeImage] || product.image,
      );
    }

    try {
      await checkFreshStock(
        Number(product.id),
        quantity,
        selectedAllowsPurchaseWithoutStock,
      );

      const payload: any = {
        product_id: product.id,
        quantity,
      };

      await addToCart(payload).unwrap();

      setIsAddedToCart(true);

      dispatch(
        showToast({
          message: `${product.name} added to cart successfully! 🛒`,
          type: "success",
        }),
      );

      if (mountedRef.current) {
        if (cartFeedbackTimer.current !== null) clearTimeout(cartFeedbackTimer.current);
        cartFeedbackTimer.current = setTimeout(() => {
          cartFeedbackTimer.current = null;
          setIsAddedToCart(false);
        }, 3000);
      }
    } catch (error: unknown) {
      dispatch(
        showToast({
          message:
            readCaughtMessage(error, "data", "message") ||
            readCaughtMessage(error, "message") ||
            "Failed to add item to cart",
          type: "error",
        }),
      );
    }
  };

const handleReadMore = () => {
    setActiveTab("details");

    if (scrollFrame.current !== null) cancelAnimationFrame(scrollFrame.current);
    scrollFrame.current = requestAnimationFrame(() => {
      scrollFrame.current = null;
      detailsSectionRef.current?.scrollIntoView({
        behavior: "smooth",
        block: "start",
      });
    });
  };

const handleViewComboDetails = () => {
    setActiveTab("combo");

    if (scrollFrame.current !== null) cancelAnimationFrame(scrollFrame.current);
    scrollFrame.current = requestAnimationFrame(() => {
      scrollFrame.current = null;
      detailsSectionRef.current?.scrollIntoView({
        behavior: "smooth",
        block: "start",
      });
    });
  };

const handleSelectComboImage = (imageUrl: string) => {
    const index = gallery.indexOf(imageUrl);

    if (index >= 0) {
      setActiveImage(index);
    }
  };

const handleBuyNow = async () => {
    if (!product || !mainPurchaseAvailable || isBuyingNow) return;

    if (hasToken !== true) {
      router.push(getLoginPath());
      return;
    }

    const productId = Number(product.id);

    const selectedVariantProductId = Number(
      selectedVariant?.product_id ?? selectedVariant?.id,
    );

    const variantId =
      !isMainProductSelected &&
      selectedVariant &&
      selectedVariantProductId === productId
        ? (selectedVariant.product_variant_id ?? selectedVariant.variant_id)
        : undefined;

    if (!Number.isFinite(productId) || productId <= 0) {
      dispatch(
        showToast({
          message: "Invalid product selected",
          type: "error",
        }),
      );
      return;
    }

    const purchaseQty = Math.max(1, Math.floor(Number(quantity) || 1));

    setIsBuyingNow(true);

    try {
      await checkFreshStock(
        productId,
        purchaseQty,
        selectedAllowsPurchaseWithoutStock,
      );

      const params = new URLSearchParams({
        checkout_type: "buy_now",
        product_id: String(productId),
        quantity: String(purchaseQty),
      });

      if (variantId != null) {
        params.set("variant_id", String(variantId));
      }

      router.push(`/checkout?${params.toString()}`);
    } catch (error: unknown) {
      dispatch(
        showToast({
          message:
            readCaughtMessage(error, "data", "message") ||
            readCaughtMessage(error, "message") ||
            "Failed to process your order",
          type: "error",
        }),
      );
    } finally {
      setIsBuyingNow(false);
    }
  };

const handleNotifySubmit = async () => {
    if (!product || isNotifyLoading) return;

    if (hasToken !== true) {
      router.push(getLoginPath());
      return;
    }

    try {
      const result = await notifyProduct({
        product_id: Number(product.id),
      }).unwrap();

      dispatch(
        showToast({
          message:
            result?.message ||
            `We'll notify you when ${product.name} is back in stock!`,
          type: "success",
        }),
      );
    } catch (error: unknown) {
      dispatch(
        showToast({
          message:
            readCaughtMessage(error, "data", "message") ||
            readCaughtMessage(error, "message") ||
            "Failed to request notification.",
          type: "error",
        }),
      );
    }
  };

const {
    isFullscreen,
    fullscreenImageIndex,
    setFullscreenImageIndex,
    openFullscreen,
    closeFullscreen,
    nextFullscreenImage,
    prevFullscreenImage,
    isReviewViewerOpen,
    reviewViewerImages,
    reviewViewerIndex,
    setReviewViewerIndex,
    openReviewViewer,
    closeReviewViewer,
    nextReviewViewerImage,
    prevReviewViewerImage,
  } = useProductMedia(gallery);

const hasUserReviewed = useMemo(() => {
    if (!currentUserId) return false;

    return reviewsList.some(
      (review: any) => String(review?.user?.id ?? "") === String(currentUserId),
    );
  }, [reviewsList, currentUserId]);

const reviewableOrderLine = useMemo(() => {
    if (!apiProduct?.id || !Array.isArray(myOrdersData?.data)) {
      return null;
    }

    const lines: any[] = [];

    const collectLine = (item: any, parent: any = null) => {
      if (!item || typeof item !== "object") return;

      const lineId = item?.line_id ?? item?.order_line_id ?? item?.id ?? null;

      const productId = item?.product_id ?? item?.product?.id ?? null;

      const orderId =
        item?.order_id ??
        item?.order?.id ??
        parent?.order_id ??
        parent?.id ??
        null;

      if (lineId != null && productId != null && orderId != null) {
        lines.push({
          ...item,
          line_id: lineId,
          order_line_id: lineId,
          product_id: productId,
          order_id: orderId,
          order_status: item?.order_status ?? parent?.order_status ?? null,
          delivery_status:
            item?.delivery_status ?? parent?.delivery_status ?? null,
        });
      }

      const nested =
        item?.order_lines ??
        item?.orderLines ??
        item?.lines ??
        item?.items ??
        null;

      if (Array.isArray(nested)) {
        nested.forEach((child: any) => collectLine(child, item));
      }
    };

    myOrdersData.data.forEach((item: any) => collectLine(item));

    const matching = lines.filter(
      (line) => String(line.product_id) === String(apiProduct.id),
    );

    const delivered = matching.find(
      (line) =>
        String(
          line.delivery_status ?? line.order_status ?? "",
        ).toLowerCase() === "delivered",
    );

    return delivered || matching[0] || null;
  }, [myOrdersData, apiProduct?.id]);

const canReview = Boolean(currentUserId && reviewableOrderLine);

const handleReviewSubmit = async (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();

    if (!reviewTitle.trim()) {
      dispatch(
        showToast({
          message: "Please write your review.",
          type: "error",
        }),
      );

      return;
    }

    if (!product || !currentUserId || !reviewableOrderLine) {
      return;
    }

    setIsSubmittingReview(true);

    try {
      const payload = {
        rating: Number(reviewRating),
        review_text: reviewTitle.trim(),
        order_id: Number(reviewableOrderLine.order_id),
        order_line_id: Number(reviewableOrderLine.line_id),
        product_id: Number(reviewableOrderLine.product_id || product.id),
        images: reviewImages,
      };

      const result = await addRatingReview(payload).unwrap();

      dispatch(
        showToast({
          message: result?.message || "Review submitted successfully.",
          type: "success",
        }),
      );

      setReviewName("");
      setReviewEmail("");
      setReviewTitle("");
      setReviewRating(5);
      setReviewImages([]);

      await refetchProduct();
      await refetchOrders();
    } catch (error: unknown) {
      dispatch(
        showToast({
          message: readCaughtMessage(error, "data", "message") || "Failed to submit review.",
          type: "error",
        }),
      );
    } finally {
      setIsSubmittingReview(false);
    }
  };

const handleReviewImageUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (!e.target.files) return;

    const files = Array.from(e.target.files);

    setReviewImages((prev) => [...prev, ...files.slice(0, 5 - prev.length)]);

    e.target.value = "";
  };

const removeReviewImage = (index: number) => {
    setReviewImages((prev) => prev.filter((_, i) => i !== index));
  };

const { similarProducts, sortedSimilarProducts, visibleSimilarProducts } = useRelatedProducts(categoryProductsData, product?.id, userAccountType, relatedSortOption);

const [relatedBusyId, setRelatedBusyId] = useState<string | null>(null);

const addRelatedToCart = async (
    item: (typeof similarProducts)[number],
    buyNow: boolean,
  ) => {
    if (hasToken !== true) {
      router.push(getLoginPath());
      return;
    }

    if (!item.inStock || relatedBusyId !== null) return;

    setRelatedBusyId(String(item.id));

    try {
      await checkFreshStock(
        Number(item.id),
        1,
        Boolean(item.allowedWithoutStock),
      );

      await addToCart({
        product_id: item.id,
        quantity: 1,
      }).unwrap();

      if (buyNow) {
        setShowRelatedSheet(false);

        router.push(
          `/checkout?${new URLSearchParams({
            product_id: String(item.id),
            quantity: "1",
          }).toString()}`,
        );
      } else {
        dispatch(
          showToast({
            message: `${item.name} added to cart successfully`,
            type: "success",
          }),
        );
      }
    } catch (error: unknown) {
      dispatch(
        showToast({
          message:
            readCaughtMessage(error, "data", "message") ||
            readCaughtMessage(error, "message") ||
            "Could not add this product",
          type: "error",
        }),
      );
    } finally {
      setRelatedBusyId(null);
    }
  };

useEffect(() => {
    if (!isProductLoading && !product && !error) {
      dispatch(
        showToast({
          message: "Product not found",
          type: "error",
        }),
      );

      router.push("/products");
    }
  }, [isProductLoading, product, error, router, dispatch]);

return {
    product,
    gallery,
    MAX_VISIBLE_THUMBS,
    setShowAllThumbnails,
    setActiveImage,
    activeImage,
    mainImageBoxRef,
    openFullscreen,
    selectedVariantId,
    isCombo,
    comboItems,
    handleWishlistToggle,
    isWishlistLoading,
    isWishlisted,
    setShowRelatedSheet,
    isDistributorApp,
    userAccountType,
    quantity,
    handleReadMore,
    handleViewComboDetails,
    handleSelectComboImage,
    comboTotals,
    hasVariants,
    variantAttributeOptions,
    selectedVariantAttributes,
    handleAttributeSelect,
    displayVariants,
    isMainProductSelected,
    handleSelectVariant,
    selectedVariant,
    mainPurchaseAvailable,
    handleBuyNow,
    isBuyingNow,
    handleAddToCart,
    isAddedToCart,
    handleNotifySubmit,
    isNotifyLoading,
    activeProductSlug,
    apiProduct,
    manufacturingInfo,
    setShowManufacturingInfo,
    detailsSectionRef,
    setActiveTab,
    activeTab,
    router,
    buildProductPath,
    currentUserId,
    getLoginPath,
    canReview,
    hasUserReviewed,
    handleReviewSubmit,
    reviewName,
    setReviewName,
    reviewEmail,
    setReviewEmail,
    setReviewRating,
    reviewRating,
    reviewTitle,
    setReviewTitle,
    handleReviewImageUpload,
    reviewImages,
    removeReviewImage,
    isSubmittingReview,
    reviewsList,
    openReviewViewer,
    reviewsSummary,
    similarProducts,
    relatedSortOption,
    setRelatedSortOption,
    visibleSimilarProducts,
    toggleWishlist,
    wishlistState,
    relatedBusyId,
    addRelatedToCart,
    isFullscreen,
    closeFullscreen,
    fullscreenImageIndex,
    prevFullscreenImage,
    nextFullscreenImage,
    setFullscreenImageIndex,
    isReviewViewerOpen,
    reviewViewerImages,
    closeReviewViewer,
    reviewViewerIndex,
    prevReviewViewerImage,
    nextReviewViewerImage,
    setReviewViewerIndex,
    showManufacturingInfo,
    showAllThumbnails,
    showRelatedSheet,
    sortedSimilarProducts,
    isProductLoading,
  };
}

export type ProductDetailModel = ReturnType<typeof useProductDetail>;
export type ProductDetailViewModel = Omit<ProductDetailModel, 'product'> & { product: NonNullable<ProductDetailModel['product']>; specification: ReturnType<typeof parseJsonObject>; specRows: (string | number)[][]; contentTabs: [string, string][]; showBAPricing: boolean };

"use client";
import { useMemo } from "react";
import { PLACEHOLDER, distributorOfferPrice, generateSlugFromName, getAverageRating, getTotalReviews, isPurchaseAllowedWithoutStock, parseJsonObject } from "./support";
import { distributorRetailReference } from "./pricing";

export function useProductModel(apiProduct: any, userAccountType: "retail" | "distributor") {
const apiComboProducts: any[] = useMemo(() => Array.isArray(apiProduct?.combo_products)
    ? apiProduct.combo_products
    : [], [apiProduct?.combo_products]);

const isCombo =
    String(apiProduct?.product_type ?? "").toLowerCase() === "combo" &&
    apiComboProducts.length > 0;

const comboItems = useMemo(() => {
    if (!isCombo) return [];

    const isDistributorUser = userAccountType === "distributor";

    return apiComboProducts.map((c: any) => {
      const imgs: string[] = Array.isArray(c?.images)
        ? [...c.images]
            .sort(
              (a: any, b: any) =>
                Number(a?.sort_order ?? 0) - Number(b?.sort_order ?? 0),
            )
            .map((img: any) => img?.image_url || img?.image)
            .filter(Boolean)
        : [];

      const primary =
        c?.images?.find((img: any) => img?.is_primary)?.image_url ||
        imgs[0] ||
        PLACEHOLDER;

      const galleryImages: string[] = Array.from(
        new Set([primary, ...imgs].filter(Boolean)),
      );

      const price = isDistributorUser
        ? distributorOfferPrice(
            c,
            Number(c?.distributor_price || c?.retail_price || 0),
          )
        : Number(c?.retail_price || 0);

      // Distributor: struck-through reference price = RETAIL price.
      const mrp = isDistributorUser
        ? distributorRetailReference(c)
        : Number(c?.retail_mrp || 0);

      const commission =
        c?.commission_value !== null &&
        c?.commission_value !== undefined &&
        Number.isFinite(Number(c.commission_value))
          ? Math.max(0, Number(c.commission_value))
          : null;

      return {
        id: c?.id,
        name: String(c?.name ?? ""),
        slug: c?.slug || generateSlugFromName(String(c?.name ?? "")),
        productCode: c?.product_code || "",
        primaryImage: primary as string,
        images: galleryImages,
        category: c?.category?.name || "",
        subcategory: c?.subcategory?.name || "",
        brand: c?.brand?.name || "",
        brandLogo: c?.brand?.logo || "",
        taxName: c?.tax_category?.name || "",
        taxRate:
          c?.tax_category?.rate !== undefined &&
          c?.tax_category?.rate !== null &&
          Number.isFinite(Number(c.tax_category.rate))
            ? Number(c.tax_category.rate)
            : null,
        price,
        mrp,
        commission,
      };
    });
  }, [isCombo, apiComboProducts, userAccountType]);

const manufacturingInfo = useMemo(() => {
    const spec = parseJsonObject(apiProduct?.specification);

    return {
      country: String(
        spec["Country of Origin:"] ??
          spec["Country of Origin"] ??
          spec["Country of Manufacture"] ??
          "India",
      ),

      manufacturedBy: String(
        spec["Manufactured By:"] ?? spec["Manufactured By"] ?? "Not available",
      ),

      marketedBy: String(
        spec["Marketed By:"] ?? spec["Marketed By"] ?? "Not available",
      ),
    };
  }, [apiProduct?.specification]);

const reviewsSummary =
    apiProduct?.reviews_summary ?? apiProduct?.reviews?.summary ?? null;

const reviewsList: any[] = useMemo(() => Array.isArray(apiProduct?.reviews?.data)
    ? apiProduct.reviews.data
    : Array.isArray(apiProduct?.reviews)
      ? apiProduct.reviews
      : [], [apiProduct?.reviews]);

const product = useMemo(() => apiProduct
    ? {
        id: apiProduct.id,

        name: apiProduct.name,

        slug: apiProduct.slug || generateSlugFromName(apiProduct.name),

        description: apiProduct.description,

        specification: apiProduct.specification,

        category: apiProduct.category?.name || "Uncategorized",

        categoryId: apiProduct.category_id || apiProduct.category?.id,

        productCode: apiProduct.product_code,

        retailMrp: Number(apiProduct.retail_mrp || 0),

        distributorMrp: Number(apiProduct.distributor_mrp || 0),

        retailPrice: Number(apiProduct.retail_price || 0),

        distributorPrice: Number(apiProduct.distributor_price || 0),

        commissionValue:
          apiProduct.commission_value !== null &&
          apiProduct.commission_value !== undefined &&
          Number.isFinite(Number(apiProduct.commission_value))
            ? Math.max(0, Number(apiProduct.commission_value))
            : null,

        price:
          userAccountType === "distributor"
            ? distributorOfferPrice(
                apiProduct,
                Number(
                  apiProduct.distributor_price || apiProduct.retail_price || 0,
                ),
              )
            : Number(apiProduct.retail_price || 0),

        // Distributor: struck-through price = RETAIL price.
        mrp:
          userAccountType === "distributor"
            ? distributorRetailReference(apiProduct)
            : Number(apiProduct.retail_mrp || 0),

        originalPrice:
          userAccountType === "distributor"
            ? distributorRetailReference(apiProduct)
            : Number(apiProduct.retail_mrp || 0),

        discount:
          userAccountType === "distributor"
            ? (() => {
                const mrp = distributorRetailReference(apiProduct);

                const price = distributorOfferPrice(
                  apiProduct,
                  Number(
                    apiProduct.distributor_price ||
                      apiProduct.retail_price ||
                      0,
                  ),
                );

                return mrp > price && price > 0
                  ? Math.round(((mrp - price) / mrp) * 100)
                  : null;
              })()
            : (() => {
                const mrp = Number(apiProduct.retail_mrp || 0);

                const price = Number(apiProduct.retail_price || 0);

                return mrp > price && price > 0
                  ? Math.round(((mrp - price) / mrp) * 100)
                  : null;
              })(),

        image:
          apiProduct.primary_image_url ||
          apiProduct.images?.[0]?.image_url ||
          PLACEHOLDER,

        images: apiProduct.images || [],

        // Correct rating source from API.
        rating: getAverageRating(reviewsSummary),

        // Correct review count from API.
        reviews: getTotalReviews(reviewsSummary),

        allowedWithoutStock: isPurchaseAllowedWithoutStock(apiProduct),
        inStock:
          isPurchaseAllowedWithoutStock(apiProduct) ||
          Number(apiProduct.stock_quantity ?? 0) > 0,

        stockQuantity: Number(apiProduct.stock_quantity ?? 0),

        isLowStock:
          !isPurchaseAllowedWithoutStock(apiProduct) &&
          Number(apiProduct.stock_quantity ?? 0) > 0 &&
          Number(apiProduct.stock_quantity ?? 0) <=
            Number(apiProduct.low_stock_threshold ?? 10),

        lowStockThreshold: Number(apiProduct.low_stock_threshold || 10),
      }
    : null, [apiProduct, userAccountType, reviewsSummary]);

const productGallery = useMemo(() => {
    if (!product) return [];

    const images = Array.isArray(product.images)
      ? product.images
          .map((img: any) => img?.image_url || img?.image)
          .filter(Boolean)
      : [];

    return Array.from(
      new Set([product.image, ...images].filter(Boolean)),
    ) as string[];
  }, [product]);

const comboTotals = useMemo(() => {
    if (!isCombo) return null;

    const sumPrice = comboItems.reduce((acc, i) => acc + i.price, 0);
    const sumMrp = comboItems.reduce((acc, i) => acc + i.mrp, 0);
    const sumCommission = comboItems.reduce(
      (acc, i) => acc + (i.commission ?? 0),
      0,
    );

    const comboPrice = product?.price ?? 0;
    const savings = sumPrice > comboPrice ? sumPrice - comboPrice : 0;

    return {
      sumPrice,
      sumMrp,
      sumCommission,
      comboPrice,
      savings,
    };
  }, [isCombo, comboItems, product?.price]);


return {
    isCombo,
    comboItems,
    manufacturingInfo,
    reviewsSummary,
    reviewsList,
    product,
    productGallery,
    comboTotals,
  };
}
export type ProductModel = ReturnType<typeof useProductModel>;

"use client";
import { useMemo } from "react";
import { parseJsonObject, isPurchaseAllowedWithoutStock, getVariantImageUrl, getVariantGalleryImages } from "./support";
import type { ProductModel } from "./useProductModel";

export function useProductVariants(apiProduct: any, product: ProductModel['product'], productGallery: string[], selectedVariantId: number | string | null) {
const variantEntries = useMemo(() => {
    if (!Array.isArray(apiProduct?.variants)) return [];

    return apiProduct.variants
      .filter((variant: any) => variant?.is_active !== false)
      .map((variant: any) => ({
        ...variant,
        parsedAttributes: parseJsonObject(variant?.attributes),
      }));
  }, [apiProduct?.variants]);

const hasVariants = variantEntries.length > 0;

const apiAvailableAttributes = useMemo(() => parseJsonObject(
    apiProduct?.available_attributes,
  ), [apiProduct?.available_attributes]);

const variantAttributeOptions = useMemo<Record<string, string[]>>(() => {
    const result: Record<string, string[]> = {};

    Object.entries(apiAvailableAttributes).forEach(([key, values]) => {
      if (Array.isArray(values)) {
        result[key] = values.map((value) => String(value)).filter(Boolean);
      }
    });

    if (Object.keys(result).length === 0) {
      variantEntries.forEach((variant: any) => {
        const attrs = variant?.parsedAttributes || {};

        Object.entries(attrs).forEach(([key, value]) => {
          if (!result[key]) {
            result[key] = [];
          }

          const stringValue = String(value);

          if (stringValue && !result[key].includes(stringValue)) {
            result[key].push(stringValue);
          }
        });
      });
    }

    return result;
  }, [apiAvailableAttributes, variantEntries]);

const displayVariants = useMemo(() => {
    if (!product) return [];

    const mainProduct = {
      id: "main-product",

      isMainProduct: true,

      slug: product.slug,

      hax_color: /rose[\s-]*gold/i.test(product.name)
        ? "#E3AF90"
        : /steel|silver/i.test(product.name)
          ? "#C0C0C0"
          : /gold/i.test(product.name)
            ? "#D6AD60"
            : "#B6B6B6",

      name: product.name,

      primary_image_url: product.image,

      images: productGallery.map((image: string, index: number) => ({
        id: `main-${index}`,
        image_url: image,
        is_primary: index === 0,
      })),

      parsedAttributes: {},

      attributes: {},
    };

    return [mainProduct, ...variantEntries];
  }, [product, productGallery, variantEntries]);

const isMainProductSelected = selectedVariantId === null;

const selectedVariant = useMemo(() => {
    if (isMainProductSelected) return null;

    return (
      variantEntries.find(
        (variant: any) => String(variant.id) === String(selectedVariantId),
      ) || null
    );
  }, [isMainProductSelected, selectedVariantId, variantEntries]);

const selectedAllowsPurchaseWithoutStock = selectedVariant
    ? isPurchaseAllowedWithoutStock(selectedVariant) ||
      (selectedVariant.allowed_purchsed == null &&
        Boolean(product?.allowedWithoutStock))
    : Boolean(product?.allowedWithoutStock);

const mainPurchaseAvailable =
    selectedAllowsPurchaseWithoutStock ||
    (selectedVariant?.stock_quantity != null
      ? Number(selectedVariant.stock_quantity) > 0
      : Boolean(product?.stockQuantity && product.stockQuantity > 0));

const selectedVariantImage = selectedVariant
    ? getVariantImageUrl(selectedVariant)
    : null;

const selectedVariantGallery = useMemo(() => {
    if (!selectedVariant) return [];

    return getVariantGalleryImages(selectedVariant);
  }, [selectedVariant]);

const gallery = useMemo(() => {
    if (!product) return [];

    if (!isMainProductSelected && selectedVariantGallery.length > 0) {
      return selectedVariantGallery;
    }

    if (!isMainProductSelected && selectedVariantImage) {
      return [selectedVariantImage];
    }

    return productGallery;
  }, [
    product,
    isMainProductSelected,
    selectedVariantGallery,
    selectedVariantImage,
    productGallery,
  ]);


return {
    variantEntries,
    hasVariants,
    variantAttributeOptions,
    displayVariants,
    isMainProductSelected,
    selectedVariant,
    selectedAllowsPurchaseWithoutStock,
    mainPurchaseAvailable,
    gallery,
  };
}

"use client";
import { useMemo } from "react";
import { PLACEHOLDER, distributorOfferPrice, generateSlugFromName, getAverageRating, getTotalReviews, isPurchaseAllowedWithoutStock } from "./support";
import { distributorRetailReference } from "./pricing";

export type RelatedSort = "recommended" | "price_asc" | "price_desc" | "newest";
export function useRelatedProducts(categoryProductsData: any, productId: number | string | undefined, userAccountType: "retail" | "distributor", relatedSortOption: RelatedSort) {
const categoryProductList: any[] = useMemo(() => Array.isArray(categoryProductsData?.data)
    ? categoryProductsData.data
    : Array.isArray(categoryProductsData?.data?.data)
      ? categoryProductsData.data.data
      : Array.isArray(categoryProductsData)
        ? categoryProductsData
        : [], [categoryProductsData]);

const similarProducts = useMemo(() => categoryProductList
    .filter((p: any) => String(p.id) !== String(productId))
    .slice(0, 10)
    .map((p: any) => {
      const distributor = userAccountType === "distributor";

      const price = distributor
        ? distributorOfferPrice(
            p,
            Number(p.distributor_price || p.retail_price || 0),
          )
        : Number(p.retail_price || 0);

      // Distributor: struck-through reference price = RETAIL price.
      const mrp = distributor
        ? distributorRetailReference(p)
        : Number(p.retail_mrp || 0);

      /*
       * IMPORTANT:
       * Category API returns reviews_summary directly.
       * Do not rely only on reviews.summary.
       */
      const reviewSummary = p?.reviews_summary ?? p?.reviews?.summary ?? {};

      const rating = getAverageRating(reviewSummary);

      const totalReviews = getTotalReviews(reviewSummary);

      return {
        id: p.id,

        name: p.name,

        slug: p.slug || generateSlugFromName(p.name),

        category: p.category?.name || p.category_name || "",

        brand: p.brand_name || p.brandName || p.brand || "",

        description: p.short_description || p.description || "",

        stockQuantity: Number(p.stock_quantity || 0),

        lowStockThreshold: Number(p.low_stock_threshold || 0),

        peopleBought: Number(
          p.people_bought_this_week || p.peopleBoughtThisWeek || 0,
        ),

        badge:
          p.badge ||
          (p.is_deal_of_the_day
            ? "Deal of the Day"
            : p.sale_type === "today_best"
              ? "Best Seller"
              : ""),

        price,

        commissionValue:
          p.commission_value !== null &&
          p.commission_value !== undefined &&
          Number.isFinite(Number(p.commission_value))
            ? Math.max(0, Number(p.commission_value))
            : null,

        originalPrice: mrp,

        discount:
          mrp > price && price > 0
            ? Math.round(((mrp - price) / mrp) * 100)
            : null,

        image:
          p.primary_image_url ||
          p.images?.find((img: any) => img?.is_primary)?.image_url ||
          p.images?.[0]?.image_url ||
          PLACEHOLDER,

        // Correct rating mapping.
        rating,

        // Correct review count mapping.
        reviews: totalReviews,

        allowedWithoutStock: isPurchaseAllowedWithoutStock(p),
        inStock:
          isPurchaseAllowedWithoutStock(p) || Number(p.stock_quantity || 0) > 0,

        createdAt: p.created_at || p.createdAt || null,
      };
    }), [categoryProductList, productId, userAccountType]);

const sortedSimilarProducts = useMemo(() => {
    const list = [...similarProducts];

    switch (relatedSortOption) {
      case "price_asc":
        return list.sort((a, b) => a.price - b.price);

      case "price_desc":
        return list.sort((a, b) => b.price - a.price);

      case "newest":
        return list.sort((a, b) => {
          const aTime = a.createdAt ? new Date(a.createdAt).getTime() : 0;

          const bTime = b.createdAt ? new Date(b.createdAt).getTime() : 0;

          return bTime - aTime;
        });

      default:
        return list;
    }
  }, [similarProducts, relatedSortOption]);

const visibleSimilarProducts = useMemo(() => sortedSimilarProducts.slice(0, 12), [sortedSimilarProducts]);


return { similarProducts, sortedSimilarProducts, visibleSimilarProducts };
}

