/* =========================================================
   PROFILE SIDEBAR
========================================================= */

export default function ProfileSidebar({
    name,
    email,
    rating,
    activeTab,
    onTabChange,
    accountType = "Standard",
    earningsData,
}: ProfileSidebarProps) {
    const dispatch = useDispatch();
    const { logout } = useLogout();

    /* =========================================================
       TOKEN CHECK
    ========================================================= */

    const { hasToken } = useTokenCheck();

    /* =========================================================
       PROFILE API

       Guest user:
       skip=true

       Logged-in user:
       API runs normally
    ========================================================= */

    const {
        data: profileData,
    } = useGetUserProfileQuery(undefined, {
        skip: hasToken !== true,
    });

    const userProfile = profileData?.user;

    const profileImage = userProfile?.profile_picture;

    const profileName = userProfile?.full_name || name;

    const profileEmail = userProfile?.email || email;

    /* =========================================================
       STATES
    ========================================================= */

    const [showLogoutModal, setShowLogoutModal] =
        useState(false);

    const [isLoggingOut, setIsLoggingOut] =
        useState(false);

    /* =========================================================
       ORDERS API

       Guest user:
       skip=true
    ========================================================= */

    const {
        data: ordersData,
        isLoading: ordersLoading,
    } = useGetMyOrdersQuery(undefined, {
        skip: hasToken !== true,
    });

    const orderCount =
        ordersData?.data?.length || 0;

    /* =========================================================
       WISHLIST API

       Guest user:
       skip=true
    ========================================================= */

    const {
        data: wishlistData,
        isLoading: wishlistLoading,
    } = useGetWishlistQuery(undefined, {
        skip: hasToken !== true,
    });

    const wishlistCount =
        wishlistData?.data?.items?.length ||
        wishlistData?.data?.length ||
        0;

    /* =========================================================
       ACCOUNT TYPE
    ========================================================= */

    const isDistributor =
        accountType?.toLowerCase() === "distributor";

    /* =========================================================
       NAVIGATION ITEMS
    ========================================================= */

    const navItems = [
        {
            icon: User,
            label: "Overview",
            tab: "overview",
        },
        {
            icon: Package,
            label: "My Orders",
            tab: "orders",
            badge: "0",
        },
        {
            icon: Heart,
            label: "Wishlist",
            tab: "wishlist",
            badge: "0",
        },
        {
            icon: MapPin,
            label: "Manage Address",
            tab: "address",
        },
        {
            icon: Settings,
            label: "Account Settings",
            tab: "settings",
        },
    ];

    /* =========================================================
       DISTRIBUTOR NAVIGATION
    ========================================================= */

    const distributorNavItems = [
        {
            icon: User,
            label: "Overview",
            tab: "overview",
        },
        {
            icon: BarChart3,
            label: "Earnings",
            tab: "earning",
        },
        {
            icon: Package,
            label: "My Orders",
            tab: "orders",
            badge: "0",
        },
        {
            icon: Heart,
            label: "Wishlist",
            tab: "wishlist",
            badge: "0",
        },
        {
            icon: MapPin,
            label: "Manage Address",
            tab: "address",
        },
        {
            icon: Settings,
            label: "Account Settings",
            tab: "settings",
        },
    ];

    const finalNavItems = isDistributor
        ? distributorNavItems
        : navItems;

    /* =========================================================
       UPDATED NAV ITEMS
    ========================================================= */

    const updatedNavItems = finalNavItems.map((item) => {
                if (item.tab === "orders") {
                    return {
                        ...item,
                        badge:
                            hasToken !== true
                                ? "0"
                                : ordersLoading
                                    ? "..."
                                    : String(orderCount),
                    };
                }

                if (item.tab === "wishlist") {
                    return {
                        ...item,
                        badge:
                            hasToken !== true
                                ? "0"
                                : wishlistLoading
                                    ? "..."
                                    : String(wishlistCount),
                    };
                }

                return item;
            });

    /* =========================================================
       TAB NAVIGATION
    ========================================================= */

    const handleNavigation = (tab: string) => {
        onTabChange(tab);
    };

    /* =========================================================
       LOGOUT
    ========================================================= */

    const handleLogoutClick = () => {
        setShowLogoutModal(true);
    };

    const closeLogoutModal = () => {
        if (!isLoggingOut) {
            setShowLogoutModal(false);
        }
    };

    const handleLogoutConfirm = async () => {
        setIsLoggingOut(true);

        try {
            await logout({
                redirectTo: "/",
                callApi: true,
                clearReduxState: true,
                clearPersistedState: true,

                onSuccess: () => {
                    dispatch(
                        showToast({
                            message:
                                "Successfully logged out! See you soon 👋",
                            type: "success",
                        }),
                    );

                    setIsLoggingOut(false);
                    setShowLogoutModal(false);
                },

                onError: () => {
                    dispatch(
                        showToast({
                            message:
                                "Logout failed. Please try again.",
                            type: "error",
                        }),
                    );

                    setIsLoggingOut(false);
                    setShowLogoutModal(false);
                },
            });
        } catch {
            dispatch(
                showToast({
                    message:
                        "Something went wrong. Please try again.",
                    type: "error",
                }),
            );

            setIsLoggingOut(false);
            setShowLogoutModal(false);
        }
    };

    /* =========================================================
       FORMAT CURRENCY
    ========================================================= */

    const formatCurrency = (
        amount: number = 0,
    ) => {
        return new Intl.NumberFormat("en-IN", {
            style: "currency",
            currency: "INR",
            maximumFractionDigits: 0,
        }).format(amount);
    };

    /* =========================================================
       RENDER
    ========================================================= */

    return (
        <>
            <LogoutModal
