                                    className="text-[10px] font-medium tracking-wide text-[#2B2420]"
                                    style={{
                                        fontFamily: "Jost, sans-serif",
                                    }}
                                >
                                    ✨ Premium Benefits
                                </p>

                                <p
                                    className="text-[9px] tracking-wide text-[#8a7f6e]"
                                    style={{
                                        fontFamily: "Jost, sans-serif",
                                    }}
                                >
