                                        ? "Exclusive distributor rewards & offers"
                                        : "Unlock exclusive rewards & offers"}
                                </p>
                            </div>

                            <button
                                type="button"
                                className="text-[10px] font-semibold text-[#C9A227] transition-colors hover:text-[#92403F]"
