/* ========================================================================= */
/* HELPERS                                                                   */
/* ========================================================================= */

export const getFirstName = (name?: string) => {
  if (!name) return "Guest";

  return name.trim().split(" ")[0] || "Guest";
};


export const getInitials = (name?: string) => {
  if (!name) return "GU";

  const parts = name.trim().split(" ");

  if (parts.length === 1) {
    return parts[0].slice(0, 2).toUpperCase();
  }

  return `${parts[0]?.[0] || ""}${parts[parts.length - 1]?.[0] || ""
    }`.toUpperCase();
};


export const formatCurrency = (value: unknown) => {
  return `₹${Number(value || 0).toLocaleString("en-IN")}`;
};


export const renderRatingStars = (rating: number) => {
  const value = Math.max(
    0,
    Math.min(5, Math.floor(Number(rating) || 0)),
  );

  return "★".repeat(value) + "☆".repeat(Math.max(0, 5 - value));
};


export const getActivityTime = (timestamp: unknown, createdAt?: string) => {
  if (timestamp) {
    return new Date(Number(timestamp) * 1000).toLocaleTimeString([], {
      hour: "2-digit",
      minute: "2-digit",
      hour12: false,
    });
  }

  if (createdAt) {
    const date = new Date(createdAt);

    if (!Number.isNaN(date.getTime())) {
      return date.toLocaleTimeString([], {
        hour: "2-digit",
        minute: "2-digit",
        hour12: false,
      });
    }
  }

  return "--:--";
};


export const getActivityDate = (timestamp: unknown, createdAt?: string) => {
  if (timestamp) {
    return new Date(Number(timestamp) * 1000).toLocaleDateString(
      "en-IN",
      {
        month: "short",
        day: "numeric",
        year: "numeric",
      },
    );
  }

  if (createdAt) {
    const date = new Date(createdAt);

    if (!Number.isNaN(date.getTime())) {
      return date.toLocaleDateString("en-IN", {
        month: "short",
        day: "numeric",
        year: "numeric",
      });
    }
  }

  return "";
};


