            -translate-y-1/2
            items-center
            justify-center
            rounded-full
            bg-white/95
            text-[#111827]
            shadow-lg
            transition
            hover:scale-105
            lg:flex
            xl:right-5
          "
              >
                <ChevronRight size={19} />
              </button>
            </>
          )}
        </div>

        {/* SLIDER DOTS */}
        {heroSlides.length > 1 && (
          <div className="flex w-full items-center justify-center gap-1.5 py-2 sm:py-3">
            {heroSlides.map((slide, index: number) => (
